"use client";

import * as React from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

gsap.registerPlugin(ScrollTrigger);

export interface ScrollRevealGridProps
  extends React.HTMLAttributes<HTMLDivElement> {
  ref?: React.Ref<HTMLDivElement>;
}

/**
 * Wrapper grid: direct children rise-in on scroll with a grid-aware stagger.
 */
export function ScrollRevealGrid({
  className,
  children,
  ref,
  ...rest
}: ScrollRevealGridProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const cards = gsap.utils.toArray<HTMLElement>(
        Array.from(root.children) as HTMLElement[]
      );
      if (!cards.length) return;
      if (reduced) {
        gsap.set(cards, { y: 0, opacity: 1 });
        return;
      }
      gsap.set(cards, { y: 12, opacity: 0 });
      gsap.to(cards, {
        y: 0,
        opacity: 1,
        duration: 0.35,
        ease: "power2.out",
        stagger: { each: 0.08, grid: "auto", from: "start" },
        scrollTrigger: {
          trigger: root,
          start: "top 80%",
          once: true,
        },
      });
    },
    { dependencies: [reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="scroll-reveal-grid"
      className={cn("grid gap-4 sm:grid-cols-2 lg:grid-cols-3", className)}
      {...rest}
    >
      {children}
    </div>
  );
}

registry/default/fintech/option-chain.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import {
  blackScholes,
  smileIv,
} from "@/registry/default/lib/black-scholes";

/* ------------------------------------------------------------------ */
/* Data model + example-data generator                                  */
/* ------------------------------------------------------------------ */

export interface OptionQuote {
  ltp: number;
  /** Percent change on the day. */
  chg: number;
  oi: number;
  chgOi: number;
  volume: number;
  /** Implied volatility as a fraction, e.g. 0.14. */
  iv: number;
  bid: number;
  ask: number;
  bidQty: number;
  askQty: number;
  delta: number;
  gamma: number;
  theta: number;
  vega: number;
}

export interface OptionChainRow {
  strike: number;
  call: OptionQuote;
  put: OptionQuote;
}

/** Deterministic pseudo-random in [0,1) seeded by strike + salt. */
const prand = (seed: number) => {
  const x = Math.sin(seed * 12.9898) * 43758.5453;
  return x - Math.floor(x);
};

export interface GenerateOptionChainOptions {
  spot: number;
  /** Strike interval. Default 50 (NIFTY). */
  step?: number;
  /** Strikes on each side of ATM. Default 8. */
  span?: number;
  /** Days to expiry. Default 7. */
  dte?: number;
}

/** Coherent example data: premiums and Greeks come from Black-Scholes. */
export function generateOptionChain({
  spot,
  step = 50,
  span = 8,
  dte = 7,
}: GenerateOptionChainOptions): OptionChainRow[] {
  const atm = Math.round(spot / step) * step;
  const t = dte / 365;
  const rows: OptionChainRow[] = [];
  for (let i = -span; i <= span; i++) {
    const strike = atm + i * step;
    const iv = smileIv(spot, strike);
    const quote = (side: "call" | "put"): OptionQuote => {
      const g = blackScholes({ s: spot, k: strike, t, iv, side });
      const salt = strike + (side === "call" ? 1 : 2) * 1000 + dte;
      const near = Math.exp(-Math.abs(strike - spot) / (step * 4));
      const ltp = Math.max(0.05, g.price);
      const spread = Math.max(0.05, ltp * 0.004 + 0.05);
      return {
        ltp,
        chg: (prand(salt) - (side === "call" ? 0.45 : 0.55)) * 18,
        oi: Math.round((0.4 + near) * (1.5 + prand(salt + 1)) * 2_000_000),
        chgOi: Math.round((prand(salt + 2) - 0.45) * 900_000),
        volume: Math.round((0.3 + near) * (1 + prand(salt + 3)) * 1_500_000),
        iv,
        bid: ltp - spread / 2,
        ask: ltp + spread / 2,
        bidQty: Math.round((1 + prand(salt + 4) * 9) * 75),
        askQty: Math.round((1 + prand(salt + 5) * 9) * 75),
        delta: g.delta,
        gamma: g.gamma,
        theta: g.theta,
        vega: g.vega,
      };
    };
    rows.push({ strike, call: quote("call"), put: quote("put") });
  }
  return rows;
}

/* ------------------------------------------------------------------ */
/* Formatting                                                           */
/* ------------------------------------------------------------------ */

const nf0 = new Intl.NumberFormat("en-IN");
const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});
const compactOi = (n: number) =>
  Math.abs(n) >= 100_000
    ? `${(n / 100_000).toFixed(1)}L`
    : Math.abs(n) >= 1_000
      ? `${(n / 1_000).toFixed(1)}K`
      : nf0.format(n);

/* ------------------------------------------------------------------ */
/* Tick cell: restrained directional flash when a value changes         */
/* ------------------------------------------------------------------ */

function TickNum({
  value,
  format = nf2.format,
  className,
}: {
  value: number;
  format?: (n: number) => string;
  className?: string;
}) {
  const reduced = useReducedMotion();
  const prev = React.useRef(value);
  const [dir, setDir] = React.useState<"up" | "down" | null>(null);

  React.useEffect(() => {
    if (reduced || value === prev.current) {
      prev.current = value;
      return;
    }
    setDir(value > prev.current ? "up" : "down");
    prev.current = value;
    const t = setTimeout(() => setDir(null), 600);
    return () => clearTimeout(t);
  }, [value, reduced]);

  return (
    <span
      className={cn(
        "tabular-nums transition-colors duration-500",
        dir === "up" && "text-market-up",
        dir === "down" && "text-market-down",
        className
      )}
    >
      {format(value)}
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Option chain                                                         */
/* ------------------------------------------------------------------ */

export interface OptionOrder {
  side: "call" | "put";
  action: "buy" | "sell";
  strike: number;
  price: number;
}

export interface OptionChainProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "rows"> {
  rows: OptionChainRow[];
  spot: number;
  /** Lot size shown in the depth panel. Default 75 (NIFTY). */
  lotSize?: number;
  expiries?: string[];
  expiry?: string;
  onExpiryChange?: (expiry: string) => void;
  /** Start with Greek columns instead of OI/volume. */
  defaultShowGreeks?: boolean;
  /** Fewer columns for narrow containers. */
  compact?: boolean;
  onOrder?: (order: OptionOrder) => void;
  ref?: React.Ref<HTMLDivElement>;
}

interface ColumnDef {
  key: string;
  label: string;
  cell: (q: OptionQuote) => React.ReactNode;
}

export function OptionChain({
  rows,
  spot,
  lotSize = 75,
  expiries,
  expiry,
  onExpiryChange,
  defaultShowGreeks = false,
  compact = false,
  onOrder,
  className,
  ref,
  ...rest
}: OptionChainProps) {
  const reduced = useReducedMotion();
  const [showGreeks, setShowGreeks] = React.useState(defaultShowGreeks);
  const [expanded, setExpanded] = React.useState<number | null>(null);

  const atmStrike = React.useMemo(() => {
    let best = rows[0]?.strike ?? 0;
    for (const r of rows)
      if (Math.abs(r.strike - spot) < Math.abs(best - spot)) best = r.strike;
    return best;
  }, [rows, spot]);

  const maxOi = React.useMemo(
    () => Math.max(1, ...rows.flatMap((r) => [r.call.oi, r.put.oi])),
    [rows]
  );

  const columns: ColumnDef[] = React.useMemo(() => {
    if (compact)
      return [
        { key: "oi", label: "OI", cell: (q) => compactOi(q.oi) },
        { key: "ltp", label: "LTP", cell: (q) => <TickNum value={q.ltp} /> },
      ];
    if (showGreeks)
      return [
        { key: "delta", label: "Δ", cell: (q) => <TickNum value={q.delta} format={(n) => n.toFixed(2)} /> },
        { key: "gamma", label: "Γ", cell: (q) => <TickNum value={q.gamma} format={(n) => n.toFixed(4)} /> },
        { key: "theta", label: "Θ", cell: (q) => <TickNum value={q.theta} format={(n) => n.toFixed(2)} /> },
        { key: "vega", label: "V", cell: (q) => <TickNum value={q.vega} format={(n) => n.toFixed(2)} /> },
        { key: "ltp", label: "LTP", cell: (q) => <TickNum value={q.ltp} /> },
      ];
    return [
      { key: "oi", label: "OI", cell: (q) => compactOi(q.oi) },
      {
        key: "chgOi",
        label: "Chg OI",
        cell: (q) => (
          <span className={q.chgOi >= 0 ? "text-market-up" : "text-market-down"}>
            {q.chgOi >= 0 ? "+" : ""}
            {compactOi(q.chgOi)}
          </span>
        ),
      },
      { key: "volume", label: "Vol", cell: (q) => compactOi(q.volume) },
      { key: "iv", label: "IV", cell: (q) => `${(q.iv * 100).toFixed(1)}%` },
      { key: "ltp", label: "LTP", cell: (q) => <TickNum value={q.ltp} /> },
      {
        key: "chg",
        label: "Chg%",
        cell: (q) => (
          <TickNum
            value={q.chg}
            format={(n) => `${n >= 0 ? "+" : ""}${n.toFixed(1)}%`}
            className={q.chg >= 0 ? "text-market-up" : "text-market-down"}
          />
        ),
      },
    ];
  }, [compact, showGreeks]);

  const toggleRow = (strike: number) =>
    setExpanded((e) => (e === strike ? null : strike));

  const oiBar = (q: OptionQuote, side: "call" | "put") => ({
    backgroundImage: `linear-gradient(to ${side === "call" ? "left" : "right"}, ${
      side === "call" ? "var(--bid)" : "var(--ask)"
    } ${Math.round((q.oi / maxOi) * 100)}%, transparent ${Math.round((q.oi / maxOi) * 100)}%)`,
  });

  return (
    <div
      ref={ref}
      data-slot="option-chain"
      className={cn(
        "w-full rounded-xl border border-border bg-card text-sm",
        className
      )}
      {...rest}
    >
      {/* Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-3 py-2.5">
        <div className="flex items-center gap-2">
          <span className="text-xs font-medium text-muted-foreground">
            Spot
          </span>
          <TickNum value={spot} className="text-sm font-semibold" />
        </div>
        {expiries && expiries.length > 0 ? (
          <div
            role="tablist"
            aria-label="Expiry"
            className="flex items-center gap-1 rounded-lg bg-muted p-0.5"
          >
            {expiries.map((e) => (
              <button
                key={e}
                role="tab"
                aria-selected={e === expiry}
                onClick={() => onExpiryChange?.(e)}
                className={cn(
                  "rounded-md px-2 py-1 text-xs font-medium transition-colors duration-200",
                  e === expiry
                    ? "bg-background text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {e}
              </button>
            ))}
          </div>
        ) : null}
        {!compact ? (
          <button
            type="button"
            aria-pressed={showGreeks}
            onClick={() => setShowGreeks((g) => !g)}
            className={cn(
              "rounded-md border border-border px-2.5 py-1 text-xs font-medium transition-colors duration-200",
              showGreeks
                ? "bg-primary text-primary-foreground"
                : "text-muted-foreground hover:bg-muted hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            Greeks
          </button>
        ) : null}
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full min-w-max border-collapse text-right text-[13px]">
          <thead>
            <tr className="border-b border-border text-[11px] uppercase tracking-wide text-muted-foreground">
              <th
                colSpan={columns.length}
                className="px-3 pb-1 pt-2 text-center font-medium text-bid"
              >
                Calls
              </th>
              <th className="px-3 pb-1 pt-2 text-center font-medium">Strike</th>
              <th
                colSpan={columns.length}
                className="px-3 pb-1 pt-2 text-center font-medium text-ask"
              >
                Puts
              </th>
            </tr>
            <tr className="border-b border-border text-[11px] text-muted-foreground">
              {columns.map((c) => (
                <th key={`c-${c.key}`} className="px-3 py-1.5 font-medium">
                  {c.label}
                </th>
              ))}
              <th className="px-3 py-1.5 text-center font-medium">₹</th>
              {[...columns].reverse().map((c) => (
                <th key={`p-${c.key}`} className="px-3 py-1.5 font-medium">
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => {
              const isAtm = row.strike === atmStrike;
              const callItm = row.strike < spot;
              const putItm = row.strike > spot;
              const isOpen = expanded === row.strike;
              return (
                <React.Fragment key={row.strike}>
                  <tr
                    tabIndex={0}
                    role="button"
                    aria-expanded={isOpen}
                    aria-label={`Strike ${row.strike}, ${isAtm ? "at the money, " : ""}call ${nf2.format(row.call.ltp)}, put ${nf2.format(row.put.ltp)}`}
                    onClick={() => toggleRow(row.strike)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        toggleRow(row.strike);
                      }
                    }}
                    className={cn(
                      "cursor-pointer border-b border-border/60 transition-colors duration-150",
                      isAtm
                        ? "bg-accent/80 font-medium"
                        : "hover:bg-muted/50",
                      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                    )}
                  >
                    {columns.map((c, i) => (
                      <td
                        key={`c-${c.key}`}
                        className={cn(
                          "relative px-3 py-1.5",
                          callItm && "bg-bid/5"
                        )}
                      >
                        {i === 0 && !compact ? (
                          <span
                            aria-hidden="true"
                            className="absolute inset-y-1 right-0 left-0 opacity-15"
                            style={oiBar(row.call, "call")}
                          />
                        ) : null}
                        <span className="relative">{c.cell(row.call)}</span>
                      </td>
                    ))}
                    <td
                      className={cn(
                        "px-3 py-1.5 text-center font-semibold tabular-nums",
                        isAtm && "text-foreground"
                      )}
                    >
                      {nf0.format(row.strike)}
                      {isAtm ? (
                        <span className="ml-1 rounded bg-primary px-1 py-px text-[9px] font-semibold uppercase text-primary-foreground">
                          ATM
                        </span>
                      ) : null}
                    </td>
                    {[...columns].reverse().map((c, i) => (
                      <td
                        key={`p-${c.key}`}
                        className={cn(
                          "relative px-3 py-1.5",
                          putItm && "bg-ask/5"
                        )}
                      >
                        {i === columns.length - 1 && !compact ? (
                          <span
                            aria-hidden="true"
                            className="absolute inset-y-1 left-0 right-0 opacity-15"
                            style={oiBar(row.put, "put")}
                          />
                        ) : null}
                        <span className="relative">{c.cell(row.put)}</span>
                      </td>
                    ))}
                  </tr>
                  {isOpen ? (
                    <tr className="border-b border-border/60 bg-muted/30">
                      <td colSpan={columns.length * 2 + 1} className="p-0">
                        <DepthPanel
                          row={row}
                          lotSize={lotSize}
                          reduced={reduced}
                          onOrder={onOrder}
                        />
                      </td>
                    </tr>
                  ) : null}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
      <p className="border-t border-border px-3 py-2 text-[11px] text-muted-foreground">
        Lot size {lotSize} · click a strike for depth and orders · simulated
        data
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Depth + order panel (expands in context under the strike row)        */
/* ------------------------------------------------------------------ */

function DepthPanel({
  row,
  lotSize,
  reduced,
  onOrder,
}: {
  row: OptionChainRow;
  lotSize: number;
  reduced: boolean;
  onOrder?: (order: OptionOrder) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { height: "auto", opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { height: 0, opacity: 0 },
        {
          height: "auto",
          opacity: 1,
          duration: 0.35,
          ease: "power3.out",
          clearProps: "height",
        }
      );
    },
    { scope: ref }
  );

  const side = (label: "call" | "put", q: OptionQuote) => (
    <div className="flex-1 rounded-lg border border-border bg-card p-3">
      <div className="mb-2 flex items-center justify-between">
        <span
          className={cn(
            "text-xs font-semibold uppercase tracking-wide",
            label === "call" ? "text-bid" : "text-ask"
          )}
        >
          {label} {nf0.format(row.strike)}
        </span>
        <span className="text-xs text-muted-foreground">
          Δ {q.delta.toFixed(2)} · Θ {q.theta.toFixed(2)}
        </span>
      </div>
      <div className="grid grid-cols-2 gap-2 text-center text-[13px] tabular-nums">
        <div className="rounded-md bg-bid/10 px-2 py-1.5">
          <p className="text-[10px] uppercase text-muted-foreground">
            Bid × {q.bidQty}
          </p>
          <p className="font-medium text-bid">{nf2.format(q.bid)}</p>
        </div>
        <div className="rounded-md bg-ask/10 px-2 py-1.5">
          <p className="text-[10px] uppercase text-muted-foreground">
            Ask × {q.askQty}
          </p>
          <p className="font-medium text-ask">{nf2.format(q.ask)}</p>
        </div>
      </div>
      <div className="mt-2 grid grid-cols-2 gap-2">
        <button
          type="button"
          onClick={() =>
            onOrder?.({ side: label, action: "buy", strike: row.strike, price: q.ask })
          }
          className="rounded-md bg-market-up px-2 py-1.5 text-xs font-semibold text-white transition-transform duration-100 active:scale-97 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          Buy ({lotSize})
        </button>
        <button
          type="button"
          onClick={() =>
            onOrder?.({ side: label, action: "sell", strike: row.strike, price: q.bid })
          }
          className="rounded-md bg-market-down px-2 py-1.5 text-xs font-semibold text-white transition-transform duration-100 active:scale-97 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          Sell ({lotSize})
        </button>
      </div>
    </div>
  );

  return (
    <div ref={ref} className="overflow-hidden">
      <div className="flex flex-col gap-3 p-3 sm:flex-row">
        {side("call", row.call)}
        {side("put", row.put)}
      </div>
    </div>
  );
}

registry/default/lib/black-scholes.ts:
/**
 * Compact Black-Scholes pricing and Greeks for index options.
 * Powers OptionChain and GreeksPanel so displayed values stay coherent
 * (premium, delta, gamma, theta and vega always agree with each other).
 * Rates are annualized; time is in years.
 */

/** Abramowitz–Stegun error-function approximation (max error ~1.5e-7). */
export function erf(x: number): number {
  const sign = x < 0 ? -1 : 1;
  const ax = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * ax);
  const y =
    1 -
    (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t -
      0.284496736) *
      t +
      0.254829592) *
      t *
      Math.exp(-ax * ax);
  return sign * y;
}

/** Standard normal CDF. */
export const cnd = (x: number): number => 0.5 * (1 + erf(x / Math.SQRT2));

/** Standard normal PDF. */
export const pdf = (x: number): number =>
  Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);

export interface Greeks {
  /** Option premium. */
  price: number;
  /** Per ₹1 move in the underlying. */
  delta: number;
  /** Delta change per ₹1 move. */
  gamma: number;
  /** Per calendar day (already divided by 365). */
  theta: number;
  /** Per 1 percentage-point change in IV. */
  vega: number;
}

export interface BsInput {
  /** Spot price. */
  s: number;
  /** Strike price. */
  k: number;
  /** Time to expiry in years. */
  t: number;
  /** Implied volatility, e.g. 0.14 for 14%. */
  iv: number;
  /** Risk-free rate. Default 0.065. */
  r?: number;
  side: "call" | "put";
}

export function blackScholes({ s, k, t, iv, r = 0.065, side }: BsInput): Greeks {
  const T = Math.max(t, 1 / 365 / 24); // clamp: expiry day still prices
  const sig = Math.max(iv, 0.001);
  const sqT = Math.sqrt(T);
  const d1 = (Math.log(s / k) + (r + (sig * sig) / 2) * T) / (sig * sqT);
  const d2 = d1 - sig * sqT;
  const disc = Math.exp(-r * T);

  const callPrice = s * cnd(d1) - k * disc * cnd(d2);
  const putPrice = k * disc * cnd(-d2) - s * cnd(-d1);
  const gamma = pdf(d1) / (s * sig * sqT);
  const vega = (s * pdf(d1) * sqT) / 100;

  if (side === "call") {
    const theta =
      (-(s * pdf(d1) * sig) / (2 * sqT) - r * k * disc * cnd(d2)) / 365;
    return { price: callPrice, delta: cnd(d1), gamma, theta, vega };
  }
  const theta =
    (-(s * pdf(d1) * sig) / (2 * sqT) + r * k * disc * cnd(-d2)) / 365;
  return { price: putPrice, delta: cnd(d1) - 1, gamma, theta, vega };
}

/** A gentle smile: IV rises away from ATM. `skew` tilts the put side up. */
export function smileIv(
  s: number,
  k: number,
  base = 0.13,
  skew = 0.015
): number {
  const m = (k - s) / s;
  return base + 6 * m * m - skew * m * 10 * 0.01;
}

registry/default/fintech/greeks-panel.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { blackScholes, smileIv } from "@/registry/default/lib/black-scholes";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

export interface GreeksPanelProps
  extends React.HTMLAttributes<HTMLDivElement> {
  side: "call" | "put";
  strike: number;
  spot: number;
  /** Days to expiry. */
  dte: number;
  /** Implied volatility as a fraction. Defaults to a smile around ATM. */
  iv?: number;
  /** Contract lot size used for the per-lot theta line. Default 75. */
  lotSize?: number;
  ref?: React.Ref<HTMLDivElement>;
}

interface GreekRow {
  key: "delta" | "gamma" | "theta" | "vega";
  label: string;
  symbol: string;
  value: number;
  decimals: number;
  /** 0–1 magnitude for the gauge. */
  norm: number;
  negative: boolean;
  description: string;
}

/**
 * Live Greeks for one option: premium and Δ Γ Θ V computed with
 * Black-Scholes so every number agrees. Values roll with NumberFlow and
 * each gauge springs to its new magnitude when inputs change.
 */
export function GreeksPanel({
  side,
  strike,
  spot,
  dte,
  iv,
  lotSize = 75,
  className,
  ref,
  ...rest
}: GreeksPanelProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const vol = iv ?? smileIv(spot, strike);
  const g = blackScholes({ s: spot, k: strike, t: dte / 365, iv: vol, side });
  const moneyness =
    (side === "call" ? spot - strike : strike - spot) > 0 ? "ITM" : "OTM";

  const rows: GreekRow[] = [
    {
      key: "delta",
      label: "Delta",
      symbol: "Δ",
      value: g.delta,
      decimals: 2,
      norm: Math.min(1, Math.abs(g.delta)),
      negative: g.delta < 0,
      description: "Premium change per ₹1 move in the underlying.",
    },
    {
      key: "gamma",
      label: "Gamma",
      symbol: "Γ",
      value: g.gamma,
      decimals: 4,
      norm: Math.min(1, g.gamma * 400),
      negative: false,
      description: "How fast delta itself moves — peaks at the money.",
    },
    {
      key: "theta",
      label: "Theta",
      symbol: "Θ",
      value: g.theta,
      decimals: 2,
      norm: Math.min(1, Math.abs(g.theta) / Math.max(1, g.price * 0.25)),
      negative: g.theta < 0,
      description: "Time decay per calendar day, all else equal.",
    },
    {
      key: "vega",
      label: "Vega",
      symbol: "V",
      value: g.vega,
      decimals: 2,
      norm: Math.min(1, g.vega / Math.max(1, spot * 0.002)),
      negative: false,
      description: "Premium change per 1 percentage-point move in IV.",
    },
  ];

  // Gauges spring to their new magnitude whenever inputs change.
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(
        root.querySelectorAll("[data-gauge]")
      );
      for (const bar of bars) {
        const target = Number(bar.dataset.gauge ?? 0) * 100;
        if (reduced) gsap.set(bar, { width: `${target}%` });
        else
          gsap.to(bar, {
            width: `${target}%`,
            duration: 0.6,
            ease: "power3.out",
            overwrite: true,
          });
      }
    },
    { dependencies: [spot, strike, dte, vol, side, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="greeks-panel"
      className={cn(
        "w-full max-w-md rounded-xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="flex items-center gap-2">
          <span
            className={cn(
              "rounded-md px-1.5 py-0.5 text-[11px] font-semibold uppercase",
              side === "call" ? "bg-bid/15 text-bid" : "bg-ask/15 text-ask"
            )}
          >
            {side}
          </span>
          <span className="text-sm font-semibold tabular-nums text-foreground">
            {new Intl.NumberFormat("en-IN").format(strike)}
          </span>
          <span className="text-xs text-muted-foreground">
            {moneyness} · {dte}d · IV {(vol * 100).toFixed(1)}%
          </span>
        </div>
      </div>

      <div className="mt-3 flex items-baseline gap-2">
        <span className="text-3xl font-semibold tracking-tight text-foreground">
          <NumberFlow value={g.price} prefix="₹" decimals={2} locale="en-IN" trend />
        </span>
        <span className="text-xs text-muted-foreground">premium</span>
      </div>

      <ul className="mt-4 flex flex-col gap-3">
        {rows.map((row) => (
          <li key={row.key}>
            <div className="flex items-baseline justify-between gap-2">
              <span className="text-xs font-medium text-foreground">
                <span className="mr-1.5 inline-block w-3 text-center font-semibold text-muted-foreground">
                  {row.symbol}
                </span>
                {row.label}
              </span>
              <span
                className={cn(
                  "text-sm font-semibold tabular-nums",
                  row.negative ? "text-market-down" : "text-foreground"
                )}
              >
                <NumberFlow value={row.value} decimals={row.decimals} trend />
              </span>
            </div>
            <div
              className="mt-1 h-1.5 w-full overflow-hidden rounded-full bg-muted"
              role="meter"
              aria-label={`${row.label} magnitude`}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={Math.round(row.norm * 100)}
            >
              <span
                data-gauge={row.norm}
                className={cn(
                  "block h-full rounded-full",
                  row.negative ? "bg-market-down" : "bg-primary"
                )}
                style={{ width: 0 }}
              />
            </div>
            <p className="mt-1 text-[11px] leading-4 text-muted-foreground">
              {row.description}
            </p>
          </li>
        ))}
      </ul>

      <p className="mt-4 border-t border-border pt-2 text-[11px] text-muted-foreground">
        Θ per lot ({lotSize}): ₹{(g.theta * lotSize).toFixed(0)}/day ·
        Black-Scholes, r 6.5%
      </p>
    </div>
  );
}

registry/default/workflows/kyc-flow.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import { Field } from "@/registry/default/ui/field";
import { Alert } from "@/registry/default/ui/alert";
import { Badge } from "@/registry/default/ui/badge";

/* ------------------------------------------------------------------ */
/* Types                                                                */
/* ------------------------------------------------------------------ */

export interface KycData {
  name: string;
  email: string;
  dob: string;
  pan: string;
}

export type KycOutcome = "approved" | "manual-review";

export interface KycFlowProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onComplete"> {
  /** Final verification outcome once submitted. Default "approved". */
  outcome?: KycOutcome;
  onComplete?: (data: KycData, outcome: KycOutcome) => void;
  onStepChange?: (step: number) => void;
  initialData?: Partial<KycData>;
  ref?: React.Ref<HTMLDivElement>;
}

const STEPS = ["Details", "PAN", "Documents", "Liveness", "Review"] as const;
const PAN_RE = /^[A-Z]{5}[0-9]{4}[A-Z]$/;
const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/* ------------------------------------------------------------------ */
/* Small shared pieces                                                  */
/* ------------------------------------------------------------------ */

function CheckIcon({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2.5}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={cn("size-3.5", className)}
      aria-hidden="true"
    >
      <path d="M5 13l4 4L19 7" />
    </svg>
  );
}

/** Big success check that draws itself. */
function SuccessCheck() {
  const ref = React.useRef<SVGPathElement>(null);
  const reduced = useReducedMotion();
  useGSAP(() => {
    if (!ref.current) return;
    if (reduced) {
      gsap.set(ref.current, { strokeDashoffset: 0 });
      return;
    }
    gsap.fromTo(
      ref.current,
      { strokeDashoffset: 1 },
      { strokeDashoffset: 0, duration: 0.6, ease: "power2.inOut", delay: 0.2 }
    );
  });
  return (
    <span className="flex size-14 items-center justify-center rounded-full bg-success/15">
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2.5}
        strokeLinecap="round"
        strokeLinejoin="round"
        className="size-7 text-success"
        aria-hidden="true"
      >
        <path
          ref={ref}
          d="M5 13l4 4L19 7"
          pathLength={1}
          strokeDasharray={1}
          strokeDashoffset={1}
        />
      </svg>
    </span>
  );
}

/* ------------------------------------------------------------------ */
/* Progress rail                                                        */
/* ------------------------------------------------------------------ */

function StepRail({ step }: { step: number }) {
  const reduced = useReducedMotion();
  const fillRef = React.useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!fillRef.current) return;
      const pct = (Math.min(step, STEPS.length - 1) / (STEPS.length - 1)) * 100;
      if (reduced) gsap.set(fillRef.current, { width: `${pct}%` });
      else
        gsap.to(fillRef.current, {
          width: `${pct}%`,
          duration: 0.5,
          ease: "power3.inOut",
        });
    },
    { dependencies: [step, reduced] }
  );

  return (
    <ol
      aria-label="Verification progress"
      className="relative mb-6 flex items-start justify-between"
    >
      <span
        aria-hidden="true"
        className="absolute left-3 right-3 top-[11px] h-0.5 bg-border"
      />
      <span
        aria-hidden="true"
        className="absolute left-3 top-[11px] h-0.5 max-w-[calc(100%-1.5rem)] bg-primary"
        ref={fillRef}
        style={{ width: 0 }}
      />
      {STEPS.map((label, i) => {
        const done = step > i;
        const active = step === i;
        return (
          <li
            key={label}
            aria-current={active ? "step" : undefined}
            className="relative flex w-12 flex-col items-center gap-1.5"
          >
            <span
              className={cn(
                "flex size-6 items-center justify-center rounded-full border-2 text-[10px] font-semibold transition-colors duration-300",
                done
                  ? "border-primary bg-primary text-primary-foreground"
                  : active
                    ? "border-primary bg-background text-foreground"
                    : "border-border bg-background text-muted-foreground"
              )}
            >
              {done ? <CheckIcon className="size-3" /> : i + 1}
            </span>
            <span
              className={cn(
                "text-[10px] font-medium",
                active ? "text-foreground" : "text-muted-foreground"
              )}
            >
              {label}
            </span>
          </li>
        );
      })}
    </ol>
  );
}

/* ------------------------------------------------------------------ */
/* Step container: directional slide-in on step change                  */
/* ------------------------------------------------------------------ */

function StepPanel({
  step,
  dir,
  children,
}: {
  step: number;
  dir: 1 | -1;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { x: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { x: 28 * dir, opacity: 0, filter: "blur(6px)" },
        {
          x: 0,
          opacity: 1,
          filter: "blur(0px)",
          duration: 0.4,
          ease: "power3.out",
          clearProps: "filter",
        }
      );
    },
    { dependencies: [step], scope: ref }
  );

  return (
    <div ref={ref} key={step}>
      {children}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Step 2: document capture card                                        */
/* ------------------------------------------------------------------ */

type DocState = "idle" | "checking" | "glare" | "done";

function DocCapture({
  label,
  state,
  onCapture,
}: {
  label: string;
  state: DocState;
  onCapture: () => void;
}) {
  return (
    <div
      className={cn(
        "flex flex-1 flex-col items-center gap-2 rounded-xl border border-dashed p-4 text-center transition-colors duration-300",
        state === "done"
          ? "border-success/60 bg-success/5"
          : state === "glare"
            ? "border-warning/60 bg-warning/5"
            : "border-border"
      )}
    >
      <span className="text-xs font-medium text-foreground">{label}</span>
      {state === "idle" ? (
        <>
          <span className="text-[11px] text-muted-foreground">
            Align inside the frame — we check focus and glare
          </span>
          <Button size="sm" variant="outline" onClick={onCapture}>
            Capture
          </Button>
        </>
      ) : null}
      {state === "checking" ? (
        <>
          <span className="relative h-1.5 w-full overflow-hidden rounded-full bg-muted">
            <span className="absolute inset-y-0 w-1/3 animate-duku-shimmer rounded-full bg-primary/60" />
          </span>
          <span className="text-[11px] text-muted-foreground">
            Checking edges, blur and glare…
          </span>
        </>
      ) : null}
      {state === "glare" ? (
        <>
          <span className="text-[11px] text-warning">
            Glare detected — tilt the document away from the light
          </span>
          <Button size="sm" variant="outline" onClick={onCapture}>
            Retake
          </Button>
        </>
      ) : null}
      {state === "done" ? (
        <span className="flex items-center gap-1.5 text-[11px] font-medium text-success">
          <CheckIcon /> Quality passed
        </span>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Step 3: liveness arc                                                 */
/* ------------------------------------------------------------------ */

const LIVENESS_PROMPTS = [
  "Center your face",
  "Turn your head left",
  "Turn your head right",
  "Blink twice",
] as const;

function LivenessCheck({
  running,
  done,
  prompt,
  progress,
}: {
  running: boolean;
  done: boolean;
  prompt: string;
  progress: number;
}) {
  const arcRef = React.useRef<SVGCircleElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!arcRef.current) return;
      if (reduced) {
        gsap.set(arcRef.current, { strokeDashoffset: 1 - progress });
        return;
      }
      gsap.to(arcRef.current, {
        strokeDashoffset: 1 - progress,
        duration: 0.8,
        ease: "power2.inOut",
      });
    },
    { dependencies: [progress, reduced] }
  );

  return (
    <div className="flex flex-col items-center gap-3">
      <div className="relative">
        <svg viewBox="0 0 120 120" className="size-32" aria-hidden="true">
          <circle
            cx="60"
            cy="60"
            r="54"
            fill="none"
            strokeWidth="4"
            className="stroke-muted"
          />
          <circle
            ref={arcRef}
            cx="60"
            cy="60"
            r="54"
            fill="none"
            strokeWidth="4"
            strokeLinecap="round"
            pathLength={1}
            strokeDasharray={1}
            strokeDashoffset={1}
            transform="rotate(-90 60 60)"
            className={cn(done ? "stroke-success" : "stroke-primary")}
          />
          {/* abstract face silhouette */}
          <circle cx="60" cy="50" r="14" className="fill-muted-foreground/30" />
          <path
            d="M36 92c4-14 14-20 24-20s20 6 24 20"
            className="fill-muted-foreground/30"
          />
        </svg>
        {done ? (
          <span className="absolute inset-0 flex items-center justify-center">
            <SuccessCheck />
          </span>
        ) : null}
      </div>
      <p
        aria-live="polite"
        className={cn(
          "text-sm font-medium",
          done ? "text-success" : "text-foreground"
        )}
      >
        {done ? "Liveness confirmed" : running ? prompt : "Ready when you are"}
      </p>
      <p className="max-w-xs text-center text-[11px] leading-4 text-muted-foreground">
        Frames are processed on-device for this check and never stored. This
        demo simulates the camera.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* The flow                                                             */
/* ------------------------------------------------------------------ */

export function KycFlow({
  outcome = "approved",
  onComplete,
  onStepChange,
  initialData,
  className,
  ref,
  ...rest
}: KycFlowProps) {
  const [step, setStepRaw] = React.useState(0);
  const [dir, setDir] = React.useState<1 | -1>(1);
  const [data, setData] = React.useState<KycData>({
    name: initialData?.name ?? "",
    email: initialData?.email ?? "",
    dob: initialData?.dob ?? "",
    pan: initialData?.pan ?? "",
  });
  const [errors, setErrors] = React.useState<Partial<Record<keyof KycData, string>>>({});
  const [panState, setPanState] = React.useState<"idle" | "verifying" | "verified">("idle");
  const [docFront, setDocFront] = React.useState<DocState>("idle");
  const [docBack, setDocBack] = React.useState<DocState>("idle");
  const frontAttempts = React.useRef(0);
  const [liveRunning, setLiveRunning] = React.useState(false);
  const [liveDone, setLiveDone] = React.useState(false);
  const [livePrompt, setLivePrompt] = React.useState<string>(LIVENESS_PROMPTS[0]);
  const [liveProgress, setLiveProgress] = React.useState(0);
  const [submitting, setSubmitting] = React.useState(false);
  const [result, setResult] = React.useState<KycOutcome | null>(null);

  const setStep = (next: number) => {
    setDir(next > step ? 1 : -1);
    setStepRaw(next);
    onStepChange?.(next);
  };

  const patch = (k: keyof KycData, v: string) => {
    setData((d) => ({ ...d, [k]: v }));
    setErrors((e) => ({ ...e, [k]: undefined }));
  };

  /* Step 0 */
  const submitDetails = () => {
    const next: typeof errors = {};
    if (data.name.trim().length < 2) next.name = "Enter your full legal name.";
    if (!/^\S+@\S+\.\S+$/.test(data.email)) next.email = "Enter a valid email.";
    if (!data.dob) next.dob = "Date of birth is required.";
    setErrors(next);
    if (Object.values(next).some(Boolean)) return;
    setStep(1);
  };

  /* Step 1 */
  const verifyPan = async () => {
    if (!PAN_RE.test(data.pan)) {
      setErrors((e) => ({
        ...e,
        pan: "PAN must look like ABCDE1234F.",
      }));
      return;
    }
    setPanState("verifying");
    await wait(1200);
    setPanState("verified");
  };

  /* Step 2 */
  const capture = async (side: "front" | "back") => {
    const set = side === "front" ? setDocFront : setDocBack;
    set("checking");
    await wait(1100);
    if (side === "front" && frontAttempts.current === 0) {
      frontAttempts.current += 1;
      set("glare"); // first front attempt fails: the state is the product
      return;
    }
    set("done");
  };

  /* Step 3 */
  const runLiveness = async () => {
    setLiveRunning(true);
    for (let i = 0; i < LIVENESS_PROMPTS.length; i++) {
      setLivePrompt(LIVENESS_PROMPTS[i]);
      setLiveProgress((i + 1) / LIVENESS_PROMPTS.length);
      await wait(900);
    }
    setLiveRunning(false);
    setLiveDone(true);
  };

  /* Step 4 */
  const submitAll = async () => {
    setSubmitting(true);
    await wait(1500);
    setSubmitting(false);
    setResult(outcome);
    setStep(5);
    onComplete?.(data, outcome);
  };

  const review: [string, string, number][] = [
    ["Name", data.name, 0],
    ["Email", data.email, 0],
    ["Date of birth", data.dob, 0],
    ["PAN", data.pan, 1],
    ["ID document", "Front + back verified", 2],
    ["Liveness", "Confirmed", 3],
  ];

  return (
    <div
      ref={ref}
      data-slot="kyc-flow"
      className={cn(
        "w-full max-w-md rounded-2xl border border-border bg-card p-6",
        className
      )}
      {...rest}
    >
      {step < 5 ? <StepRail step={step} /> : null}

      <StepPanel step={step} dir={dir}>
        {step === 0 ? (
          <form
            className="flex flex-col gap-4"
            onSubmit={(e) => {
              e.preventDefault();
              submitDetails();
            }}
          >
            <Field
              label="Full name"
              state={errors.name ? "error" : null}
              message={errors.name}
            >
              <Input
                value={data.name}
                invalid={!!errors.name}
                autoComplete="name"
                onChange={(e) => patch("name", e.target.value)}
              />
            </Field>
            <Field
              label="Email"
              state={errors.email ? "error" : null}
              message={errors.email}
            >
              <Input
                type="email"
                value={data.email}
                invalid={!!errors.email}
                autoComplete="email"
                onChange={(e) => patch("email", e.target.value)}
              />
            </Field>
            <Field
              label="Date of birth"
              state={errors.dob ? "error" : null}
              message={errors.dob}
            >
              <Input
                type="date"
                value={data.dob}
                invalid={!!errors.dob}
                onChange={(e) => patch("dob", e.target.value)}
              />
            </Field>
            <Button type="submit" className="mt-1">
              Continue
            </Button>
          </form>
        ) : null}

        {step === 1 ? (
          <div className="flex flex-col gap-4">
            <Field
              label="PAN"
              state={errors.pan ? "error" : panState === "verified" ? "success" : "hint"}
              message={
                errors.pan ??
                (panState === "verified"
                  ? "Verified against the income-tax registry."
                  : "Permanent Account Number, e.g. ABCDE1234F.")
              }
            >
              <Input
                value={data.pan}
                invalid={!!errors.pan}
                valid={panState === "verified"}
                maxLength={10}
                autoCapitalize="characters"
                disabled={panState !== "idle"}
                onChange={(e) => patch("pan", e.target.value.toUpperCase())}
              />
            </Field>
            {panState === "verified" ? (
              <Alert variant="success" title="Name match">
                Registered name matches your PAN record.
              </Alert>
            ) : null}
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(0)}>
                Back
              </Button>
              {panState === "verified" ? (
                <Button className="flex-1" onClick={() => setStep(2)}>
                  Continue
                </Button>
              ) : (
                <Button
                  className="flex-1"
                  loading={panState === "verifying"}
                  onClick={verifyPan}
                >
                  Verify PAN
                </Button>
              )}
            </div>
          </div>
        ) : null}

        {step === 2 ? (
          <div className="flex flex-col gap-4">
            <div className="flex flex-col gap-3 sm:flex-row">
              <DocCapture
                label="ID front"
                state={docFront}
                onCapture={() => capture("front")}
              />
              <DocCapture
                label="ID back"
                state={docBack}
                onCapture={() => capture("back")}
              />
            </div>
            <p className="text-[11px] text-muted-foreground">
              No camera? You can also upload a scan — the same quality checks
              apply.
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(1)}>
                Back
              </Button>
              <Button
                className="flex-1"
                disabled={docFront !== "done" || docBack !== "done"}
                onClick={() => setStep(3)}
              >
                Continue
              </Button>
            </div>
          </div>
        ) : null}

        {step === 3 ? (
          <div className="flex flex-col gap-4">
            <LivenessCheck
              running={liveRunning}
              done={liveDone}
              prompt={livePrompt}
              progress={liveProgress}
            />
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(2)}>
                Back
              </Button>
              {liveDone ? (
                <Button className="flex-1" onClick={() => setStep(4)}>
                  Continue
                </Button>
              ) : (
                <Button
                  className="flex-1"
                  loading={liveRunning}
                  onClick={runLiveness}
                >
                  Start liveness check
                </Button>
              )}
            </div>
          </div>
        ) : null}

        {step === 4 ? (
          <div className="flex flex-col gap-4">
            <dl className="divide-y divide-border rounded-xl border border-border">
              {review.map(([k, v, target]) => (
                <div
                  key={k}
                  className="flex items-center justify-between gap-2 px-3 py-2.5"
                >
                  <div className="min-w-0">
                    <dt className="text-[11px] uppercase tracking-wide text-muted-foreground">
                      {k}
                    </dt>
                    <dd className="truncate text-sm text-foreground">{v}</dd>
                  </div>
                  <button
                    type="button"
                    onClick={() => setStep(target)}
                    className="text-xs font-medium text-muted-foreground underline-offset-4 transition-colors duration-200 hover:text-foreground hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    Edit
                  </button>
                </div>
              ))}
            </dl>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(3)}>
                Back
              </Button>
              <Button className="flex-1" loading={submitting} onClick={submitAll}>
                Submit for verification
              </Button>
            </div>
          </div>
        ) : null}

        {step === 5 && result === "approved" ? (
          <div className="flex flex-col items-center gap-3 py-4 text-center">
            <SuccessCheck />
            <h3 className="text-lg font-semibold text-foreground">
              Identity verified
            </h3>
            <p className="max-w-xs text-sm text-muted-foreground">
              {data.name.split(" ")[0] || "You"}, your account is fully
              activated. A confirmation is on its way to {data.email}.
            </p>
          </div>
        ) : null}

        {step === 5 && result === "manual-review" ? (
          <div className="flex flex-col items-center gap-3 py-4 text-center">
            <Badge variant="outline" pulse className="text-warning">
              Manual review
            </Badge>
            <h3 className="text-lg font-semibold text-foreground">
              A specialist is taking a look
            </h3>
            <p className="max-w-xs text-sm text-muted-foreground">
              Your documents passed automated checks but need one human
              confirmation. Typical turnaround is under 2 hours — we&apos;ll
              email {data.email} the moment it completes. Nothing else is
              needed from you.
            </p>
          </div>
        ) : null}
      </StepPanel>
    </div>
  );
}

registry/default/crypto/crypto-swap.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Spinner } from "@/registry/default/ui/spinner";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface SwapToken {
  symbol: string;
  name: string;
  /** USD price used for quoting. */
  usd: number;
  balance: number;
  /** Tailwind color class for the coin dot. */
  tone: string;
  /** ERC-20s need an approval transaction before the first swap. */
  needsApproval?: boolean;
}

export const DEFAULT_TOKENS: SwapToken[] = [
  { symbol: "USDT", name: "Tether USD", usd: 1, balance: 2450.75, tone: "bg-emerald-500", needsApproval: true },
  { symbol: "ETH", name: "Ether", usd: 3412.6, balance: 0.42, tone: "bg-indigo-500" },
  { symbol: "USDC", name: "USD Coin", usd: 1, balance: 830.1, tone: "bg-sky-500", needsApproval: true },
  { symbol: "WBTC", name: "Wrapped BTC", usd: 97540, balance: 0.012, tone: "bg-amber-500", needsApproval: true },
];

export interface SwapQuote {
  rate: number;
  priceImpact: number;
  gasUsd: number;
  route: string[];
}

export interface CryptoSwapProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  tokens?: SwapToken[];
  /** Called after the simulated on-chain confirmation. */
  onSwapped?: (detail: {
    from: string;
    to: string;
    amountIn: number;
    amountOut: number;
  }) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const fmt = (n: number, max = 6) =>
  new Intl.NumberFormat("en-US", { maximumFractionDigits: max }).format(n);

function quote(from: SwapToken, to: SwapToken, amountIn: number): SwapQuote {
  const rate = from.usd / to.usd;
  const notional = amountIn * from.usd;
  const priceImpact = Math.min(9.9, (notional / 2_000_000) * 100);
  const direct =
    (from.symbol === "USDC" && to.symbol === "ETH") ||
    (from.symbol === "ETH" && to.symbol === "USDC");
  const route = direct
    ? [from.symbol, to.symbol]
    : from.symbol === "ETH" || to.symbol === "ETH"
      ? [from.symbol, "USDC", to.symbol === "ETH" ? "WETH" : to.symbol, ...(to.symbol === "ETH" ? ["ETH"] : [])]
      : [from.symbol, "USDC", to.symbol];
  return { rate, priceImpact, gasUsd: 2.6 + priceImpact * 0.4, route: [...new Set(route)] };
}

/* ------------------------------------------------------------------ */
/* Token select                                                         */
/* ------------------------------------------------------------------ */

function TokenSelect({
  tokens,
  value,
  exclude,
  onChange,
  label,
}: {
  tokens: SwapToken[];
  value: SwapToken;
  exclude: string;
  onChange: (t: SwapToken) => void;
  label: string;
}) {
  return (
    <div className="relative inline-flex items-center gap-1.5">
      <span aria-hidden="true" className={cn("size-4 rounded-full", value.tone)} />
      <select
        aria-label={label}
        value={value.symbol}
        onChange={(e) => {
          const t = tokens.find((x) => x.symbol === e.target.value);
          if (t) onChange(t);
        }}
        className="appearance-none rounded-md bg-transparent pr-4 text-sm font-semibold text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        {tokens
          .filter((t) => t.symbol !== exclude)
          .map((t) => (
            <option key={t.symbol} value={t.symbol}>
              {t.symbol}
            </option>
          ))}
      </select>
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        className="pointer-events-none absolute right-0 size-3 text-muted-foreground"
        aria-hidden="true"
      >
        <path d="m6 9 6 6 6-6" />
      </svg>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Swap                                                                 */
/* ------------------------------------------------------------------ */

type Stage = "form" | "approving" | "swapping" | "done";

export function CryptoSwap({
  tokens = DEFAULT_TOKENS,
  onSwapped,
  className,
  ref,
  ...rest
}: CryptoSwapProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [from, setFrom] = React.useState(tokens[0]);
  const [to, setTo] = React.useState(tokens[1]);
  const [amount, setAmount] = React.useState("1000");
  const [slippage, setSlippage] = React.useState(0.5);
  const [feesOpen, setFeesOpen] = React.useState(false);
  const [approved, setApproved] = React.useState<Record<string, boolean>>({});
  const [stage, setStage] = React.useState<Stage>("form");
  const [txStep, setTxStep] = React.useState(0);

  const amountIn = parseFloat(amount) || 0;
  const q = quote(from, to, amountIn);
  const amountOut = amountIn * q.rate * (1 - q.priceImpact / 100);
  const minReceived = amountOut * (1 - slippage / 100);
  const insufficient = amountIn > from.balance;
  const needsApproval = !!from.needsApproval && !approved[from.symbol];

  const feesRef = React.useRef<HTMLDivElement>(null);
  const payRef = React.useRef<HTMLDivElement>(null);
  const recvRef = React.useRef<HTMLDivElement>(null);

  /* Fee breakdown expands fluidly. */
  useGSAP(
    () => {
      if (!feesRef.current) return;
      if (reduced) {
        gsap.set(feesRef.current, { height: feesOpen ? "auto" : 0, opacity: feesOpen ? 1 : 0 });
        return;
      }
      gsap.to(feesRef.current, {
        height: feesOpen ? "auto" : 0,
        opacity: feesOpen ? 1 : 0,
        duration: 0.35,
        ease: "power3.out",
      });
    },
    { dependencies: [feesOpen, reduced] }
  );

  /* Tokens physically exchange position on flip. */
  const flip = () => {
    const doSwap = () => {
      setFrom(to);
      setTo(from);
      setAmount(fmt(amountOut, to.usd > 100 ? 5 : 2).replace(/,/g, ""));
    };
    if (reduced || !payRef.current || !recvRef.current) {
      doSwap();
      return;
    }
    const dy = recvRef.current.offsetTop - payRef.current.offsetTop;
    const tl = gsap.timeline({
      onComplete: () => {
        gsap.set([payRef.current, recvRef.current], { y: 0 });
        doSwap();
      },
    });
    tl.to(payRef.current, { y: dy, duration: 0.35, ease: "power3.inOut" }, 0)
      .to(recvRef.current, { y: -dy, duration: 0.35, ease: "power3.inOut" }, 0);
  };

  const approve = async () => {
    setStage("approving");
    await new Promise((r) => setTimeout(r, 1400));
    setApproved((a) => ({ ...a, [from.symbol]: true }));
    setStage("form");
  };

  const swap = async () => {
    setStage("swapping");
    setTxStep(0);
    await new Promise((r) => setTimeout(r, 900));
    setTxStep(1);
    await new Promise((r) => setTimeout(r, 1400));
    setTxStep(2);
    setStage("done");
    onSwapped?.({ from: from.symbol, to: to.symbol, amountIn, amountOut });
  };

  const reset = () => {
    setStage("form");
    setTxStep(0);
    setAmount("");
  };

  const tokenCard = (
    which: "pay" | "receive",
    token: SwapToken,
    onToken: (t: SwapToken) => void
  ) => (
    <div
      ref={which === "pay" ? payRef : recvRef}
      className={cn(
        "rounded-xl border bg-background p-3",
        which === "pay" && insufficient ? "border-destructive" : "border-border"
      )}
    >
      <div className="flex items-center justify-between text-[11px] text-muted-foreground">
        <span>{which === "pay" ? "You pay" : "You receive"}</span>
        <button
          type="button"
          onClick={which === "pay" ? () => setAmount(String(token.balance)) : undefined}
          disabled={which !== "pay"}
          className={cn(
            "tabular-nums",
            which === "pay" &&
              "underline-offset-2 hover:text-foreground hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          )}
        >
          Bal {fmt(token.balance, 4)}
          {which === "pay" ? " · MAX" : ""}
        </button>
      </div>
      <div className="mt-1.5 flex items-center justify-between gap-2">
        {which === "pay" ? (
          <input
            inputMode="decimal"
            aria-label="Amount to pay"
            value={amount}
            onChange={(e) => setAmount(e.target.value.replace(/[^0-9.]/g, ""))}
            placeholder="0.0"
            className="w-full min-w-0 bg-transparent text-2xl font-semibold tabular-nums text-foreground placeholder:text-muted-foreground/50 focus-visible:outline-none"
          />
        ) : (
          <span className="truncate text-2xl font-semibold tabular-nums text-foreground">
            {amountIn > 0 ? fmt(amountOut, token.usd > 100 ? 5 : 2) : "0.0"}
          </span>
        )}
        <TokenSelect
          tokens={tokens}
          value={token}
          exclude={which === "pay" ? to.symbol : from.symbol}
          onChange={onToken}
          label={which === "pay" ? "Pay token" : "Receive token"}
        />
      </div>
      <p className="mt-1 text-[11px] tabular-nums text-muted-foreground">
        ≈ ${fmt((which === "pay" ? amountIn : amountOut) * token.usd, 2)}
        {which === "pay" && insufficient ? (
          <span className="ml-2 font-medium text-destructive">
            Insufficient balance
          </span>
        ) : null}
      </p>
    </div>
  );

  return (
    <div
      ref={rootRef}
      data-slot="crypto-swap"
      className={cn(
        "w-full max-w-sm rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {stage !== "done" ? (
        <>
          <div className="relative flex flex-col gap-2">
            {tokenCard("pay", from, setFrom)}
            <button
              type="button"
              aria-label="Flip tokens"
              onClick={flip}
              className="absolute left-1/2 top-1/2 z-10 flex size-8 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-lg border border-border bg-card text-muted-foreground shadow-sm transition-all duration-200 hover:text-foreground active:scale-95 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" className="size-4" aria-hidden="true">
                <path d="M7 4v16m0 0-3-3m3 3 3-3M17 20V4m0 0-3 3m3-3 3 3" />
              </svg>
            </button>
            {tokenCard("receive", to, setTo)}
          </div>

          {/* Quote summary */}
          <button
            type="button"
            aria-expanded={feesOpen}
            onClick={() => setFeesOpen((o) => !o)}
            className="mt-3 flex w-full items-center justify-between rounded-lg px-1 py-1 text-xs text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <span className="tabular-nums">
              1 {from.symbol} = {fmt(q.rate, q.rate < 0.01 ? 6 : 4)} {to.symbol}
            </span>
            <span className="flex items-center gap-1 tabular-nums">
              ${q.gasUsd.toFixed(2)} gas
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth={2}
                className={cn("size-3 transition-transform duration-300", feesOpen && "rotate-180")}
                aria-hidden="true"
              >
                <path d="m6 9 6 6 6-6" />
              </svg>
            </span>
          </button>
          <div ref={feesRef} className="overflow-hidden" style={{ height: 0, opacity: 0 }}>
            <dl className="flex flex-col gap-1.5 px-1 pb-1 pt-2 text-xs">
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Price impact</dt>
                <dd className={cn("tabular-nums", q.priceImpact > 2 ? "text-warning" : "text-foreground")}>
                  {q.priceImpact.toFixed(2)}%
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Min received ({slippage}% slippage)</dt>
                <dd className="tabular-nums text-foreground">
                  {fmt(minReceived, 5)} {to.symbol}
                </dd>
              </div>
              <div className="flex items-center justify-between">
                <dt className="text-muted-foreground">Slippage</dt>
                <dd className="flex gap-1">
                  {[0.1, 0.5, 1].map((s) => (
                    <button
                      key={s}
                      type="button"
                      aria-pressed={slippage === s}
                      onClick={() => setSlippage(s)}
                      className={cn(
                        "rounded px-1.5 py-0.5 tabular-nums transition-colors duration-150",
                        slippage === s
                          ? "bg-primary text-primary-foreground"
                          : "bg-muted text-muted-foreground hover:text-foreground",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      )}
                    >
                      {s}%
                    </button>
                  ))}
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-muted-foreground">Route</dt>
                <dd className="flex items-center gap-1">
                  {q.route.map((hop, i) => (
                    <React.Fragment key={hop}>
                      {i > 0 ? (
                        <span aria-hidden="true" className="text-muted-foreground">→</span>
                      ) : null}
                      <span className="rounded bg-muted px-1 py-0.5 text-[10px] font-medium text-foreground">
                        {hop}
                      </span>
                    </React.Fragment>
                  ))}
                </dd>
              </div>
            </dl>
          </div>

          <div className="mt-3">
            {needsApproval && amountIn > 0 && !insufficient ? (
              <Button
                className="w-full"
                loading={stage === "approving"}
                onClick={approve}
              >
                Approve {from.symbol}
              </Button>
            ) : (
              <Button
                className="w-full"
                disabled={amountIn <= 0 || insufficient}
                loading={stage === "swapping"}
                onClick={swap}
              >
                {insufficient ? "Insufficient balance" : "Swap"}
              </Button>
            )}
            {needsApproval && amountIn > 0 && !insufficient ? (
              <p className="mt-1.5 text-center text-[11px] text-muted-foreground">
                One-time token approval, then the swap transaction.
              </p>
            ) : null}
          </div>
        </>
      ) : (
        <TxTimeline
          from={from}
          to={to}
          amountIn={amountIn}
          amountOut={amountOut}
          step={txStep}
          onReset={reset}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Confirmation timeline                                                */
/* ------------------------------------------------------------------ */

const TX_STEPS = ["Submitted", "Pending on-chain", "Confirmed"] as const;

function TxTimeline({
  from,
  to,
  amountIn,
  amountOut,
  step,
  onReset,
}: {
  from: SwapToken;
  to: SwapToken;
  amountIn: number;
  amountOut: number;
  step: number;
  onReset: () => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 14, filter: "blur(8px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.45, ease: "power3.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="flex flex-col gap-4 py-2">
      <div className="text-center">
        <p className="text-sm font-semibold text-foreground">
          {fmt(amountIn)} {from.symbol} → {fmt(amountOut, 5)} {to.symbol}
        </p>
        <p className="mt-0.5 text-[11px] text-muted-foreground">
          Swap complete · tx 0x3f8a…c21d
        </p>
      </div>
      <ol className="flex flex-col gap-0">
        {TX_STEPS.map((label, i) => {
          const done = step > i || (i === TX_STEPS.length - 1 && step >= i);
          const active = step === i && i < TX_STEPS.length - 1;
          return (
            <li key={label} className="flex gap-3">
              <div className="flex flex-col items-center">
                <span
                  className={cn(
                    "flex size-5 items-center justify-center rounded-full text-[10px]",
                    done
                      ? "bg-success text-white"
                      : active
                        ? "bg-primary/15"
                        : "bg-muted"
                  )}
                >
                  {done ? (
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true">
                      <path d="M5 13l4 4L19 7" />
                    </svg>
                  ) : active ? (
                    <Spinner size="sm" />
                  ) : null}
                </span>
                {i < TX_STEPS.length - 1 ? (
                  <span className={cn("my-0.5 h-5 w-px", done ? "bg-success" : "bg-border")} />
                ) : null}
              </div>
              <span
                className={cn(
                  "pt-0.5 text-sm",
                  done ? "text-foreground" : "text-muted-foreground"
                )}
              >
                {label}
              </span>
            </li>
          );
        })}
      </ol>
      <Button variant="outline" onClick={onReset}>
        New swap
      </Button>
    </div>
  );
}

registry/default/ai/agent-canvas.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Spinner } from "@/registry/default/ui/spinner";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface AgentToolCall {
  tool: string;
  args: string;
  /** Simulated duration in ms. */
  duration?: number;
  result?: string;
  /** First run fails with this error; a retry succeeds. */
  failsOnceWith?: string;
}

export interface AgentStep {
  id: string;
  title: string;
  toolCalls?: AgentToolCall[];
  /** Pause and require human approval before running. */
  approval?: { summary: string };
}

export type AgentRunStatus =
  | "idle"
  | "running"
  | "waiting-approval"
  | "error"
  | "complete"
  | "rejected";

export interface AgentCanvasProps
  extends React.HTMLAttributes<HTMLDivElement> {
  goal: string;
  steps: AgentStep[];
  /** Begin executing on mount. Default false — shows the plan first. */
  autoStart?: boolean;
  /** Rendered when the run completes. */
  artifact?: React.ReactNode;
  onStatusChange?: (status: AgentRunStatus) => void;
  ref?: React.Ref<HTMLDivElement>;
}

type StepState = "pending" | "active" | "done" | "error" | "waiting";
const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

const STATUS_META: Record<AgentRunStatus, { label: string; tone: string; pulse?: boolean }> = {
  idle: { label: "Plan ready", tone: "text-muted-foreground" },
  running: { label: "Running", tone: "text-agent-active", pulse: true },
  "waiting-approval": { label: "Waiting for approval", tone: "text-agent-waiting", pulse: true },
  error: { label: "Error — retry available", tone: "text-agent-error" },
  complete: { label: "Complete", tone: "text-success" },
  rejected: { label: "Stopped by user", tone: "text-muted-foreground" },
};

/* ------------------------------------------------------------------ */
/* Bits                                                                 */
/* ------------------------------------------------------------------ */

function StepDot({ state }: { state: StepState }) {
  return (
    <span
      className={cn(
        "relative mt-0.5 flex size-5 shrink-0 items-center justify-center rounded-full border-2 transition-colors duration-300",
        state === "done" && "border-success bg-success text-white",
        state === "active" && "border-agent-active",
        state === "waiting" && "border-agent-waiting",
        state === "error" && "border-agent-error bg-agent-error text-white",
        state === "pending" && "border-border"
      )}
    >
      {state === "done" ? (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true">
          <path d="M5 13l4 4L19 7" />
        </svg>
      ) : null}
      {state === "error" ? (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" className="size-3" aria-hidden="true">
          <path d="M18 6 6 18M6 6l12 12" />
        </svg>
      ) : null}
      {state === "active" || state === "waiting" ? (
        <>
          <span
            className={cn(
              "absolute inline-flex size-2.5 animate-ping rounded-full opacity-60",
              state === "active" ? "bg-agent-active" : "bg-agent-waiting"
            )}
          />
          <span
            className={cn(
              "size-2 rounded-full",
              state === "active" ? "bg-agent-active" : "bg-agent-waiting"
            )}
          />
        </>
      ) : null}
    </span>
  );
}

function ToolCallRow({
  call,
  state,
  error,
}: {
  call: AgentToolCall;
  state: "pending" | "running" | "done" | "error";
  error?: string;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 8, filter: "blur(4px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.3, ease: "power2.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );

  return (
    <div
      ref={ref}
      className="flex items-start gap-2 rounded-lg border border-border/70 bg-muted/40 px-2.5 py-1.5 font-mono text-[11px] leading-5"
    >
      <span className="mt-1">
        {state === "running" ? (
          <Spinner size="sm" />
        ) : state === "done" ? (
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3 text-success" aria-hidden="true">
            <path d="M5 13l4 4L19 7" />
          </svg>
        ) : state === "error" ? (
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" className="size-3 text-agent-error" aria-hidden="true">
            <path d="M18 6 6 18M6 6l12 12" />
          </svg>
        ) : (
          <span className="block size-3 rounded-full border border-border" />
        )}
      </span>
      <div className="min-w-0 flex-1">
        <p className="truncate">
          <span className="font-semibold text-foreground">{call.tool}</span>
          <span className="text-muted-foreground">({call.args})</span>
        </p>
        {state === "done" && call.result ? (
          <p className="truncate text-muted-foreground">→ {call.result}</p>
        ) : null}
        {state === "error" && error ? (
          <p className="truncate text-agent-error">✕ {error}</p>
        ) : null}
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Canvas                                                               */
/* ------------------------------------------------------------------ */

export function AgentCanvas({
  goal,
  steps,
  autoStart = false,
  artifact,
  onStatusChange,
  className,
  ref,
  ...rest
}: AgentCanvasProps) {
  const reduced = useReducedMotion();
  const [status, setStatusRaw] = React.useState<AgentRunStatus>("idle");
  const [stepIdx, setStepIdx] = React.useState(-1);
  const [callIdx, setCallIdx] = React.useState(-1);
  const [failedOnce, setFailedOnce] = React.useState<Record<string, boolean>>({});
  const [errorMsg, setErrorMsg] = React.useState<string | null>(null);
  const runToken = React.useRef(0);

  const setStatus = (s: AgentRunStatus) => {
    setStatusRaw(s);
    onStatusChange?.(s);
  };

  const stepState = (i: number): StepState => {
    if (status === "complete" || i < stepIdx) return "done";
    if (i > stepIdx) return "pending";
    if (status === "waiting-approval") return "waiting";
    if (status === "error") return "error";
    if (status === "running") return "active";
    return "pending";
  };

  const runFrom = React.useCallback(
    async (startStep: number, startCall: number) => {
      const token = ++runToken.current;
      setStatus("running");
      setErrorMsg(null);
      for (let i = startStep; i < steps.length; i++) {
        if (runToken.current !== token) return;
        const step = steps[i];
        setStepIdx(i);
        if (step.approval && !(startStep === i && startCall > -1)) {
          setCallIdx(-1);
          setStatus("waiting-approval");
          return; // resumes via approve()
        }
        const calls = step.toolCalls ?? [];
        for (let c = i === startStep ? Math.max(0, startCall) : 0; c < calls.length; c++) {
          if (runToken.current !== token) return;
          setCallIdx(c);
          await wait(calls[c].duration ?? 900);
          if (runToken.current !== token) return;
          const key = `${step.id}:${c}`;
          if (calls[c].failsOnceWith && !failedOnce[key]) {
            setFailedOnce((f) => ({ ...f, [key]: true }));
            setErrorMsg(calls[c].failsOnceWith ?? "Tool failed");
            setStatus("error");
            return;
          }
        }
        setCallIdx(calls.length);
      }
      setStepIdx(steps.length);
      setStatus("complete");
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [steps, failedOnce]
  );

  React.useEffect(() => {
    if (autoStart) runFrom(0, -1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoStart]);

  const approve = () => {
    // continue current step's tool calls after the gate
    runFrom(stepIdx, 0);
  };
  const reject = () => {
    runToken.current++;
    setStatus("rejected");
  };
  const retry = () => runFrom(stepIdx, callIdx);

  const meta = STATUS_META[status];

  return (
    <div
      ref={ref}
      data-slot="agent-canvas"
      className={cn(
        "w-full max-w-lg rounded-2xl border border-border bg-card",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-start justify-between gap-3 border-b border-border px-4 py-3">
        <div className="min-w-0">
          <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
            Goal
          </p>
          <p className="truncate text-sm font-medium text-foreground">{goal}</p>
        </div>
        <span className={cn("flex shrink-0 items-center gap-1.5 text-xs font-medium", meta.tone)}>
          {meta.pulse ? (
            <span className="relative flex size-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-current opacity-50" />
              <span className="relative inline-flex size-2 rounded-full bg-current" />
            </span>
          ) : null}
          {meta.label}
        </span>
      </div>

      {/* Timeline */}
      <ol className="flex flex-col px-4 py-3">
        {steps.map((step, i) => {
          const state = stepState(i);
          const calls = step.toolCalls ?? [];
          return (
            <li key={step.id} className="relative flex gap-3 pb-4 last:pb-0">
              {i < steps.length - 1 ? (
                <span
                  aria-hidden="true"
                  className={cn(
                    "absolute left-[9px] top-6 h-[calc(100%-1.25rem)] w-0.5 rounded transition-colors duration-500",
                    state === "done" ? "bg-success/50" : "bg-border"
                  )}
                />
              ) : null}
              <StepDot state={state} />
              <div className="min-w-0 flex-1">
                <p
                  className={cn(
                    "text-sm",
                    state === "pending" ? "text-muted-foreground" : "font-medium text-foreground"
                  )}
                >
                  {step.title}
                </p>

                {/* Tool calls appear as the step executes */}
                {(state === "active" || state === "error") && calls.length > 0 ? (
                  <div className="mt-1.5 flex flex-col gap-1">
                    {calls.slice(0, Math.max(0, callIdx + 1)).map((call, c) => (
                      <ToolCallRow
                        key={c}
                        call={call}
                        state={
                          status === "error" && c === callIdx
                            ? "error"
                            : c < callIdx
                              ? "done"
                              : "running"
                        }
                        error={errorMsg ?? undefined}
                      />
                    ))}
                  </div>
                ) : null}
                {state === "done" && calls.length > 0 ? (
                  <p className="mt-0.5 text-[11px] text-muted-foreground">
                    {calls.length} tool call{calls.length > 1 ? "s" : ""} ·{" "}
                    {calls.map((c) => c.tool).join(", ")}
                  </p>
                ) : null}

                {/* Approval gate */}
                {state === "waiting" && step.approval ? (
                  <div className="mt-2 rounded-lg border border-agent-waiting/40 bg-agent-waiting/10 p-2.5">
                    <p className="text-xs text-foreground">{step.approval.summary}</p>
                    <div className="mt-2 flex gap-2">
                      <Button size="sm" onClick={approve}>
                        Approve
                      </Button>
                      <Button size="sm" variant="outline" onClick={reject}>
                        Reject
                      </Button>
                    </div>
                  </div>
                ) : null}

                {/* Retry */}
                {state === "error" ? (
                  <div className="mt-2">
                    <Button size="sm" variant="outline" onClick={retry}>
                      Retry step
                    </Button>
                  </div>
                ) : null}
              </div>
            </li>
          );
        })}
      </ol>

      {/* Footer: start / artifact */}
      <div className="border-t border-border px-4 py-3">
        {status === "idle" ? (
          <Button className="w-full" onClick={() => runFrom(0, -1)}>
            Run plan
          </Button>
        ) : null}
        {status === "rejected" ? (
          <Button className="w-full" variant="outline" onClick={() => runFrom(stepIdx, -1)}>
            Resume run
          </Button>
        ) : null}
        {status === "complete" ? (
          artifact ? (
            <ArtifactReveal reduced={reduced}>{artifact}</ArtifactReveal>
          ) : (
            <p className="text-center text-xs text-success">Run complete</p>
          )
        ) : null}
        {status === "running" || status === "waiting-approval" || status === "error" ? (
          <p className="text-center text-[11px] tabular-nums text-muted-foreground">
            step {Math.min(stepIdx + 1, steps.length)}/{steps.length} · 12.4k tokens · $0.08
          </p>
        ) : null}
      </div>
    </div>
  );
}

function ArtifactReveal({
  children,
  reduced,
}: {
  children: React.ReactNode;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 12, filter: "blur(8px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.45, ease: "power3.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );
  return (
    <div ref={ref}>
      <p className="mb-2 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
        Artifact
      </p>
      {children}
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";
import { Alert } from "@/registry/default/ui/alert";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface Holding {
  symbol: string;
  name: string;
  sector: string;
  value: number;
  /** Stock beta vs the index. */
  beta: number;
  dayChangePct: number;
}

export const DEMO_HOLDINGS: Holding[] = [
  { symbol: "HDFCBANK", name: "HDFC Bank", sector: "Financials", value: 412000, beta: 1.05, dayChangePct: 0.6 },
  { symbol: "ICICIBANK", name: "ICICI Bank", sector: "Financials", value: 268000, beta: 1.12, dayChangePct: -0.3 },
  { symbol: "INFY", name: "Infosys", sector: "IT", value: 236000, beta: 0.85, dayChangePct: 1.2 },
  { symbol: "TCS", name: "TCS", sector: "IT", value: 158000, beta: 0.8, dayChangePct: 0.4 },
  { symbol: "RELIANCE", name: "Reliance", sector: "Energy", value: 301000, beta: 1.1, dayChangePct: -0.8 },
  { symbol: "SUNPHARMA", name: "Sun Pharma", sector: "Pharma", value: 92000, beta: 0.6, dayChangePct: 0.9 },
  { symbol: "DMART", name: "Avenue Supermarts", sector: "Consumer", value: 74000, beta: 0.7, dayChangePct: -1.1 },
];

export interface PortfolioRiskProps
  extends React.HTMLAttributes<HTMLDivElement> {
  holdings?: Holding[];
  /** Concentration warning threshold as a fraction of portfolio. Default 0.25. */
  concentrationLimit?: number;
  ref?: React.Ref<HTMLDivElement>;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);

/* ------------------------------------------------------------------ */
/* Cockpit                                                              */
/* ------------------------------------------------------------------ */

export function PortfolioRisk({
  holdings = DEMO_HOLDINGS,
  concentrationLimit = 0.25,
  className,
  ref,
  ...rest
}: PortfolioRiskProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [shock, setShock] = React.useState(0); // NIFTY move in %, negative = down

  const total = holdings.reduce((s, h) => s + h.value, 0);
  const beta = holdings.reduce((s, h) => s + h.beta * h.value, 0) / total;
  const dayPnl = holdings.reduce((s, h) => s + (h.dayChangePct / 100) * h.value, 0);
  // 1-day 95% parametric VaR with ~1% daily index vol scaled by beta
  const var95 = total * beta * 0.01 * 1.65;

  const sectors = React.useMemo(() => {
    const map = new Map<string, number>();
    for (const h of holdings) map.set(h.sector, (map.get(h.sector) ?? 0) + h.value);
    return [...map.entries()]
      .map(([sector, value]) => ({ sector, value, share: value / total }))
      .sort((a, b) => b.value - a.value);
  }, [holdings, total]);

  const topConcentration = sectors[0];
  const concentrated = topConcentration.share > concentrationLimit;
  const shockImpact = total * beta * (shock / 100);

  /* Sector bars fill on scroll-in / data change. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-bar]"));
      for (const bar of bars) {
        const target = Number(bar.dataset.bar ?? 0) * 100;
        if (reduced) gsap.set(bar, { width: `${target}%` });
        else
          gsap.fromTo(
            bar,
            { width: 0 },
            { width: `${target}%`, duration: 0.7, ease: "power3.out", stagger: 0.06 }
          );
      }
    },
    { dependencies: [reduced, holdings], scope: rootRef }
  );

  const tiles: {
    label: string;
    value: React.ReactNode;
    sub?: string;
    accent: string;
  }[] = [
    {
      label: "Portfolio value",
      value: <NumberFlow value={total} prefix="₹" locale="en-IN" />,
      sub: `${holdings.length} holdings`,
      accent: "var(--foreground)",
    },
    {
      label: "Day P&L",
      value: (
        <span className={dayPnl >= 0 ? "text-market-up" : "text-market-down"}>
          <NumberFlow value={Math.round(dayPnl)} prefix={dayPnl >= 0 ? "+₹" : "−₹"} locale="en-IN" />
        </span>
      ),
      sub: `${((dayPnl / total) * 100).toFixed(2)}%`,
      accent: dayPnl >= 0 ? "var(--market-up)" : "var(--market-down)",
    },
    {
      label: "Beta",
      value: <NumberFlow value={beta} decimals={2} />,
      sub: "vs NIFTY 50",
      accent: "var(--info)",
    },
    {
      label: "VaR 95% · 1d",
      value: (
        <span className="text-risk-high">
          <NumberFlow value={Math.round(var95)} prefix="₹" locale="en-IN" />
        </span>
      ),
      sub: `${((var95 / total) * 100).toFixed(1)}% of value`,
      accent: "var(--risk-high)",
    },
  ];

  return (
    <div
      ref={rootRef}
      data-slot="portfolio-risk"
      className={cn(
        "w-full max-w-2xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      {/* Stat tiles */}
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        {tiles.map((t) => (
          <div
            key={t.label}
            className="group/tile relative overflow-hidden rounded-xl border border-border/70 bg-background p-3 shadow-xs transition-shadow duration-200 hover:shadow-sm"
          >
            {/* Left accent rail keyed to the metric's meaning. */}
            <span
              aria-hidden="true"
              className="absolute inset-y-2 left-0 w-0.5 rounded-full opacity-70"
              style={{ background: t.accent }}
            />
            <p className="pl-1.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
              {t.label}
            </p>
            <p className="mt-1 pl-1.5 text-lg font-semibold tabular-nums text-foreground">
              {t.value}
            </p>
            {t.sub ? (
              <p className="pl-1.5 text-[11px] tabular-nums text-muted-foreground">{t.sub}</p>
            ) : null}
          </div>
        ))}
      </div>

      {/* Sector exposure */}
      <div className="mt-5">
        <h3 className="text-xs font-semibold text-foreground">Sector exposure</h3>
        <ul className="mt-2.5 flex flex-col gap-2.5">
          {sectors.map((s) => {
            const over = s.share > concentrationLimit;
            return (
              <li key={s.sector} className="flex items-center gap-3 text-xs">
                <span className="w-20 shrink-0 truncate text-muted-foreground">
                  {s.sector}
                </span>
                <span className="relative h-2 flex-1 overflow-hidden rounded-full bg-muted/70 ring-1 ring-inset ring-border/50">
                  <span
                    data-bar={s.share}
                    className="block h-full rounded-full"
                    style={{
                      width: 0,
                      background: over
                        ? "linear-gradient(90deg, color-mix(in oklab, var(--risk-high) 70%, transparent), var(--risk-high))"
                        : "linear-gradient(90deg, color-mix(in oklab, var(--info) 55%, var(--primary)), var(--info))",
                    }}
                  />
                </span>
                <span
                  className={cn(
                    "w-12 shrink-0 text-right tabular-nums",
                    over ? "font-medium text-risk-high" : "text-foreground"
                  )}
                >
                  {(s.share * 100).toFixed(1)}%
                </span>
              </li>
            );
          })}
        </ul>
      </div>

      {concentrated ? (
        <div className="mt-3">
          <Alert variant="warning" title="Concentration risk">
            {topConcentration.sector} is {(topConcentration.share * 100).toFixed(0)}% of the
            portfolio — above your {(concentrationLimit * 100).toFixed(0)}% limit.
          </Alert>
        </div>
      ) : null}

      {/* Scenario testing */}
      <div className="mt-4 rounded-xl border border-border bg-background p-3">
        <div className="flex items-center justify-between gap-2">
          <h3 className="text-xs font-semibold text-foreground">Scenario</h3>
          <span className="text-xs tabular-nums text-muted-foreground">
            NIFTY {shock >= 0 ? "+" : ""}
            {shock.toFixed(1)}%
          </span>
        </div>
        <input
          type="range"
          min={-10}
          max={5}
          step={0.5}
          value={shock}
          aria-label="Index shock scenario in percent"
          onChange={(e) => setShock(parseFloat(e.target.value))}
          className="mt-2 w-full accent-primary"
        />
        <div className="mt-1 flex items-baseline justify-between">
          <span className="text-[11px] text-muted-foreground">
            Estimated portfolio impact (β-scaled)
          </span>
          <span
            className={cn(
              "text-sm font-semibold tabular-nums",
              shockImpact >= 0 ? "text-market-up" : "text-market-down"
            )}
          >
            <NumberFlow
              value={Math.round(shockImpact)}
              prefix={shockImpact >= 0 ? "+₹" : "−₹"}
              locale="en-IN"
              trend
            />
          </span>
        </div>
        {shock <= -5 ? (
          <p className="mt-2 rounded-lg bg-muted/60 px-2.5 py-1.5 text-[11px] leading-4 text-foreground">
            <span className="font-semibold">Hedge idea:</span> a NIFTY put ~5% below spot
            (β-weighted {inr(Math.round(total * beta))} exposure) caps this scenario near ₹
            {inr(Math.round(Math.abs(shockImpact) * 0.4))}. Educational, not advice.
          </p>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface BiomarkerReading {
  date: string; // ISO date
  value: number;
}

export interface BiomarkerEvent {
  date: string;
  label: string;
}

export interface BiomarkerTrendProps
  extends React.HTMLAttributes<HTMLDivElement> {
  name: string;
  unit: string;
  readings: BiomarkerReading[];
  /** Laboratory reference range in primary units. */
  range: { low: number; high: number };
  /** Personal baseline (median of historical normals). */
  baseline?: number;
  events?: BiomarkerEvent[];
  /** Optional secondary unit, e.g. mmol/L for a mg/dL marker. */
  altUnit?: { unit: string; factor: number };
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_LDL: Omit<BiomarkerTrendProps, keyof React.HTMLAttributes<HTMLDivElement>> = {
  name: "LDL cholesterol",
  unit: "mg/dL",
  range: { low: 50, high: 130 },
  baseline: 112,
  altUnit: { unit: "mmol/L", factor: 0.02586 },
  readings: [
    { date: "2025-01-14", value: 118 },
    { date: "2025-03-02", value: 127 },
    { date: "2025-05-20", value: 149 },
    { date: "2025-07-11", value: 158 },
    { date: "2025-09-05", value: 141 },
    { date: "2025-11-19", value: 122 },
    { date: "2026-01-24", value: 108 },
    { date: "2026-04-02", value: 101 },
  ],
  events: [{ date: "2025-08-01", label: "Statin started" }],
};

const short = (iso: string) =>
  new Date(iso).toLocaleDateString("en-GB", { month: "short", year: "2-digit" });

/* ------------------------------------------------------------------ */
/* Explorer                                                             */
/* ------------------------------------------------------------------ */

const W = 560;
const H = 220;
const PAD = { l: 40, r: 12, t: 14, b: 26 };

export function BiomarkerTrend({
  name,
  unit,
  readings,
  range,
  baseline,
  events = [],
  altUnit,
  className,
  ref,
  ...rest
}: BiomarkerTrendProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const pathRef = React.useRef<SVGPathElement>(null);
  const areaRef = React.useRef<SVGPathElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [useAlt, setUseAlt] = React.useState(false);
  const [selected, setSelected] = React.useState<number | null>(
    readings.length - 1
  );

  const factor = useAlt && altUnit ? altUnit.factor : 1;
  const displayUnit = useAlt && altUnit ? altUnit.unit : unit;
  const decimals = useAlt && altUnit ? 2 : 0;
  const fmtVal = (v: number) => (v * factor).toFixed(decimals);

  const t0 = new Date(readings[0].date).getTime();
  const t1 = new Date(readings[readings.length - 1].date).getTime();
  const values = readings.map((r) => r.value);
  const vMin = Math.min(...values, range.low) * 0.9;
  const vMax = Math.max(...values, range.high) * 1.06;

  const x = (iso: string) =>
    PAD.l + ((new Date(iso).getTime() - t0) / (t1 - t0)) * (W - PAD.l - PAD.r);
  const y = (v: number) =>
    H - PAD.b - ((v - vMin) / (vMax - vMin)) * (H - PAD.t - PAD.b);

  const line = readings
    .map((r, i) => `${i === 0 ? "M" : "L"}${x(r.date).toFixed(1)},${y(r.value).toFixed(1)}`)
    .join(" ");
  const area = `${line} L${x(readings[readings.length - 1].date).toFixed(1)},${(H - PAD.b).toFixed(1)} L${x(readings[0].date).toFixed(1)},${(H - PAD.b).toFixed(1)} Z`;

  /* The trend draws itself once, then the area fades up beneath it. */
  useGSAP(
    () => {
      const p = pathRef.current;
      const a = areaRef.current;
      if (!p) return;
      const len = p.getTotalLength();
      if (reduced) {
        gsap.set(p, { strokeDasharray: "none", strokeDashoffset: 0 });
        if (a) gsap.set(a, { opacity: 1 });
        return;
      }
      if (a) gsap.set(a, { opacity: 0 });
      gsap.fromTo(
        p,
        { strokeDasharray: len, strokeDashoffset: len },
        { strokeDashoffset: 0, duration: 1.2, ease: "power2.inOut" }
      );
      if (a) gsap.to(a, { opacity: 1, duration: 0.6, delay: 0.7 });
    },
    { dependencies: [reduced], scope: rootRef }
  );

  const sel = selected != null ? readings[selected] : null;
  const selAbnormal = sel != null && (sel.value > range.high || sel.value < range.low);
  const latest = readings[readings.length - 1];
  const prev = readings[readings.length - 2];
  const trendPct = prev ? ((latest.value - prev.value) / prev.value) * 100 : 0;

  return (
    <div
      ref={rootRef}
      data-slot="biomarker-trend"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <h3 className="text-sm font-semibold text-foreground">{name}</h3>
          <p className="text-[11px] text-muted-foreground">
            Lab range {fmtVal(range.low)}–{fmtVal(range.high)} {displayUnit}
            {baseline ? ` · your baseline ${fmtVal(baseline)}` : ""}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span
            className={cn(
              "text-xs font-medium tabular-nums",
              trendPct <= 0 ? "text-success" : "text-warning"
            )}
          >
            {trendPct >= 0 ? "▲" : "▼"} {Math.abs(trendPct).toFixed(1)}% vs last
          </span>
          {altUnit ? (
            <button
              type="button"
              aria-pressed={useAlt}
              onClick={() => setUseAlt((a) => !a)}
              className="rounded-md border border-border px-2 py-0.5 text-[11px] font-medium text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {displayUnit}
            </button>
          ) : null}
        </div>
      </div>

      {/* Chart */}
      <div className="mt-3 overflow-x-auto">
        <svg
          viewBox={`0 0 ${W} ${H}`}
          role="img"
          aria-label={`${name} trend: ${readings.length} readings from ${short(readings[0].date)} to ${short(latest.date)}`}
          className="min-w-[420px]"
        >
          <defs>
            <linearGradient id={`bm-area-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--info)" stopOpacity={0.24} />
              <stop offset="100%" stopColor="var(--info)" stopOpacity={0} />
            </linearGradient>
            <linearGradient id={`bm-band-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--success)" stopOpacity={0.16} />
              <stop offset="100%" stopColor="var(--success)" stopOpacity={0.05} />
            </linearGradient>
            <filter id={`bm-glow-${uid}`} x="-10%" y="-40%" width="120%" height="180%">
              <feDropShadow dx="0" dy="1.5" stdDeviation="3" floodColor="var(--info)" floodOpacity="0.3" />
            </filter>
          </defs>

          {/* reference band */}
          <rect
            x={PAD.l}
            width={W - PAD.l - PAD.r}
            y={y(range.high)}
            height={y(range.low) - y(range.high)}
            rx={6}
            fill={`url(#bm-band-${uid})`}
          />
          <line
            x1={PAD.l}
            x2={W - PAD.r}
            y1={y(range.high)}
            y2={y(range.high)}
            className="stroke-success/25"
            strokeDasharray="3 3"
          />
          <text x={PAD.l + 4} y={y(range.high) + 11} className="fill-success text-[9px] font-medium">
            in range
          </text>

          {/* baseline */}
          {baseline ? (
            <>
              <line
                x1={PAD.l}
                x2={W - PAD.r}
                y1={y(baseline)}
                y2={y(baseline)}
                strokeDasharray="4 4"
                className="stroke-muted-foreground/50"
              />
              <text
                x={W - PAD.r - 2}
                y={y(baseline) - 3}
                textAnchor="end"
                className="fill-muted-foreground text-[9px]"
              >
                baseline
              </text>
            </>
          ) : null}

          {/* events */}
          {events.map((e) => (
            <g key={e.date}>
              <line
                x1={x(e.date)}
                x2={x(e.date)}
                y1={PAD.t}
                y2={H - PAD.b}
                className="stroke-info/50"
                strokeDasharray="2 3"
              />
              <text
                x={x(e.date) + 3}
                y={PAD.t + 8}
                className="fill-info text-[9px] font-medium"
              >
                {e.label}
              </text>
            </g>
          ))}

          {/* axis labels */}
          {[range.low, range.high].map((v) => (
            <text
              key={v}
              x={PAD.l - 5}
              y={y(v) + 3}
              textAnchor="end"
              className="fill-muted-foreground text-[9px] tabular-nums"
            >
              {fmtVal(v)}
            </text>
          ))}
          {readings.map((r, i) =>
            i % 2 === 0 ? (
              <text
                key={r.date}
                x={x(r.date)}
                y={H - 8}
                textAnchor="middle"
                className="fill-muted-foreground text-[9px]"
              >
                {short(r.date)}
              </text>
            ) : null
          )}

          {/* trend area + line */}
          <path ref={areaRef} d={area} fill={`url(#bm-area-${uid})`} opacity={0} />
          <path
            ref={pathRef}
            d={line}
            fill="none"
            stroke="var(--info)"
            strokeWidth={2.25}
            strokeLinecap="round"
            strokeLinejoin="round"
            filter={`url(#bm-glow-${uid})`}
          />

          {/* points */}
          {readings.map((r, i) => {
            const abnormal = r.value > range.high || r.value < range.low;
            const isSel = selected === i;
            return (
              <circle
                key={r.date}
                cx={x(r.date)}
                cy={y(r.value)}
                r={isSel ? 6 : 4}
                tabIndex={0}
                role="button"
                aria-label={`${short(r.date)}: ${fmtVal(r.value)} ${displayUnit}${abnormal ? ", outside range" : ""}`}
                onClick={() => setSelected(i)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    setSelected(i);
                  }
                }}
                className={cn(
                  "cursor-pointer transition-all duration-200 focus-visible:outline-none",
                  abnormal ? "fill-risk-high stroke-card" : "fill-info stroke-card",
                  isSel && "stroke-2"
                )}
                strokeWidth={isSel ? 2.5 : 1.5}
                style={
                  isSel
                    ? {
                        filter: `drop-shadow(0 0 5px color-mix(in oklab, ${abnormal ? "var(--risk-high)" : "var(--info)"} 60%, transparent))`,
                      }
                    : undefined
                }
              />
            );
          })}
        </svg>
      </div>

      {/* Selected reading */}
      {sel ? (
        <div
          className={cn(
            "mt-2 rounded-xl border p-3 text-sm transition-colors duration-300",
            selAbnormal ? "border-risk-high/40 bg-risk-high/5" : "border-border bg-background"
          )}
        >
          <div className="flex items-baseline justify-between gap-2">
            <span className="font-semibold tabular-nums text-foreground">
              {fmtVal(sel.value)} {displayUnit}
            </span>
            <span className="text-xs text-muted-foreground">
              {new Date(sel.date).toLocaleDateString("en-GB", {
                day: "numeric",
                month: "long",
                year: "numeric",
              })}
            </span>
          </div>
          <p className="mt-1 text-[12px] leading-5 text-muted-foreground">
            {selAbnormal ? (
              <>
                Above the laboratory range. Single readings vary with fasting
                state and lab method — the trend matters more than one point.
                Discuss persistent elevation with your clinician; this view is
                informational, not a diagnosis.
              </>
            ) : (
              <>
                Within the laboratory range
                {baseline
                  ? sel.value <= baseline
                    ? " and at or below your personal baseline."
                    : ", slightly above your personal baseline."
                  : "."}
              </>
            )}
          </p>
        </div>
      ) : null}
    </div>
  );
}

registry/default/fintech/market-depth.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface DepthLevel {
  price: number;
  qty: number;
  orders: number;
}

export interface MarketDepthProps
  extends React.HTMLAttributes<HTMLDivElement> {
  symbol: string;
  /** Best-first (descending price) bid levels. */
  bids: DepthLevel[];
  /** Best-first (ascending price) ask levels. */
  asks: DepthLevel[];
  lastPrice: number;
  /** Average traded price marker. */
  atp?: number;
  onLevelSelect?: (side: "bid" | "ask", level: DepthLevel) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const nf = new Intl.NumberFormat("en-IN");
const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

/** Deterministic demo ladder around a mid price. */
export function generateDepth(mid: number, tick = 0.05, levels = 7) {
  const mk = (side: 1 | -1): DepthLevel[] =>
    Array.from({ length: levels }, (_, i) => {
      const seed = Math.sin((mid + side * i) * 7.13) * 10_000;
      const r = seed - Math.floor(seed);
      return {
        price: +(mid + side * tick * (i + 1)).toFixed(2),
        qty: Math.round(300 + r * 4200),
        orders: 1 + Math.round(r * 14),
      };
    });
  return { bids: mk(-1), asks: mk(1) };
}

/* ------------------------------------------------------------------ */
/* Ladder                                                               */
/* ------------------------------------------------------------------ */

function Row({
  side,
  level,
  maxQty,
  best,
  onSelect,
}: {
  side: "bid" | "ask";
  level: DepthLevel;
  maxQty: number;
  best: boolean;
  onSelect?: (side: "bid" | "ask", level: DepthLevel) => void;
}) {
  const barRef = React.useRef<HTMLSpanElement>(null);
  const reduced = useReducedMotion();
  const pct = Math.round((level.qty / maxQty) * 100);

  /* Qty bars breathe to their new size on every update. */
  useGSAP(
    () => {
      if (!barRef.current) return;
      if (reduced) {
        gsap.set(barRef.current, { width: `${pct}%` });
        return;
      }
      gsap.to(barRef.current, {
        width: `${pct}%`,
        duration: 0.45,
        ease: "power2.out",
        overwrite: true,
      });
    },
    { dependencies: [pct, reduced] }
  );

  return (
    <button
      type="button"
      onClick={() => onSelect?.(side, level)}
      aria-label={`${side} ${nf2.format(level.price)}, quantity ${nf.format(level.qty)}, ${level.orders} orders`}
      className={cn(
        "relative grid w-full grid-cols-[1fr_auto_auto] items-center gap-2 rounded-md px-2 py-1 text-right font-mono text-[12px] tabular-nums transition-colors duration-150",
        "hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
        best && "font-semibold"
      )}
    >
      <span
        ref={barRef}
        aria-hidden="true"
        className={cn(
          "absolute inset-y-0.5 rounded-sm opacity-15",
          side === "bid" ? "right-0 bg-bid" : "left-0 bg-ask"
        )}
        style={{ width: 0 }}
      />
      <span className="relative text-left text-muted-foreground">
        {level.orders}
      </span>
      <span className="relative text-muted-foreground">{nf.format(level.qty)}</span>
      <span
        className={cn(
          "relative w-16",
          side === "bid" ? "text-bid" : "text-ask"
        )}
      >
        {nf2.format(level.price)}
      </span>
    </button>
  );
}

/**
 * Live bid/ask depth ladder: quantity bars grow from the outside in,
 * the spread sits in the middle, and last price flashes directionally.
 */
export function MarketDepth({
  symbol,
  bids,
  asks,
  lastPrice,
  atp,
  onLevelSelect,
  className,
  ref,
  ...rest
}: MarketDepthProps) {
  const reduced = useReducedMotion();
  const prevLast = React.useRef(lastPrice);
  const [flash, setFlash] = React.useState<"up" | "down" | null>(null);

  React.useEffect(() => {
    if (reduced || lastPrice === prevLast.current) {
      prevLast.current = lastPrice;
      return;
    }
    setFlash(lastPrice > prevLast.current ? "up" : "down");
    prevLast.current = lastPrice;
    const t = setTimeout(() => setFlash(null), 600);
    return () => clearTimeout(t);
  }, [lastPrice, reduced]);

  const maxQty = Math.max(1, ...bids.map((b) => b.qty), ...asks.map((a) => a.qty));
  const spread = asks[0] && bids[0] ? asks[0].price - bids[0].price : 0;
  const bidTotal = bids.reduce((s, b) => s + b.qty, 0);
  const askTotal = asks.reduce((s, a) => s + a.qty, 0);
  const bidShare = Math.round((bidTotal / (bidTotal + askTotal)) * 100);

  return (
    <div
      ref={ref}
      data-slot="market-depth"
      className={cn(
