        <span>Orders</span>
        <span className="ml-6">Qty</span>
        <span className="text-right">Price</span>
      </div>

      {/* Asks (worst to best, so the spread meets in the middle) */}
      <div className="mt-1 flex flex-col-reverse">
        {asks.map((a, i) => (
          <Row key={a.price} side="ask" level={a} maxQty={maxQty} best={i === 0} onSelect={onLevelSelect} />
        ))}
      </div>

      <div className="my-1 flex items-center justify-between rounded-md bg-muted/60 px-2 py-1 text-[11px]">
        <span className="text-muted-foreground">
          Spread <span className="font-mono tabular-nums text-foreground">{nf2.format(spread)}</span>
        </span>
        {atp ? (
          <span className="text-muted-foreground">
            ATP <span className="font-mono tabular-nums text-foreground">{nf2.format(atp)}</span>
          </span>
        ) : null}
      </div>

      <div className="flex flex-col">
        {bids.map((b, i) => (
          <Row key={b.price} side="bid" level={b} maxQty={maxQty} best={i === 0} onSelect={onLevelSelect} />
        ))}
      </div>

      <p className="mt-2 px-1 text-[10px] text-muted-foreground">
        Tap a level to prefill an order · simulated feed
      </p>
    </div>
  );
}

registry/default/fintech/sip-simulator.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Math                                                                 */
/* ------------------------------------------------------------------ */

export interface SipInputs {
  monthly: number;
  years: number;
  /** Expected annual return, %. */
  returnPct: number;
  /** Annual step-up of the contribution, %. */
  stepUpPct: number;
  /** Assumed inflation for the real-value line, %. */
  inflationPct: number;
}

export interface SipYearPoint {
  year: number;
  invested: number;
  value: number;
}

export function simulateSip({
  monthly,
  years,
  returnPct,
  stepUpPct,
}: Omit<SipInputs, "inflationPct">): SipYearPoint[] {
  const r = returnPct / 100 / 12;
  const points: SipYearPoint[] = [];
  let value = 0;
  let invested = 0;
  let contribution = monthly;
  for (let y = 1; y <= years; y++) {
    for (let m = 0; m < 12; m++) {
      value = value * (1 + r) + contribution;
      invested += contribution;
    }
    points.push({ year: y, invested, value });
    contribution *= 1 + stepUpPct / 100;
  }
  return points;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);
const lakh = (n: number) =>
  n >= 1e7 ? `₹${(n / 1e7).toFixed(2)}Cr` : n >= 1e5 ? `₹${(n / 1e5).toFixed(1)}L` : `₹${inr(n)}`;

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

export interface SipSimulatorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  defaults?: Partial<SipInputs>;
  /** Optional goal amount to mark on the chart. */
  goal?: number;
  ref?: React.Ref<HTMLDivElement>;
}

const W = 480;
const H = 170;
const PAD = { l: 8, r: 8, t: 12, b: 18 };

/**
 * SIP goal simulator: sliders drive a compounding projection; the growth
 * area redraws with a morphing path, the corpus rolls via NumberFlow and
 * the invested/growth split bar re-balances on every change.
 */
export function SipSimulator({
  defaults,
  goal,
  className,
  ref,
  ...rest
}: SipSimulatorProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [monthly, setMonthly] = React.useState(defaults?.monthly ?? 25_000);
  const [years, setYears] = React.useState(defaults?.years ?? 15);
  const [returnPct, setReturnPct] = React.useState(defaults?.returnPct ?? 12);
  const [stepUpPct, setStepUpPct] = React.useState(defaults?.stepUpPct ?? 5);
  const inflationPct = defaults?.inflationPct ?? 5;

  const points = React.useMemo(
    () => simulateSip({ monthly, years, returnPct, stepUpPct }),
    [monthly, years, returnPct, stepUpPct]
  );
  const final = points[points.length - 1];
  const growth = final.value - final.invested;
  const realValue = final.value / Math.pow(1 + inflationPct / 100, years);
  const growthShare = Math.round((growth / final.value) * 100);
  const goalYear = goal ? points.find((p) => p.value >= goal)?.year : undefined;

  /* Chart paths */
  const vMax = Math.max(final.value, goal ?? 0) * 1.05;
  const x = (year: number) => PAD.l + (year / years) * (W - PAD.l - PAD.r);
  const y = (v: number) => H - PAD.b - (v / vMax) * (H - PAD.t - PAD.b);
  const area = (key: "value" | "invested") =>
    `M${x(0)},${y(0)} ` +
    points.map((p) => `L${x(p.year)},${y(p[key])}`).join(" ") +
    ` L${x(years)},${y(0)} Z`;

  // Top edge of the value area, drawn as a glowing stroke.
  const valueLine =
    `M${x(0)},${y(0)} ` + points.map((p) => `L${x(p.year)},${y(p.value)}`).join(" ");

  const valueRef = React.useRef<SVGPathElement>(null);
  const investedRef = React.useRef<SVGPathElement>(null);
  const valueLineRef = React.useRef<SVGPathElement>(null);

  /* Paths morph to the new projection instead of snapping. */
  useGSAP(
    () => {
      const pairs: [SVGPathElement | null, string][] = [
        [valueRef.current, area("value")],
        [investedRef.current, area("invested")],
        [valueLineRef.current, valueLine],
      ];
      for (const [el, d] of pairs) {
        if (!el) continue;
        if (reduced) el.setAttribute("d", d);
        else gsap.to(el, { attr: { d }, duration: 0.5, ease: "power2.out", overwrite: true });
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    { dependencies: [points, reduced, goal] }
  );

  const slider = (
    label: string,
    value: number,
    set: (v: number) => void,
    min: number,
    max: number,
    step: number,
    fmt: (v: number) => string
  ) => (
    <label className="flex flex-col gap-1 text-xs">
      <span className="flex justify-between text-muted-foreground">
        {label}
        <span className="font-medium tabular-nums text-foreground">{fmt(value)}</span>
      </span>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        aria-label={label}
        onChange={(e) => set(parseFloat(e.target.value))}
        className="accent-primary"
      />
    </label>
  );

  return (
    <div
      ref={rootRef}
      data-slot="sip-simulator"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <div>
          <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
            Projected corpus · {years}y
          </p>
          <p className="text-2xl font-semibold tracking-tight text-foreground">
            <NumberFlow value={Math.round(final.value)} prefix="₹" locale="en-IN" trend />
          </p>
        </div>
        <div className="text-right text-[11px] text-muted-foreground">
          <p>
            Real value (at {inflationPct}% inflation):{" "}
            <span className="font-medium tabular-nums text-foreground">{lakh(realValue)}</span>
          </p>
          {goal ? (
            <p>
              Goal {lakh(goal)}:{" "}
              {goalYear ? (
                <span className="font-medium text-success">reached in year {goalYear}</span>
              ) : (
                <span className="font-medium text-warning">not reached — raise SIP or horizon</span>
              )}
            </p>
          ) : null}
        </div>
      </div>

      {/* Chart */}
      <svg
        viewBox={`0 0 ${W} ${H}`}
        role="img"
        aria-label={`Projection: ₹${inr(final.invested)} invested grows to ₹${inr(final.value)} over ${years} years`}
        className="mt-3 w-full"
      >
        <defs>
          <linearGradient id={`sip-growth-${uid}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--market-up)" stopOpacity={0.35} />
            <stop offset="100%" stopColor="var(--market-up)" stopOpacity={0.04} />
          </linearGradient>
          <linearGradient id={`sip-invested-${uid}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="var(--info)" stopOpacity={0.9} />
            <stop offset="100%" stopColor="var(--info)" stopOpacity={0.35} />
          </linearGradient>
          <filter id={`sip-glow-${uid}`} x="-5%" y="-40%" width="110%" height="180%">
            <feDropShadow dx="0" dy="1" stdDeviation="2.5" floodColor="var(--market-up)" floodOpacity="0.35" />
          </filter>
        </defs>
        <path ref={valueRef} d={area("value")} fill={`url(#sip-growth-${uid})`} />
        <path ref={investedRef} d={area("invested")} fill={`url(#sip-invested-${uid})`} />
        <path
          ref={valueLineRef}
          d={valueLine}
          fill="none"
          stroke="var(--market-up)"
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          filter={`url(#sip-glow-${uid})`}
        />
        {goal ? (
          <>
            <line
              x1={PAD.l}
              x2={W - PAD.r}
              y1={y(Math.min(goal, vMax))}
              y2={y(Math.min(goal, vMax))}
              strokeDasharray="4 4"
              className="stroke-warning"
            />
            <text x={W - PAD.r} y={y(Math.min(goal, vMax)) - 4} textAnchor="end" className="fill-warning text-[9px] font-medium">
              goal
            </text>
          </>
        ) : null}
        {[0.25, 0.5, 0.75, 1].map((f) => (
          <text
            key={f}
            x={x(years * f)}
            y={H - 5}
            textAnchor="middle"
            className="fill-muted-foreground text-[9px] tabular-nums"
          >
            {Math.round(years * f)}y
          </text>
        ))}
      </svg>

      {/* Invested vs growth split */}
      <div className="mt-1 flex h-2 overflow-hidden rounded-full ring-1 ring-inset ring-border/40" aria-hidden="true">
        <span
          className="transition-all duration-500"
          style={{
            width: `${100 - growthShare}%`,
            background: "linear-gradient(90deg, color-mix(in oklab, var(--info) 70%, transparent), var(--info))",
          }}
        />
        <span
          className="flex-1"
          style={{
            background: "linear-gradient(90deg, color-mix(in oklab, var(--market-up) 55%, transparent), var(--market-up))",
          }}
        />
      </div>
      <div className="mt-1 flex justify-between text-[11px] text-muted-foreground">
        <span>
          Invested <span className="font-medium tabular-nums text-foreground">{lakh(final.invested)}</span>
        </span>
        <span>
          Growth <span className="font-medium tabular-nums text-market-up">{lakh(growth)}</span> ({growthShare}%)
        </span>
      </div>

      {/* Controls */}
      <div className="mt-4 grid gap-x-6 gap-y-3 sm:grid-cols-2">
        {slider("Monthly SIP", monthly, setMonthly, 1_000, 200_000, 1_000, (v) => `₹${inr(v)}`)}
        {slider("Horizon", years, setYears, 1, 35, 1, (v) => `${v} years`)}
        {slider("Expected return", returnPct, setReturnPct, 4, 18, 0.5, (v) => `${v}% p.a.`)}
        {slider("Annual step-up", stepUpPct, setStepUpPct, 0, 15, 1, (v) => `${v}%`)}
      </div>
      <p className="mt-3 text-[10px] leading-4 text-muted-foreground">
        Illustration with constant returns — actual returns vary. Not
        investment advice.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Spinner } from "@/registry/default/ui/spinner";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type PaymentScenario = "success" | "failed" | "refunded";

export interface PaymentStatusProps
  extends React.HTMLAttributes<HTMLDivElement> {
  amount: number;
  currency?: string;
  reference: string;
  method?: string;
  /** Which lifecycle to play. Default "success". */
  scenario?: PaymentScenario;
  /** Replays the timeline when this changes. */
  playKey?: React.Key;
  /** ms between stage transitions. Default 1000. */
  speed?: number;
  onSettled?: (scenario: PaymentScenario) => void;
  ref?: React.Ref<HTMLDivElement>;
}

interface Stage {
  key: string;
  label: string;
  detail: string;
  state: "done" | "active" | "pending" | "failed" | "refund";
}

const BASE_STAGES = [
  { key: "initiated", label: "Initiated", detail: "Payment request created" },
  { key: "authorised", label: "Authorised", detail: "Issuer approved the charge" },
  { key: "captured", label: "Captured", detail: "Funds reserved for settlement" },
  { key: "settled", label: "Settled", detail: "Funds credited to your account" },
] as const;

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * One payment, its whole lifecycle: stages light up in sequence with
 * check-draws; failures stop the rail in red with a reason; refunds play
 * a second branch back to the customer.
 */
export function PaymentStatus({
  amount,
  currency = "₹",
  reference,
  method = "UPI",
  scenario = "success",
  playKey,
  speed = 1000,
  onSettled,
  className,
  ref,
  ...rest
}: PaymentStatusProps) {
  const reduced = useReducedMotion();
  // progress: number of completed base stages; then refund stages
  const failAt = 2; // capture fails in the failed scenario
  const totalBase = BASE_STAGES.length;
  const [progress, setProgress] = React.useState(0);
  const [refundProgress, setRefundProgress] = React.useState(0);

  React.useEffect(() => {
    let cancelled = false;
    setProgress(reduced ? totalBase : 0);
    setRefundProgress(0);
    if (reduced) {
      if (scenario === "failed") setProgress(failAt);
      if (scenario === "refunded") setRefundProgress(2);
      onSettled?.(scenario);
      return;
    }
    (async () => {
      const wait = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
      const target = scenario === "failed" ? failAt : totalBase;
      for (let i = 1; i <= target; i++) {
        await wait(speed);
        if (cancelled) return;
        setProgress(i);
      }
      if (scenario === "refunded") {
        for (let i = 1; i <= 2; i++) {
          await wait(speed);
          if (cancelled) return;
          setRefundProgress(i);
        }
      }
      onSettled?.(scenario);
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scenario, playKey, speed, reduced]);

  const stages: Stage[] = BASE_STAGES.map((s, i) => {
    if (scenario === "failed" && i === failAt)
      return {
        ...s,
        label: "Capture failed",
        detail: "Issuer declined: insufficient funds (05)",
        state: progress >= failAt ? "failed" : progress === i ? "active" : "pending",
      };
    if (scenario === "failed" && i > failAt) return { ...s, state: "pending" };
    return {
      ...s,
      state: progress > i ? "done" : progress === i ? "active" : "pending",
    };
  });

  const refundStages: Stage[] =
    scenario === "refunded"
      ? [
          { key: "refund-init", label: "Refund initiated", detail: "Full amount reversed by merchant", state: refundProgress > 0 ? "refund" : progress >= totalBase && refundProgress === 0 ? "active" : "pending" },
          { key: "refund-done", label: "Refunded", detail: "5–7 working days to the source account", state: refundProgress > 1 ? "refund" : refundProgress === 1 ? "active" : "pending" },
        ]
      : [];

  const headline =
    scenario === "failed" && progress >= failAt
      ? { text: "Payment failed", tone: "text-destructive" }
      : scenario === "refunded" && refundProgress > 1
        ? { text: "Refunded", tone: "text-info" }
        : progress >= totalBase && scenario === "success"
          ? { text: "Settled", tone: "text-success" }
          : { text: "Processing", tone: "text-muted-foreground" };

  return (
    <div
      ref={ref}
      data-slot="payment-status"
      className={cn(
        "w-full max-w-sm rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      <div className="flex items-start justify-between gap-2">
        <div>
          <p className="text-xl font-semibold tabular-nums text-foreground">
            {currency}
            {new Intl.NumberFormat("en-IN", { minimumFractionDigits: 2 }).format(amount)}
          </p>
          <p className="text-[11px] text-muted-foreground">
            {reference} · {method}
          </p>
        </div>
        <span className={cn("text-xs font-semibold", headline.tone)} aria-live="polite">
          {headline.text}
        </span>
      </div>

      <ol className="mt-4 flex flex-col">
        {[...stages, ...refundStages].map((s, i, all) => (
          <StageRow key={s.key} stage={s} last={i === all.length - 1} />
        ))}
      </ol>

      {scenario === "failed" && progress >= failAt ? (
        <p className="mt-2 rounded-lg bg-destructive/10 px-2.5 py-1.5 text-[11px] leading-4 text-destructive">
          No funds were captured. The authorisation hold releases
          automatically within 24 hours — safe to retry with another method.
        </p>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Stage row                                                            */
/* ------------------------------------------------------------------ */

function StageRow({ stage, last }: { stage: Stage; last: boolean }) {
  const ref = React.useRef<HTMLLIElement>(null);
  const checkRef = React.useRef<SVGPathElement>(null);
  const reduced = useReducedMotion();
  const settled = stage.state === "done" || stage.state === "failed" || stage.state === "refund";

  useGSAP(
    () => {
      if (!checkRef.current || !settled) return;
      if (reduced) {
        gsap.set(checkRef.current, { strokeDashoffset: 0 });
        return;
      }
      gsap.fromTo(
        checkRef.current,
        { strokeDashoffset: 1 },
        { strokeDashoffset: 0, duration: 0.4, ease: "power2.out" }
      );
    },
    { dependencies: [settled, reduced], scope: ref }
  );

  return (
    <li ref={ref} className="flex gap-3">
      <div className="flex flex-col items-center">
        <span
          className={cn(
            "relative flex size-5 items-center justify-center rounded-full transition-colors duration-300",
            stage.state === "done" && "bg-success text-white",
            stage.state === "refund" && "bg-info text-white",
            stage.state === "failed" && "bg-destructive text-white",
            stage.state === "active" && "bg-primary/10",
            stage.state === "pending" && "bg-muted"
          )}
        >
          {settled ? (
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3" aria-hidden="true">
              {stage.state === "failed" ? (
                <path ref={checkRef} d="M18 6 6 18M6 6l12 12" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
              ) : (
                <path ref={checkRef} d="M5 13l4 4L19 7" pathLength={1} strokeDasharray={1} strokeDashoffset={1} />
              )}
            </svg>
          ) : stage.state === "active" ? (
            <Spinner size="sm" />
          ) : null}
        </span>
        {!last ? (
          <span
            className={cn(
              "my-0.5 min-h-4 w-px flex-1 transition-colors duration-500",
              stage.state === "done" ? "bg-success/50" : stage.state === "refund" ? "bg-info/50" : "bg-border"
            )}
          />
        ) : null}
      </div>
      <div className="pb-3">
        <p
          className={cn(
            "text-sm leading-5",
            stage.state === "pending" ? "text-muted-foreground" : "font-medium text-foreground",
            stage.state === "failed" && "text-destructive"
          )}
        >
          {stage.label}
        </p>
        <p className="text-[11px] leading-4 text-muted-foreground">{stage.detail}</p>
      </div>
    </li>
  );
}

registry/default/health/medication-timel:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Badge } from "@/registry/default/ui/badge";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface Medication {
  name: string;
  dose: string;
  frequency: string;
  /** Day index (0-based) the course starts/ends within the visible window. */
  startDay: number;
  endDay: number;
  /** Adherence per day: taken, missed or upcoming. Index = day - startDay. */
  adherence: ("taken" | "missed" | "upcoming")[];
  /** Days until refill runs out, if low. */
  refillInDays?: number;
}

export interface MedicationInteraction {
  a: string;
  b: string;
  note: string;
}

export interface MedicationTimelineProps
  extends React.HTMLAttributes<HTMLDivElement> {
  medications: Medication[];
  interactions?: MedicationInteraction[];
  /** Days in the visible window. Default 28. */
  windowDays?: number;
  /** 0-based index of "today" within the window. Default 20. */
  today?: number;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_MEDICATIONS: Medication[] = [
  {
    name: "Metformin",
    dose: "500 mg",
    frequency: "2× daily",
    startDay: 0,
    endDay: 27,
    adherence: Array.from({ length: 28 }, (_, i) =>
      i > 20 ? "upcoming" : i === 6 || i === 14 ? "missed" : "taken"
    ),
  },
  {
    name: "Atorvastatin",
    dose: "10 mg",
    frequency: "1× nightly",
    startDay: 4,
    endDay: 27,
    adherence: Array.from({ length: 24 }, (_, i) =>
      i + 4 > 20 ? "upcoming" : i === 9 ? "missed" : "taken"
    ),
    refillInDays: 4,
  },
  {
    name: "Vitamin D3",
    dose: "60k IU",
    frequency: "weekly",
    startDay: 0,
    endDay: 27,
    adherence: Array.from({ length: 28 }, (_, i) =>
      i % 7 !== 0 ? "upcoming" : i > 20 ? "upcoming" : "taken"
    ),
  },
];

export const DEMO_INTERACTIONS: MedicationInteraction[] = [
  {
    a: "Metformin",
    b: "Atorvastatin",
    note: "Generally safe together; monitor for muscle pain and report it early.",
  },
];

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * A month of medication at a glance: course bars grow in, adherence dots
 * cascade (missed doses in warning), refills flag before they run out and
 * interactions link the two rows they concern.
 */
export function MedicationTimeline({
  medications,
  interactions = [],
  windowDays = 28,
  today = 20,
  className,
  ref,
  ...rest
}: MedicationTimelineProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);
  const [selected, setSelected] = React.useState<string | null>(null);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-course]"));
      const dots = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-dose]"));
      if (reduced) {
        gsap.set(bars, { scaleX: 1, opacity: 1 });
        gsap.set(dots, { scale: 1, opacity: 1 });
        return;
      }
      gsap.fromTo(
        bars,
        { scaleX: 0, opacity: 0, transformOrigin: "left center" },
        { scaleX: 1, opacity: 1, duration: 0.6, ease: "power3.out", stagger: 0.12 }
      );
      gsap.fromTo(
        dots,
        { scale: 0, opacity: 0 },
        { scale: 1, opacity: 1, duration: 0.3, ease: "back.out(2)", stagger: 0.008, delay: 0.35 }
      );
    },
    { dependencies: [reduced, medications], scope: rootRef }
  );

  const pct = (day: number) => (day / (windowDays - 1)) * 100;
  const adherenceStats = (m: Medication) => {
    const past = m.adherence.filter((a) => a !== "upcoming");
    const taken = past.filter((a) => a === "taken").length;
    return { taken, past: past.length, pct: past.length ? Math.round((taken / past.length) * 100) : 100 };
  };

  return (
    <div
      ref={rootRef}
      data-slot="medication-timeline"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">Medications · last 4 weeks</h3>
        <span className="text-[11px] text-muted-foreground">tap a row for details</span>
      </div>

      <div className="relative mt-4 flex flex-col gap-5">
        {/* today line */}
        <span
          aria-hidden="true"
          className="absolute bottom-0 top-1 w-px"
          style={{
            left: `${pct(today)}%`,
            background: "linear-gradient(180deg, var(--info), color-mix(in oklab, var(--info) 20%, transparent))",
          }}
        />
        <span
          aria-hidden="true"
          className="absolute top-1 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-info"
          style={{ left: `${pct(today)}%`, boxShadow: "0 0 6px color-mix(in oklab, var(--info) 70%, transparent)" }}
        />
        <span
          className="absolute -top-1 -translate-x-1/2 text-[9px] font-medium uppercase text-info"
          style={{ left: `${pct(today)}%` }}
        >
          today
        </span>

        {medications.map((m) => {
          const stats = adherenceStats(m);
          const isSel = selected === m.name;
          return (
            <button
              key={m.name}
              type="button"
              aria-pressed={isSel}
              onClick={() => setSelected((s) => (s === m.name ? null : m.name))}
              className={cn(
                "group rounded-lg p-1 pt-2 text-left transition-colors duration-200",
                isSel ? "bg-muted/70" : "hover:bg-muted/40",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              <div className="flex items-baseline justify-between gap-2 px-1">
                <span className="text-xs font-medium text-foreground">
                  {m.name} <span className="text-muted-foreground">{m.dose} · {m.frequency}</span>
                </span>
                <span
                  className={cn(
                    "text-[11px] tabular-nums",
                    stats.pct >= 90 ? "text-success" : stats.pct >= 75 ? "text-warning" : "text-risk-high"
                  )}
                >
                  {stats.pct}% adherence
                </span>
              </div>
              {/* course bar + dose dots */}
              <div className="relative mt-1.5 h-5 px-1">
                <span
                  data-course
                  aria-hidden="true"
                  className="absolute top-1/2 h-1.5 -translate-y-1/2 rounded-full"
                  style={{
                    left: `${pct(m.startDay)}%`,
                    width: `${pct(m.endDay) - pct(m.startDay)}%`,
                    background: "linear-gradient(90deg, color-mix(in oklab, var(--info) 22%, transparent), color-mix(in oklab, var(--success) 18%, transparent))",
                  }}
                />
                {m.adherence.map((a, i) => {
                  const day = m.startDay + i;
                  if (day >= windowDays) return null;
                  return (
                    <span
                      key={day}
                      data-dose
                      aria-hidden="true"
                      className={cn(
                        "absolute top-1/2 size-2 -translate-x-1/2 -translate-y-1/2 rounded-full",
                        a === "taken" && "bg-success ring-2 ring-success/20",
                        a === "missed" && "bg-warning ring-2 ring-warning/30",
                        a === "upcoming" && "border border-border bg-background"
                      )}
                      style={{ left: `${pct(day)}%` }}
                    />
                  );
                })}
                {m.refillInDays != null ? (
                  <Badge
                    variant="outline"
                    pulse
                    className="absolute -top-1 right-0 text-[9px] text-warning"
                  >
                    Refill in {m.refillInDays}d
                  </Badge>
                ) : null}
              </div>
              {isSel ? (
                <p className="mt-1 px-1 text-[11px] leading-4 text-muted-foreground">
                  {stats.taken}/{stats.past} doses taken.{" "}
                  {m.adherence.includes("missed")
                    ? "Missed doses shown in amber — don't double up; take the next scheduled dose."
                    : "No missed doses in this window."}
                </p>
              ) : null}
            </button>
          );
        })}
      </div>

      {interactions.length > 0 ? (
        <div className="mt-4 flex flex-col gap-1.5">
          {interactions.map((ix) => (
            <p
              key={`${ix.a}-${ix.b}`}
              className="rounded-lg border border-info/30 bg-info/5 px-2.5 py-1.5 text-[11px] leading-4 text-foreground"
            >
              <span className="font-semibold">{ix.a} + {ix.b}:</span> {ix.note}
            </p>
          ))}
        </div>
      ) : null}
      <p className="mt-3 text-[10px] text-muted-foreground">
        Legend: green taken · amber missed · hollow upcoming. Informational —
        follow your prescriber&apos;s instructions.
      </p>
    </div>
  );
}

registry/default/health/clinical-risk.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface RiskFactor {
  label: string;
  /** Contribution weight, -1..1. Positive raises risk. */
  weight: number;
  detail?: string;
}

export interface ClinicalRiskProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title: string;
  /** Risk score 0..100. */
  score: number;
  factors: RiskFactor[];
  missingData?: string[];
  recommendation?: string;
  onEscalate?: () => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_CARDIO_RISK: Pick<
  ClinicalRiskProps,
  "title" | "score" | "factors" | "missingData" | "recommendation"
> = {
  title: "10-year cardiovascular risk",
  score: 34,
  factors: [
    { label: "LDL trending down", weight: -0.35, detail: "158 → 101 mg/dL over 9 months" },
    { label: "HbA1c 6.1%", weight: 0.4, detail: "Pre-diabetic range" },
    { label: "Blood pressure 138/88", weight: 0.5, detail: "Stage-1 hypertension range" },
    { label: "Non-smoker", weight: -0.3 },
    { label: "Family history", weight: 0.45, detail: "Parent with early CAD" },
  ],
  missingData: ["Recent lipoprotein(a)", "Resting ECG"],
  recommendation:
    "Risk is moderate and modifiable: blood-pressure control and continued LDL reduction have the largest effect. Re-score after the missing tests.",
};

const riskBand = (score: number) =>
  score < 25
    ? { label: "Low", cls: "text-risk-low", stroke: "stroke-risk-low" }
    : score < 55
      ? { label: "Moderate", cls: "text-risk-medium", stroke: "stroke-risk-medium" }
      : { label: "High", cls: "text-risk-high", stroke: "stroke-risk-high" };

/* ------------------------------------------------------------------ */
/* Component                                                            */
/* ------------------------------------------------------------------ */

/**
 * A clinician-review risk summary: the gauge arc sweeps to the score,
 * factor bars grow from the center (protective left, adverse right) and
 * the copy stays explicitly decision-support, not diagnosis.
 */
export function ClinicalRisk({
  title,
  score,
  factors,
  missingData = [],
  recommendation,
  onEscalate,
  className,
  ref,
  ...rest
}: ClinicalRiskProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const arcRef = React.useRef<SVGPathElement>(null);
  const scoreRef = React.useRef<HTMLSpanElement>(null);
  const uid = React.useId().replace(/[^a-zA-Z0-9]/g, "");
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const band = riskBand(score);
  const maxW = Math.max(...factors.map((f) => Math.abs(f.weight)), 0.01);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-factor]"));
      if (reduced) {
        if (arcRef.current) gsap.set(arcRef.current, { strokeDashoffset: 1 - score / 100 });
        if (scoreRef.current) scoreRef.current.textContent = String(score);
        gsap.set(bars, { scaleX: 1, opacity: 1 });
        return;
      }
      if (arcRef.current)
        gsap.fromTo(
          arcRef.current,
          { strokeDashoffset: 1 },
          { strokeDashoffset: 1 - score / 100, duration: 1.1, ease: "power3.inOut" }
        );
      if (scoreRef.current) {
        const counter = { v: 0 };
        gsap.to(counter, {
          v: score,
          duration: 1.1,
          ease: "power3.inOut",
          onUpdate: () => {
            if (scoreRef.current) scoreRef.current.textContent = String(Math.round(counter.v));
          },
        });
      }
      gsap.fromTo(
        bars,
        { scaleX: 0, opacity: 0 },
        { scaleX: 1, opacity: 1, duration: 0.5, ease: "power3.out", stagger: 0.08, delay: 0.5 }
      );
    },
    { dependencies: [score, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="clinical-risk"
      className={cn(
        "w-full max-w-md rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      <h3 className="text-sm font-semibold text-foreground">{title}</h3>

      {/* Gauge */}
      <div className="mt-2 flex items-center gap-4">
        <div
          className="relative shrink-0"
          role="meter"
          aria-label={`${title}: ${score} of 100, ${band.label}`}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={score}
        >
          <svg viewBox="0 0 100 62" className="w-32 overflow-visible">
            <defs>
              <linearGradient id={`gauge-${uid}`} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="var(--risk-low)" />
                <stop offset="50%" stopColor="var(--risk-medium)" />
                <stop offset="100%" stopColor="var(--risk-high)" />
              </linearGradient>
            </defs>
            <path
              d="M10,55 A45,45 0 0 1 90,55"
              fill="none"
              strokeWidth={9}
              strokeLinecap="round"
              className="stroke-muted/70"
            />
            <path
              ref={arcRef}
              d="M10,55 A45,45 0 0 1 90,55"
              fill="none"
              strokeWidth={9}
              strokeLinecap="round"
              pathLength={1}
              strokeDasharray={1}
              strokeDashoffset={1}
              stroke={`url(#gauge-${uid})`}
              style={{ filter: `drop-shadow(0 1px 4px color-mix(in oklab, ${band.label === "High" ? "var(--risk-high)" : band.label === "Moderate" ? "var(--risk-medium)" : "var(--risk-low)"} 45%, transparent))` }}
            />
          </svg>
          <div className="absolute inset-x-0 bottom-0 text-center">
            <span ref={scoreRef} className="text-2xl font-semibold tabular-nums text-foreground">
              0
            </span>
            <span className="text-xs text-muted-foreground">/100</span>
          </div>
        </div>
        <div>
          <p className={cn("text-sm font-semibold", band.cls)}>{band.label} risk</p>
          <p className="mt-0.5 text-[11px] leading-4 text-muted-foreground">
            Decision support for clinician review — not a diagnosis.
          </p>
        </div>
      </div>

      {/* Factors: protective ← | → adverse */}
      <div className="mt-4">
        <div className="flex justify-between text-[10px] uppercase tracking-wide text-muted-foreground">
          <span>Protective</span>
          <span>Adverse</span>
        </div>
        <ul className="mt-1.5 flex flex-col gap-2">
          {factors.map((f) => {
            const adverse = f.weight > 0;
            const width = (Math.abs(f.weight) / maxW) * 50;
            return (
              <li key={f.label} className="text-xs">
                <div className="relative h-2.5 overflow-hidden rounded-full bg-muted/70 ring-1 ring-inset ring-border/40">
                  <span aria-hidden="true" className="absolute inset-y-0 left-1/2 z-10 w-px bg-border" />
                  <span
                    data-factor
                    className={cn(
                      "absolute inset-y-0 rounded-full",
                      adverse ? "left-1/2 origin-left" : "right-1/2 origin-right"
                    )}
                    style={{
                      width: `${width}%`,
                      background: adverse
                        ? "linear-gradient(90deg, color-mix(in oklab, var(--risk-high) 55%, transparent), var(--risk-high))"
                        : "linear-gradient(270deg, color-mix(in oklab, var(--risk-low) 55%, transparent), var(--risk-low))",
                    }}
                  />
                </div>
                <div className="mt-0.5 flex justify-between gap-2">
                  <span className="font-medium text-foreground">{f.label}</span>
                  {f.detail ? (
                    <span className="text-right text-muted-foreground">{f.detail}</span>
                  ) : null}
                </div>
              </li>
            );
          })}
        </ul>
      </div>

      {missingData.length > 0 ? (
        <p className="mt-3 rounded-lg bg-muted/60 px-2.5 py-1.5 text-[11px] leading-4 text-muted-foreground">
          <span className="font-semibold text-foreground">Missing data:</span>{" "}
          {missingData.join(", ")} — the score has wider uncertainty until these
          are available.
        </p>
      ) : null}

      {recommendation ? (
        <p className="mt-2 text-[12px] leading-5 text-foreground">{recommendation}</p>
      ) : null}

      <div className="mt-3 flex gap-2">
        <Button size="sm" variant="outline" className="flex-1" onClick={onEscalate}>
          Send to clinician review
        </Button>
      </div>
    </div>
  );
}

registry/default/health/vitals-monitor.t:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Synthetic ECG                                                        */
/* ------------------------------------------------------------------ */

/** One cardiac cycle sampled at phase 0..1: P wave, QRS complex, T wave. */
function ecgSample(phase: number): number {
  const g = (c: number, w: number, h: number) =>
    h * Math.exp(-((phase - c) ** 2) / (2 * w * w));
  return (
    g(0.18, 0.025, 0.12) + // P
    g(0.395, 0.016, -0.18) + // Q
    g(0.42, 0.014, 1) + // R
    g(0.445, 0.018, -0.28) + // S
    g(0.62, 0.045, 0.28) // T
  );
}

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface VitalsMonitorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  patient?: string;
  /** Baseline heart rate. Default 72. */
  heartRate?: number;
  spo2?: number;
  systolic?: number;
  diastolic?: number;
  temperature?: number;
  /** Simulate a tachycardia alarm: HR climbs and the card enters alarm state. */
  alarm?: boolean;
  /** HR above this triggers the alarm styling. Default 110. */
  hrAlarmAt?: number;
  ref?: React.Ref<HTMLDivElement>;
}

const W = 320;
const H = 72;
const SAMPLES = 240;

/**
 * A live patient vitals card: the ECG trace draws continuously with a
 * fading tail, the rate rolls via NumberFlow, and out-of-range values put
 * the whole card into a pulsing alarm state.
 */
export function VitalsMonitor({
  patient = "Bed 12",
  heartRate = 72,
  spo2 = 98,
  systolic = 122,
  diastolic = 78,
  temperature = 36.8,
  alarm = false,
  hrAlarmAt = 110,
  className,
  ref,
  ...rest
}: VitalsMonitorProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const pathRef = React.useRef<SVGPathElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [hr, setHr] = React.useState(heartRate);
  const targetHr = alarm ? Math.max(hrAlarmAt + 18, heartRate + 40) : heartRate;
  const inAlarm = hr >= hrAlarmAt;

  /* HR drifts toward its target with small jitter. */
  React.useEffect(() => {
    if (reduced) {
      setHr(targetHr);
      return;
    }
    const id = setInterval(() => {
      setHr((h) => {
        const drift = (targetHr - h) * 0.25;
        const jitter = (Math.random() - 0.5) * 2;
        return Math.round(h + drift + jitter);
      });
    }, 1200);
    return () => clearInterval(id);
  }, [targetHr, reduced]);

  /* Continuous trace: a ring buffer of samples advanced by rAF, drawn
     straight into the path's `d` — no React re-render per frame. */
  React.useEffect(() => {
    const path = pathRef.current;
    if (!path) return;
    const buf = new Array(SAMPLES).fill(0);
    let phase = 0;
    let raf = 0;
    let last = performance.now();
    let head = 0;

    const draw = () => {
      let d = "";
      for (let i = 0; i < SAMPLES; i++) {
        const v = buf[(head + i) % SAMPLES];
        const px = (i / (SAMPLES - 1)) * W;
        const py = H * 0.72 - v * H * 0.55;
        d += `${i === 0 ? "M" : "L"}${px.toFixed(1)},${py.toFixed(1)}`;
      }
      path.setAttribute("d", d);
    };

    if (reduced) {
      // Static two-beat strip instead of animation.
      for (let i = 0; i < SAMPLES; i++) buf[i] = ecgSample(((i / SAMPLES) * 2) % 1);
      draw();
      return;
    }

    const tick = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const beatsPerSec = hr / 60;
      // advance ~90 samples/sec worth of trace
      const advance = Math.max(1, Math.round(dt * 90));
      for (let i = 0; i < advance; i++) {
        phase = (phase + (beatsPerSec / 90) * 1) % 1;
        buf[head] = ecgSample(phase);
        head = (head + 1) % SAMPLES;
      }
      draw();
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [hr, reduced]);

  /* Alarm state pulses the card border. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      gsap.killTweensOf(root);
      if (inAlarm && !reduced) {
        gsap.to(root, {
          boxShadow: "0 0 0 3px var(--risk-high)",
          duration: 0.7,
          ease: "power1.inOut",
          repeat: -1,
          yoyo: true,
        });
      } else {
        gsap.set(root, { boxShadow: "0 0 0 0px transparent" });
      }
    },
    { dependencies: [inAlarm, reduced] }
  );

  const tiles: { label: string; value: React.ReactNode; unit: string; bad?: boolean }[] = [
    {
      label: "HR",
      value: <NumberFlow value={hr} />,
      unit: "bpm",
      bad: inAlarm,
    },
    { label: "SpO₂", value: spo2, unit: "%", bad: spo2 < 94 },
    { label: "BP", value: `${systolic}/${diastolic}`, unit: "mmHg", bad: systolic > 140 },
    { label: "Temp", value: temperature.toFixed(1), unit: "°C", bad: temperature >= 38 },
  ];

  return (
    <div
      ref={rootRef}
      data-slot="vitals-monitor"
      className={cn(
        "w-full max-w-sm rounded-2xl border bg-card p-4 transition-colors duration-300",
        inAlarm ? "border-risk-high" : "border-border",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <span className="text-sm font-semibold text-foreground">{patient}</span>
        {inAlarm ? (
          <span className="flex items-center gap-1.5 text-xs font-semibold text-risk-high" role="alert">
            <span className="relative flex size-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-risk-high opacity-60" />
              <span className="relative inline-flex size-2 rounded-full bg-risk-high" />
            </span>
            Tachycardia
          </span>
        ) : (
          <span className="text-xs text-success">All vitals in range</span>
        )}
      </div>

      {/* ECG strip */}
      <div className="mt-3 overflow-hidden rounded-lg bg-foreground/[0.04] dark:bg-background">
        <svg viewBox={`0 0 ${W} ${H}`} className="w-full" aria-hidden="true">
          {/* grid */}
          {Array.from({ length: 7 }, (_, i) => (
            <line
              key={`v${i}`}
              x1={(i + 1) * (W / 8)}
              x2={(i + 1) * (W / 8)}
              y1={0}
              y2={H}
              className="stroke-border/60"
              strokeWidth={0.5}
            />
          ))}
          {Array.from({ length: 3 }, (_, i) => (
            <line
              key={`h${i}`}
              y1={(i + 1) * (H / 4)}
              y2={(i + 1) * (H / 4)}
              x1={0}
              x2={W}
              className="stroke-border/60"
              strokeWidth={0.5}
            />
          ))}
          <path
            ref={pathRef}
            fill="none"
            strokeWidth={1.6}
            strokeLinejoin="round"
            className={cn(inAlarm ? "stroke-risk-high" : "stroke-success")}
          />
        </svg>
      </div>
      <p className="sr-only" aria-live="polite">
        Heart rate {hr} beats per minute{inAlarm ? ", tachycardia alarm active" : ""}.
      </p>

      {/* Tiles */}
      <div className="mt-3 grid grid-cols-4 gap-2">
        {tiles.map((t) => (
          <div
            key={t.label}
            className={cn(
              "rounded-lg border px-2 py-1.5 text-center transition-colors duration-300",
              t.bad ? "border-risk-high/50 bg-risk-high/5" : "border-border bg-background"
            )}
          >
            <p className="text-[9px] font-medium uppercase tracking-wide text-muted-foreground">
              {t.label}
            </p>
            <p
              className={cn(
                "text-sm font-semibold tabular-nums",
                t.bad ? "text-risk-high" : "text-foreground"
              )}
            >
              {t.value}
            </p>
            <p className="text-[9px] text-muted-foreground">{t.unit}</p>
          </div>
        ))}
      </div>
      <p className="mt-2 text-[10px] text-muted-foreground">
        Simulated telemetry for demonstration — not a medical device.
      </p>
    </div>
  );
}

registry/default/fintech/order-ticket.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type OrderType = "market" | "limit" | "stop" | "stop-limit";

export interface PlacedOrder {
  side: "buy" | "sell";
  type: OrderType;
  qty: number;
  price?: number;
  triggerPrice?: number;
}

export interface OrderTicketProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  symbol: string;
  lastPrice: number;
  bestBid: number;
  bestAsk: number;
  lotSize?: number;
  /** Margin available to trade. Drives the risk-blocked state. */
  availableMargin?: number;
  /** Margin factor per unit of notional. Default 0.14 (index options-ish). */
  marginFactor?: number;
  onPlaced?: (order: PlacedOrder) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);
const nf2 = new Intl.NumberFormat("en-IN", {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
});

// Indian-broker conventions: SL = stop-loss limit (trigger + limit price),
// SL-M = stop-loss market (trigger, fills at market).
const TYPES: { key: OrderType; label: string }[] = [
  { key: "market", label: "Market" },
  { key: "limit", label: "Limit" },
  { key: "stop-limit", label: "SL" },
  { key: "stop", label: "SL-M" },
];

type Stage = "form" | "review" | "placing" | "filling" | "done";

/* ------------------------------------------------------------------ */
/* Ticket                                                               */
/* ------------------------------------------------------------------ */

/**
 * Advanced order ticket: buy/sell recolors the whole ticket, order types
 * reveal the fields they need, margin and charges roll live, over-margin
 * blocks the flow, and placement plays a partial-fill progress state.
 */
export function OrderTicket({
  symbol,
  lastPrice,
  bestBid,
  bestAsk,
  lotSize = 75,
  availableMargin = 250_000,
  marginFactor = 0.14,
  onPlaced,
  className,
  ref,
  ...rest
}: OrderTicketProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [side, setSide] = React.useState<"buy" | "sell">("buy");
  const [type, setType] = React.useState<OrderType>("limit");
  const [lots, setLots] = React.useState(1);
  const [price, setPrice] = React.useState(lastPrice.toFixed(2));
  const [trigger, setTrigger] = React.useState((lastPrice * 0.995).toFixed(2));
  const [chargesOpen, setChargesOpen] = React.useState(false);
  const [stage, setStage] = React.useState<Stage>("form");
  const [filled, setFilled] = React.useState(0);

  const qty = lots * lotSize;
  const effPrice =
    type === "market" ? (side === "buy" ? bestAsk : bestBid) : parseFloat(price) || 0;
  const notional = qty * effPrice;
  const margin = Math.round(notional * marginFactor);
  const brokerage = 20;
  const stt = Math.round(notional * 0.000625);
  const other = Math.round(notional * 0.000053) + 15;
  const charges = brokerage + stt + other;
  const overMargin = margin > availableMargin;
  const needsPrice = type === "limit" || type === "stop-limit";
  const needsTrigger = type === "stop" || type === "stop-limit";

  const chargesRef = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!chargesRef.current) return;
      if (reduced) {
        gsap.set(chargesRef.current, { height: chargesOpen ? "auto" : 0, opacity: chargesOpen ? 1 : 0 });
        return;
      }
      gsap.to(chargesRef.current, {
        height: chargesOpen ? "auto" : 0,
        opacity: chargesOpen ? 1 : 0,
        duration: 0.3,
        ease: "power3.out",
      });
    },
    { dependencies: [chargesOpen, reduced] }
  );

  const place = async () => {
    setStage("placing");
    await new Promise((r) => setTimeout(r, 900));
    setStage("filling");
    // partial fill: 40% then complete
    setFilled(Math.round(qty * 0.4));
    await new Promise((r) => setTimeout(r, 1300));
    setFilled(qty);
    await new Promise((r) => setTimeout(r, 500));
    setStage("done");
    onPlaced?.({
      side,
      type,
      qty,
      ...(needsPrice ? { price: parseFloat(price) } : {}),
      ...(needsTrigger ? { triggerPrice: parseFloat(trigger) } : {}),
    });
  };

  const reset = () => {
    setStage("form");
    setFilled(0);
  };

  const numField = (
    label: string,
    value: string,
    set: (v: string) => void,
    disabled = false
  ) => (
    <label className="flex min-w-0 flex-1 flex-col gap-1 text-[11px] text-muted-foreground">
      {label}
      <input
        inputMode="decimal"
        value={value}
        disabled={disabled}
        aria-label={label}
        onChange={(e) => set(e.target.value.replace(/[^0-9.]/g, ""))}
        className={cn(
          "h-9 w-full min-w-0 rounded-lg border border-input bg-background px-2.5 font-mono text-sm tabular-nums text-foreground",
          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          disabled && "opacity-50"
        )}
      />
    </label>
  );

  return (
    <div
      ref={rootRef}
      data-slot="order-ticket"
      className={cn(
        "w-full max-w-sm rounded-2xl border bg-card p-4 transition-colors duration-300",
        side === "buy" ? "border-market-up/40" : "border-market-down/40",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-sm font-semibold text-foreground">{symbol}</span>
        <span className="font-mono text-xs tabular-nums text-muted-foreground">
          <span className="text-bid">{nf2.format(bestBid)}</span>
          {" / "}
          <span className="text-ask">{nf2.format(bestAsk)}</span>
        </span>
      </div>

      {stage === "form" || stage === "review" ? (
        <>
          {/* Side toggle */}
          <div className="mt-3 grid grid-cols-2 gap-1 rounded-lg bg-muted p-1" role="tablist" aria-label="Order side">
            {(["buy", "sell"] as const).map((s) => (
              <button
                key={s}
                role="tab"
                aria-selected={side === s}
                onClick={() => setSide(s)}
                className={cn(
                  "rounded-md py-1.5 text-xs font-semibold uppercase tracking-wide transition-colors duration-200",
                  side === s
                    ? s === "buy"
                      ? "bg-market-up text-white"
                      : "bg-market-down text-white"
                    : "text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {s}
              </button>
            ))}
          </div>

          {/* Order type */}
          <div className="mt-2 flex gap-1" role="tablist" aria-label="Order type">
            {TYPES.map((t) => (
              <button
                key={t.key}
                role="tab"
                aria-selected={type === t.key}
                onClick={() => setType(t.key)}
                className={cn(
                  "flex-1 rounded-md px-1 py-1 text-[11px] font-medium transition-colors duration-200",
                  type === t.key
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {t.label}
              </button>
            ))}
          </div>

          {/* Qty + prices */}
          <div className="mt-3 flex gap-2">
            <label className="flex w-24 flex-col gap-1 text-[11px] text-muted-foreground">
              Lots ({lotSize}/lot)
              <div className="flex h-9 items-stretch overflow-hidden rounded-lg border border-input">
                <button
                  type="button"
                  aria-label="Decrease lots"
                  onClick={() => setLots((l) => Math.max(1, l - 1))}
                  className="w-7 bg-muted text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  −
                </button>
                <span className="flex flex-1 items-center justify-center font-mono text-sm tabular-nums text-foreground">
                  {lots}
                </span>
                <button
                  type="button"
                  aria-label="Increase lots"
                  onClick={() => setLots((l) => Math.min(20, l + 1))}
                  className="w-7 bg-muted text-foreground transition-colors hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  +
                </button>
              </div>
            </label>
            {needsTrigger ? numField("Trigger", trigger, setTrigger) : null}
            {numField(
              type === "market" ? "Price (mkt)" : "Price",
              type === "market" ? nf2.format(effPrice) : price,
              setPrice,
              type === "market"
            )}
          </div>

          {/* Margin */}
          <div className="mt-3 flex items-baseline justify-between text-xs">
            <span className="text-muted-foreground">Margin required</span>
            <span
              className={cn(
                "font-semibold tabular-nums",
                overMargin ? "text-destructive" : "text-foreground"
              )}
            >
              <NumberFlow value={margin} prefix="₹" locale="en-IN" />
            </span>
          </div>
          <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-muted" aria-hidden="true">
            <span
              className={cn(
                "block h-full rounded-full transition-all duration-500",
                overMargin
                  ? "bg-destructive"
                  : side === "buy"
                    ? "bg-market-up"
                    : "bg-market-down"
              )}
              style={{ width: `${Math.min(100, (margin / availableMargin) * 100)}%` }}
            />
          </div>
          <p className="mt-1 text-[11px] tabular-nums text-muted-foreground">
            Available ₹{inr(availableMargin)}
            {overMargin ? (
              <span className="ml-1 font-medium text-destructive">
                — exceeds margin, reduce quantity
              </span>
            ) : null}
          </p>

          {/* Charges */}
          <button
            type="button"
            aria-expanded={chargesOpen}
            onClick={() => setChargesOpen((o) => !o)}
            className="mt-2 flex w-full justify-between rounded-md py-1 text-[11px] text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <span>Charges ≈ ₹{inr(charges)}</span>
            <span className={cn("transition-transform duration-300", chargesOpen && "rotate-180")}>▾</span>
          </button>
          <div ref={chargesRef} className="overflow-hidden" style={{ height: 0, opacity: 0 }}>
            <dl className="flex flex-col gap-1 py-1 text-[11px] tabular-nums text-muted-foreground">
              <div className="flex justify-between"><dt>Brokerage</dt><dd>₹{brokerage}</dd></div>
              <div className="flex justify-between"><dt>STT</dt><dd>₹{inr(stt)}</dd></div>
              <div className="flex justify-between"><dt>Exchange + GST + stamp</dt><dd>₹{inr(other)}</dd></div>
            </dl>
          </div>

          {/* Action */}
          {stage === "form" ? (
            <Button
              className={cn(
                "mt-3 w-full text-white",
                side === "buy"
                  ? "bg-market-up hover:bg-market-up/90"
                  : "bg-market-down hover:bg-market-down/90"
              )}
              disabled={overMargin || (needsPrice && !parseFloat(price))}
              onClick={() => setStage("review")}
            >
              Review {side} order
            </Button>
          ) : (
            <div className="mt-3 flex flex-col gap-2 rounded-xl border border-border bg-background p-3">
              <p className="text-xs text-foreground">
                <span className={cn("font-semibold uppercase", side === "buy" ? "text-market-up" : "text-market-down")}>
                  {side}
                </span>{" "}
                {qty} {symbol} · {TYPES.find((t) => t.key === type)?.label}
                {needsPrice ? ` @ ₹${price}` : " @ market"}
                {needsTrigger ? ` · trigger ₹${trigger}` : ""}
              </p>
              <p className="text-[11px] tabular-nums text-muted-foreground">
                Margin ₹{inr(margin)} + charges ₹{inr(charges)}
              </p>
              <div className="flex gap-2">
                <Button size="sm" variant="outline" onClick={() => setStage("form")}>
                  Edit
                </Button>
                <Button
                  size="sm"
                  className={cn(
                    "flex-1 text-white",
                    side === "buy"
                      ? "bg-market-up hover:bg-market-up/90"
                      : "bg-market-down hover:bg-market-down/90"
                  )}
                  onClick={place}
                >
                  Confirm
                </Button>
              </div>
            </div>
          )}
        </>
      ) : (
        <FillState
          stage={stage}
          side={side}
          qty={qty}
          filled={filled}
          symbol={symbol}
          onReset={reset}
        />
      )}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Placement / partial fill                                             */
/* ------------------------------------------------------------------ */

function FillState({
  stage,
  side,
  qty,
  filled,
  symbol,
  onReset,
}: {
  stage: Stage;
  side: "buy" | "sell";
  qty: number;
  filled: number;
  symbol: string;
  onReset: () => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const pct = Math.round((filled / qty) * 100);

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { opacity: 1, y: 0 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { opacity: 0, y: 12, filter: "blur(6px)" },
        { opacity: 1, y: 0, filter: "blur(0px)", duration: 0.4, ease: "power3.out", clearProps: "filter" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="mt-4 flex flex-col items-center gap-3 py-2 text-center">
      <p className="text-sm font-medium text-foreground">
        {stage === "placing"
          ? "Placing order…"
          : stage === "filling"
            ? pct < 100
              ? "Partially filled"
              : "Filling…"
            : "Order complete"}
      </p>
      <div
        className="h-2 w-full overflow-hidden rounded-full bg-muted"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={qty}
        aria-valuenow={filled}
        aria-label="Fill progress"
      >
        <span
          className={cn(
            "block h-full rounded-full transition-all duration-700 ease-out",
            side === "buy" ? "bg-market-up" : "bg-market-down"
          )}
          style={{ width: `${stage === "placing" ? 4 : pct}%` }}
        />
      </div>
      <p className="text-xs tabular-nums text-muted-foreground">
        {filled}/{qty} {symbol}
        {stage === "filling" && pct < 100 ? " · working the rest at your limit" : ""}
      </p>
      {stage === "done" ? (
        <Button size="sm" variant="outline" onClick={onReset}>
          New order
        </Button>
      ) : null}
    </div>
  );
}

registry/default/fintech/strategy-builde:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { blackScholes, smileIv } from "@/registry/default/lib/black-scholes";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface StrategyLeg {
  side: "buy" | "sell";
  type: "call" | "put";
  strike: number;
  premium: number;
  delta: number;
  theta: number;
  vega: number;
}

export type StrategyKey =
  | "long-call"
  | "bull-call-spread"
  | "straddle"
  | "strangle"
  | "iron-condor";

export const STRATEGIES: Record<StrategyKey, { label: string; legs: (atm: number, step: number) => { side: "buy" | "sell"; type: "call" | "put"; strike: number }[] }> = {
  "long-call": {
    label: "Long Call",
    legs: (atm) => [{ side: "buy", type: "call", strike: atm }],
  },
  "bull-call-spread": {
    label: "Bull Call Spread",
    legs: (atm, step) => [
      { side: "buy", type: "call", strike: atm },
      { side: "sell", type: "call", strike: atm + 2 * step },
    ],
  },
  straddle: {
    label: "Straddle",
    legs: (atm) => [
      { side: "buy", type: "call", strike: atm },
      { side: "buy", type: "put", strike: atm },
    ],
  },
  strangle: {
    label: "Strangle",
    legs: (atm, step) => [
      { side: "buy", type: "call", strike: atm + 2 * step },
      { side: "buy", type: "put", strike: atm - 2 * step },
    ],
  },
  "iron-condor": {
    label: "Iron Condor",
    legs: (atm, step) => [
      { side: "sell", type: "put", strike: atm - 2 * step },
      { side: "buy", type: "put", strike: atm - 4 * step },
      { side: "sell", type: "call", strike: atm + 2 * step },
      { side: "buy", type: "call", strike: atm + 4 * step },
    ],
  },
};

export interface StrategyBuilderProps
  extends React.HTMLAttributes<HTMLDivElement> {
  spot: number;
  /** Days to expiry used to price the legs. Default 7. */
  dte?: number;
  /** Strike interval. Default 100. */
  step?: number;
  lotSize?: number;
  defaultStrategy?: StrategyKey;
  ref?: React.Ref<HTMLDivElement>;
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);

/* ------------------------------------------------------------------ */
/* Builder                                                              */
/* ------------------------------------------------------------------ */

const W = 480;
const H = 190;
const PAD = { l: 10, r: 10, t: 14, b: 20 };

/**
 * Options strategy builder: pick a structure and the payoff curve morphs
 * to it — profit region in market-up, loss in market-down, breakevens
 * marked, leg Greeks totalled, and an expiry-spot scrubber that rolls the
 * P&L as you drag.
 */
export function StrategyBuilder({
  spot,
  dte = 7,
  step = 100,
  lotSize = 75,
  defaultStrategy = "bull-call-spread",
  className,
  ref,
  ...rest
}: StrategyBuilderProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const lineRef = React.useRef<SVGPathElement>(null);
  const areaRef = React.useRef<SVGPathElement>(null);
  const areaLossRef = React.useRef<SVGPathElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [strategy, setStrategy] = React.useState<StrategyKey>(defaultStrategy);
  const atm = Math.round(spot / step) * step;
  const [expirySpot, setExpirySpot] = React.useState(atm);

  /* Price the legs coherently. */
  const legs: StrategyLeg[] = React.useMemo(
    () =>
      STRATEGIES[strategy].legs(atm, step).map((l) => {
        const iv = smileIv(spot, l.strike);
        const g = blackScholes({ s: spot, k: l.strike, t: dte / 365, iv, side: l.type });
        const sign = l.side === "buy" ? 1 : -1;
        return {
          ...l,
          premium: g.price,
          delta: sign * g.delta,
          theta: sign * g.theta,
          vega: sign * g.vega,
        };
      }),
    [strategy, atm, step, spot, dte]
  );

  const payoffAt = React.useCallback(
    (s: number) =>
      legs.reduce((sum, l) => {
        const intrinsic = l.type === "call" ? Math.max(0, s - l.strike) : Math.max(0, l.strike - s);
        const sign = l.side === "buy" ? 1 : -1;
        return sum + sign * (intrinsic - l.premium);
      }, 0) * lotSize,
    [legs, lotSize]
  );

  /* Sample the payoff across ±10%. */
  const sMin = spot * 0.9;
  const sMax = spot * 1.1;
  const N = 80;
  const samples = React.useMemo(
    () =>
      Array.from({ length: N + 1 }, (_, i) => {
        const s = sMin + ((sMax - sMin) * i) / N;
        return { s, p: payoffAt(s) };
      }),
    [payoffAt, sMin, sMax]
  );
  const pMax = Math.max(...samples.map((d) => Math.abs(d.p)), 1);
  const x = (s: number) => PAD.l + ((s - sMin) / (sMax - sMin)) * (W - PAD.l - PAD.r);
  const y = (p: number) => H / 2 - (p / pMax) * (H / 2 - PAD.t);
  const zeroY = y(0);

  const linePath = samples
    .map((d, i) => `${i === 0 ? "M" : "L"}${x(d.s).toFixed(1)},${y(d.p).toFixed(1)}`)
    .join(" ");
  const areaPath = `${linePath} L${x(sMax).toFixed(1)},${zeroY} L${x(sMin).toFixed(1)},${zeroY} Z`;

  /* Breakevens: zero crossings. */
  const breakevens: number[] = [];
  for (let i = 1; i < samples.length; i++) {
    const a = samples[i - 1];
    const b = samples[i];
    if ((a.p <= 0 && b.p > 0) || (a.p >= 0 && b.p < 0)) {
      breakevens.push(a.s + ((0 - a.p) / (b.p - a.p)) * (b.s - a.s));
    }
  }

  const maxProfitRaw = Math.max(...samples.map((d) => d.p));
  const maxLossRaw = Math.min(...samples.map((d) => d.p));
  const edgeUp = samples[samples.length - 1].p >= maxProfitRaw - 1;
  const edgeDown = samples[0].p <= maxLossRaw + 1 && strategy !== "iron-condor";
  const netPremium = legs.reduce(
    (s, l) => s + (l.side === "buy" ? -1 : 1) * l.premium * lotSize,
    0
  );
  const totals = legs.reduce(
    (t, l) => ({ delta: t.delta + l.delta, theta: t.theta + l.theta, vega: t.vega + l.vega }),
    { delta: 0, theta: 0, vega: 0 }
  );

  /* The curve morphs between strategies. */
  useGSAP(
    () => {
      const items: [SVGPathElement | null, string][] = [
        [lineRef.current, linePath],
        [areaRef.current, areaPath],
        [areaLossRef.current, areaPath],
      ];
      for (const [el, d] of items) {
        if (!el) continue;
        if (reduced) el.setAttribute("d", d);
        else gsap.to(el, { attr: { d }, duration: 0.55, ease: "power3.inOut", overwrite: true });
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    { dependencies: [linePath, reduced] }
  );

  const pnlAtScrub = payoffAt(expirySpot);

  return (
    <div
      ref={rootRef}
      data-slot="strategy-builder"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Strategy picker */}
      <div className="flex flex-wrap gap-1.5" role="tablist" aria-label="Strategy">
        {(Object.keys(STRATEGIES) as StrategyKey[]).map((k) => (
          <button
            key={k}
            role="tab"
            aria-selected={strategy === k}
            onClick={() => setStrategy(k)}
            className={cn(
              "rounded-md px-2.5 py-1 text-xs font-medium transition-colors duration-200",
              strategy === k
                ? "bg-primary text-primary-foreground"
                : "bg-muted text-muted-foreground hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            {STRATEGIES[k].label}
          </button>
        ))}
      </div>

      {/* Payoff chart */}
      <svg
        viewBox={`0 0 ${W} ${H}`}
        className="mt-3 w-full"
        role="img"
        aria-label={`${STRATEGIES[strategy].label} payoff at expiry. Max profit ${edgeUp ? "unlimited" : `₹${inr(maxProfitRaw)}`}, max loss ${edgeDown ? "unlimited" : `₹${inr(Math.abs(maxLossRaw))}`}.`}
      >
        <defs>
          <clipPath id="duku-profit-clip">
            <rect x={0} y={0} width={W} height={zeroY} />
          </clipPath>
          <clipPath id="duku-loss-clip">
            <rect x={0} y={zeroY} width={W} height={H - zeroY} />
          </clipPath>
        </defs>
        <path ref={areaRef} d={areaPath} clipPath="url(#duku-profit-clip)" className="fill-market-up/15" />
        <path ref={areaLossRef} d={areaPath} clipPath="url(#duku-loss-clip)" className="fill-market-down/15" />
        <line x1={PAD.l} x2={W - PAD.r} y1={zeroY} y2={zeroY} className="stroke-border" />
        {/* spot + scrub markers */}
        <line x1={x(spot)} x2={x(spot)} y1={PAD.t} y2={H - PAD.b} strokeDasharray="3 3" className="stroke-muted-foreground/50" />
        <text x={x(spot)} y={H - 6} textAnchor="middle" className="fill-muted-foreground text-[9px]">spot</text>
        <line x1={x(expirySpot)} x2={x(expirySpot)} y1={PAD.t} y2={H - PAD.b} className="stroke-info" />
        <circle cx={x(expirySpot)} cy={y(pnlAtScrub)} r={4} className="fill-info stroke-card" strokeWidth={1.5} />
        {breakevens.map((b) => (
          <g key={b}>
            <line x1={x(b)} x2={x(b)} y1={zeroY - 6} y2={zeroY + 6} className="stroke-foreground" strokeWidth={1.5} />
            <text x={x(b)} y={zeroY - 9} textAnchor="middle" className="fill-foreground text-[9px] font-medium tabular-nums">
              {inr(Math.round(b))}
            </text>
          </g>
        ))}
        <path ref={lineRef} d={linePath} fill="none" strokeWidth={2} strokeLinejoin="round" className="stroke-primary" />
      </svg>

      {/* Expiry scrubber */}
      <label className="mt-1 flex items-center gap-3 text-xs text-muted-foreground">
        Expiry spot
        <input
          type="range"
          min={Math.ceil(sMin / 10) * 10}
          max={Math.floor(sMax / 10) * 10}
          step={10}
          value={expirySpot}
          aria-label="Expiry spot"
          onChange={(e) => setExpirySpot(parseInt(e.target.value, 10))}
          className="flex-1 accent-primary"
        />
        <span
          className={cn(
            "w-24 text-right font-semibold tabular-nums",
            pnlAtScrub >= 0 ? "text-market-up" : "text-market-down"
          )}
        >
          <NumberFlow
            value={Math.round(pnlAtScrub)}
            prefix={pnlAtScrub >= 0 ? "+₹" : "−₹"}
            locale="en-IN"
            trend
          />
        </span>
      </label>

      {/* Stats */}
      <div className="mt-3 grid grid-cols-2 gap-2 text-xs sm:grid-cols-4">
        {[
          ["Max profit", edgeUp ? "Unlimited" : `₹${inr(maxProfitRaw)}`, "text-market-up"],
          ["Max loss", edgeDown ? "Unlimited" : `₹${inr(Math.abs(maxLossRaw))}`, "text-market-down"],
          ["Net premium", `${netPremium >= 0 ? "+" : "−"}₹${inr(Math.abs(netPremium))}`, netPremium >= 0 ? "text-market-up" : "text-foreground"],
          ["Breakevens", breakevens.length ? breakevens.map((b) => inr(Math.round(b))).join(" / ") : "—", "text-foreground"],
        ].map(([label, value, cls]) => (
          <div key={label as string} className="rounded-lg border border-border bg-background px-2.5 py-1.5">
            <p className="text-[10px] uppercase tracking-wide text-muted-foreground">{label}</p>
            <p className={cn("font-semibold tabular-nums", cls as string)}>{value}</p>
          </div>
        ))}
      </div>

      {/* Legs */}
      <ul className="mt-3 flex flex-col gap-1.5">
        {legs.map((l, i) => (
          <li
            key={`${l.side}-${l.type}-${l.strike}-${i}`}
            className="flex items-center justify-between gap-2 rounded-lg border border-border bg-background px-2.5 py-1.5 text-xs"
          >
            <span className="flex items-center gap-2">
              <span
                className={cn(
                  "rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase",
                  l.side === "buy" ? "bg-market-up/15 text-market-up" : "bg-market-down/15 text-market-down"
                )}
              >
                {l.side}
              </span>
              <span className="font-medium text-foreground">
                {inr(l.strike)} {l.type.toUpperCase()}
              </span>
            </span>
            <span className="tabular-nums text-muted-foreground">
              ₹{l.premium.toFixed(2)} · Δ {l.delta.toFixed(2)}
            </span>
          </li>
        ))}
      </ul>

      <p className="mt-2 flex flex-wrap justify-between gap-2 text-[11px] tabular-nums text-muted-foreground">
        <span>
          Net Δ {totals.delta.toFixed(2)} · Θ ₹{(totals.theta * lotSize).toFixed(0)}/day · V ₹
          {(totals.vega * lotSize).toFixed(0)}/1% IV
        </span>
        <span>1 lot = {lotSize} · payoff at expiry · not advice</span>
      </p>
    </div>
  );
}

registry/default/fintech/bank-linking.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Badge } from "@/registry/default/ui/badge";
import { OTPInput } from "@/registry/default/fintech/otp-input";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface LinkableBank {
  id: string;
  name: string;
  /** Tailwind color class for the tile mark. */
  tone: string;
}

export interface LinkableAccount {
  id: string;
  label: string;
  masked: string;
  balance?: string;
}

export interface BankLinkingProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onComplete"> {
  banks?: LinkableBank[];
  accounts?: LinkableAccount[];
  /** The demo OTP that succeeds. Any other code shows the error state. */
  validOtp?: string;
  /** Consent validity shown on the review screen, in months. */
  consentMonths?: number;
  onLinked?: (detail: { bank: string; accountIds: string[] }) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_BANKS: LinkableBank[] = [
  { id: "hdfc", name: "HDFC Bank", tone: "bg-blue-600" },
  { id: "icici", name: "ICICI Bank", tone: "bg-orange-600" },
  { id: "sbi", name: "SBI", tone: "bg-sky-700" },
  { id: "axis", name: "Axis Bank", tone: "bg-rose-700" },
  { id: "kotak", name: "Kotak", tone: "bg-red-600" },
  { id: "yes", name: "Yes Bank", tone: "bg-indigo-600" },
];

export const DEMO_ACCOUNTS: LinkableAccount[] = [
  { id: "sav", label: "Savings", masked: "••6482", balance: "₹1,84,210" },
  { id: "sal", label: "Salary", masked: "••1039", balance: "₹52,904" },
];

const PERMISSIONS = [
  { key: "balance", label: "Account balance", detail: "Refreshed daily" },
  { key: "transactions", label: "Transactions", detail: "Last 12 months, then ongoing" },
  { key: "profile", label: "Account holder name", detail: "For verification only" },
] as const;

type Step = 0 | 1 | 2 | 3 | 4;

/* ------------------------------------------------------------------ */
/* Flow                                                                 */
/* ------------------------------------------------------------------ */

/**
 * Account-aggregator style bank linking: pick a bank, review exactly what
 * is shared and for how long, confirm with OTP, choose accounts, and land
 * on a connection-health card with reauthentication date.
 */
export function BankLinking({
  banks = DEMO_BANKS,
  accounts = DEMO_ACCOUNTS,
  validOtp = "246810",
  consentMonths = 12,
  onLinked,
  className,
  ref,
  ...rest
}: BankLinkingProps) {
  const reduced = useReducedMotion();
  const [step, setStep] = React.useState<Step>(0);
  const [bank, setBank] = React.useState<LinkableBank | null>(null);
  const [otpError, setOtpError] = React.useState(false);
  const [otpAttempt, setOtpAttempt] = React.useState(0);
  const [verifying, setVerifying] = React.useState(false);
  const [picked, setPicked] = React.useState<string[]>(accounts.map((a) => a.id));
  const [linking, setLinking] = React.useState(false);

  const panelRef = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!panelRef.current) return;
      if (reduced) {
        gsap.set(panelRef.current, { x: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        panelRef.current,
        { x: 24, opacity: 0, filter: "blur(6px)" },
        { x: 0, opacity: 1, filter: "blur(0px)", duration: 0.4, ease: "power3.out", clearProps: "filter" }
      );
    },
    { dependencies: [step], scope: panelRef }
  );

  const submitOtp = async (code: string) => {
    setVerifying(true);
    await new Promise((r) => setTimeout(r, 900));
    setVerifying(false);
    if (code !== validOtp) {
      setOtpError(true);
      // clear the cells for a fresh attempt once the shake has landed
      setTimeout(() => {
        setOtpError(false);
        setOtpAttempt((a) => a + 1);
      }, 1200);
      return;
    }
    setStep(3);
  };

  const finish = async () => {
    setLinking(true);
    await new Promise((r) => setTimeout(r, 1300));
    setLinking(false);
    setStep(4);
    if (bank) onLinked?.({ bank: bank.id, accountIds: picked });
  };

  const stepTitle = [
    "Choose your bank",
    "Review consent",
    "Verify it's you",
    "Select accounts",
    "Connected",
  ][step];

  return (
    <div
      ref={ref}
      data-slot="bank-linking"
      className={cn(
        "w-full max-w-sm rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">{stepTitle}</h3>
        <span className="text-[11px] tabular-nums text-muted-foreground">
          {Math.min(step + 1, 5)}/5
        </span>
      </div>
      <div className="mt-2 h-1 overflow-hidden rounded-full bg-muted" aria-hidden="true">
        <span
          className="block h-full rounded-full bg-primary transition-all duration-500 ease-out"
          style={{ width: `${((step + 1) / 5) * 100}%` }}
        />
      </div>

      <div ref={panelRef} className="mt-4">
        {step === 0 ? (
          <div className="grid grid-cols-3 gap-2">
            {banks.map((b) => (
              <button
                key={b.id}
                type="button"
                onClick={() => {
                  setBank(b);
                  setStep(1);
                }}
                className="flex flex-col items-center gap-1.5 rounded-xl border border-border bg-background p-3 transition-all duration-200 hover:border-primary/50 hover:bg-muted/50 active:scale-[0.98] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <span
                  aria-hidden="true"
                  className={cn(
                    "flex size-8 items-center justify-center rounded-full text-[11px] font-bold text-white",
                    b.tone
                  )}
                >
                  {b.name[0]}
                </span>
                <span className="text-[11px] font-medium text-foreground">{b.name}</span>
              </button>
            ))}
          </div>
        ) : null}

        {step === 1 && bank ? (
          <div className="flex flex-col gap-3">
            <p className="text-xs text-muted-foreground">
              <span className="font-medium text-foreground">{bank.name}</span> will share the
              following, read-only, for {consentMonths} months. You can revoke
              any time.
            </p>
            <ul className="flex flex-col gap-1.5">
              {PERMISSIONS.map((p) => (
                <li
                  key={p.key}
                  className="flex items-start justify-between gap-2 rounded-lg border border-border bg-background px-2.5 py-2 text-xs"
                >
                  <span className="font-medium text-foreground">{p.label}</span>
                  <span className="text-right text-muted-foreground">{p.detail}</span>
                </li>
              ))}
            </ul>
            <p className="text-[11px] leading-4 text-muted-foreground">
              We never see your bank credentials — the OTP goes to the number
              your bank has on record.
            </p>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setStep(0)}>
                Back
              </Button>
              <Button className="flex-1" onClick={() => setStep(2)}>
                Agree & continue
              </Button>
            </div>
          </div>
        ) : null}

        {step === 2 && bank ? (
          <div className="flex flex-col items-center gap-3">
            <p className="text-xs text-muted-foreground">
              Enter the 6-digit code sent by {bank.name}
              <span className="ml-1 rounded bg-muted px-1 py-0.5 font-mono text-[10px]">
                demo: {validOtp}
              </span>
            </p>
            <OTPInput key={otpAttempt} length={6} error={otpError} onComplete={submitOtp} />
            <p aria-live="polite" className="min-h-4 text-[11px]">
              {verifying ? (
                <span className="text-muted-foreground">Verifying…</span>
              ) : otpError ? (
                <span className="font-medium text-destructive">
                  That code didn&apos;t match — try again.
                </span>
              ) : null}
            </p>
            <Button variant="outline" size="sm" onClick={() => setStep(1)}>
              Back
            </Button>
          </div>
        ) : null}

        {step === 3 ? (
          <div className="flex flex-col gap-3">
            <ul className="flex flex-col gap-1.5">
              {accounts.map((a) => {
                const on = picked.includes(a.id);
                return (
                  <li key={a.id}>
                    <button
                      type="button"
                      role="checkbox"
                      aria-checked={on}
                      onClick={() =>
                        setPicked((p) =>
                          on ? p.filter((x) => x !== a.id) : [...p, a.id]
                        )
                      }
                      className={cn(
                        "flex w-full items-center justify-between gap-2 rounded-xl border px-3 py-2.5 text-left transition-all duration-200",
                        on ? "border-primary bg-primary/5" : "border-border bg-background",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      )}
                    >
                      <span>
                        <span className="block text-sm font-medium text-foreground">
                          {a.label} {a.masked}
                        </span>
                        {a.balance ? (
                          <span className="text-[11px] tabular-nums text-muted-foreground">
                            {a.balance}
                          </span>
                        ) : null}
                      </span>
                      <span
                        aria-hidden="true"
                        className={cn(
                          "flex size-5 items-center justify-center rounded-full border-2 transition-colors duration-200",
                          on ? "border-primary bg-primary text-primary-foreground" : "border-border"
                        )}
                      >
                        {on ? (
                          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" className="size-3">
                            <path d="M5 13l4 4L19 7" />
                          </svg>
                        ) : null}
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
            <Button
              className="w-full"
              disabled={picked.length === 0}
              loading={linking}
              onClick={finish}
            >
              Link {picked.length} account{picked.length === 1 ? "" : "s"}
            </Button>
          </div>
        ) : null}

        {step === 4 && bank ? (
          <div className="flex flex-col gap-3">
            <div className="flex items-center gap-3 rounded-xl border border-success/40 bg-success/5 p-3">
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-9 items-center justify-center rounded-full text-xs font-bold text-white",
                  bank.tone
                )}
              >
                {bank.name[0]}
              </span>
              <div className="flex-1">
                <p className="text-sm font-semibold text-foreground">{bank.name}</p>
                <p className="text-[11px] text-muted-foreground">
                  {picked.length} account{picked.length === 1 ? "" : "s"} · synced just now
                </p>
              </div>
              <Badge variant="success" pulse>
                Healthy
              </Badge>
            </div>
            <dl className="flex flex-col gap-1 rounded-xl border border-border bg-background p-3 text-[11px] tabular-nums text-muted-foreground">
              <div className="flex justify-between">
                <dt>Consent valid until</dt>
                <dd className="text-foreground">
                  {new Date(Date.now() + consentMonths * 30 * 864e5).toLocaleDateString("en-GB", { month: "short", year: "numeric" })}
                </dd>
              </div>
              <div className="flex justify-between">
                <dt>Next auto-sync</dt>
                <dd className="text-foreground">Tomorrow, 6:00 AM</dd>
              </div>
              <div className="flex justify-between">
                <dt>Reauthentication</dt>
                <dd className="text-foreground">Not needed for {consentMonths} months</dd>
              </div>
            </dl>
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                setStep(0);
                setBank(null);
                setPicked(accounts.map((a) => a.id));
              }}
            >
              Link another bank
            </Button>
          </div>
        ) : null}
      </div>
    </div>
  );
}

registry/default/fintech/expense-feed.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Badge } from "@/registry/default/ui/badge";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type ExpenseCategory =
  | "food"
  | "transport"
  | "subscriptions"
  | "shopping"
  | "utilities"
  | "income";

export interface ExpenseItem {
  id: string;
  merchant: string;
  day: string;
  amount: number;
  category: ExpenseCategory;
  /** Nth consecutive monthly charge → subscription badge. */
  recurringMonth?: number;
  /** Marks an unusually large charge with the multiple vs usual. */
  unusualMultiple?: number;
  /** Refund linked to an earlier transaction id. */
  refundOf?: string;
}

export interface ExpenseFeedProps
  extends React.HTMLAttributes<HTMLDivElement> {
  items?: ExpenseItem[];
  currency?: string;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_EXPENSES: ExpenseItem[] = [
  { id: "t1", merchant: "Swiggy", day: "Today", amount: -412, category: "food" },
  { id: "t2", merchant: "Netflix", day: "Today", amount: -649, category: "subscriptions", recurringMonth: 7 },
  { id: "t3", merchant: "Uber", day: "Today", amount: -284, category: "transport" },
  { id: "t4", merchant: "Croma", day: "Yesterday", amount: -42_499, category: "shopping", unusualMultiple: 9 },
  { id: "t5", merchant: "Salary · Acme Corp", day: "Yesterday", amount: 145_000, category: "income" },
  { id: "t6", merchant: "Spotify", day: "Yesterday", amount: -119, category: "subscriptions", recurringMonth: 14 },
  { id: "t7", merchant: "BESCOM", day: "Mon 8 Jul", amount: -1_840, category: "utilities" },
  { id: "t8", merchant: "Croma (refund)", day: "Mon 8 Jul", amount: 4_500, category: "shopping", refundOf: "t4" },
  { id: "t9", merchant: "Blinkit", day: "Mon 8 Jul", amount: -876, category: "food" },
];

const CATEGORY_META: Record<ExpenseCategory, { label: string; dot: string }> = {
  food: { label: "Food", dot: "bg-amber-500" },
  transport: { label: "Transport", dot: "bg-sky-500" },
  subscriptions: { label: "Subscriptions", dot: "bg-violet-500" },
  shopping: { label: "Shopping", dot: "bg-rose-500" },
  utilities: { label: "Utilities", dot: "bg-teal-500" },
  income: { label: "Income", dot: "bg-emerald-500" },
};

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(Math.abs(n));

/* ------------------------------------------------------------------ */
/* Feed                                                                 */
/* ------------------------------------------------------------------ */

/**
 * An expense feed that understands itself: merchants are categorised,
 * subscriptions counted, unusual charges flagged with how unusual they
 * are, refunds linked back to the original transaction — and category
 * filters re-cascade the list.
 */
export function ExpenseFeed({
  items = DEMO_EXPENSES,
  currency = "₹",
  className,
  ref,
  ...rest
}: ExpenseFeedProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [filter, setFilter] = React.useState<ExpenseCategory | "all">("all");
  const [query, setQuery] = React.useState("");
  const [linked, setLinked] = React.useState<string | null>(null);

  const visible = items.filter(
    (i) =>
      (filter === "all" || i.category === filter) &&
      i.merchant.toLowerCase().includes(query.toLowerCase())
  );
  const days = [...new Set(visible.map((i) => i.day))];
  const usedCategories = [...new Set(items.map((i) => i.category))];

  /* Rows cascade in whenever the visible set changes. */
  useGSAP(
    () => {
      const list = listRef.current;
      if (!list) return;
      const rows = gsap.utils.toArray<HTMLElement>(list.querySelectorAll("[data-row]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.3, ease: "power2.out", stagger: 0.035, overwrite: true }
      );
    },
    { dependencies: [filter, query, reduced], scope: listRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="expense-feed"
      className={cn(
        "w-full max-w-md rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Search + filters */}
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search merchants…"
        aria-label="Search transactions"
        className="h-9 w-full rounded-lg border border-input bg-background px-3 text-sm text-foreground placeholder:text-muted-foreground/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      />
      <div className="mt-2 flex flex-wrap gap-1.5">
        {(["all", ...usedCategories] as const).map((c) => (
          <button
            key={c}
            type="button"
            aria-pressed={filter === c}
            onClick={() => setFilter(c as ExpenseCategory | "all")}
            className={cn(
              "flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium transition-colors duration-200",
              filter === c
                ? "bg-primary text-primary-foreground"
                : "bg-muted text-muted-foreground hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            {c !== "all" ? (
              <span
                aria-hidden="true"
                className={cn("size-1.5 rounded-full", CATEGORY_META[c as ExpenseCategory].dot)}
              />
            ) : null}
            {c === "all" ? "All" : CATEGORY_META[c as ExpenseCategory].label}
          </button>
        ))}
      </div>

      {/* Feed */}
      <div ref={listRef} className="mt-3 flex flex-col gap-3">
        {days.length === 0 ? (
          <p className="rounded-lg bg-muted/50 px-3 py-6 text-center text-xs text-muted-foreground">
            Nothing matches — clear the search or pick another category.
          </p>
        ) : null}
        {days.map((day) => (
          <div key={day}>
            <p className="px-1 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
              {day}
            </p>
            <ul className="mt-1 flex flex-col gap-1">
              {visible
                .filter((i) => i.day === day)
                .map((i) => {
                  const meta = CATEGORY_META[i.category];
                  const isLinkTarget = linked === i.id || (linked != null && i.refundOf === linked);
                  return (
                    <li key={i.id} data-row>
                      <div
                        className={cn(
                          "flex items-center gap-2.5 rounded-xl border px-2.5 py-2 transition-colors duration-300",
                          i.unusualMultiple
                            ? "border-warning/50 bg-warning/5"
                            : isLinkTarget
                              ? "border-info/60 bg-info/5"
                              : "border-border bg-background"
                        )}
                      >
                        <span
                          aria-hidden="true"
                          className={cn(
                            "flex size-7 shrink-0 items-center justify-center rounded-full text-[10px] font-bold text-white",
                            meta.dot
                          )}
                        >
                          {i.merchant[0]}
                        </span>
                        <div className="min-w-0 flex-1">
                          <p className="truncate text-sm font-medium text-foreground">
                            {i.merchant}
                          </p>
                          <p className="flex flex-wrap items-center gap-1.5 text-[10px] text-muted-foreground">
                            {meta.label}
                            {i.recurringMonth ? (
                              <Badge variant="secondary" className="px-1 py-0 text-[9px]">
                                Subscription · month {i.recurringMonth}
                              </Badge>
                            ) : null}
                            {i.unusualMultiple ? (
                              <span className="font-medium text-warning">
                                {i.unusualMultiple}× your usual here
                              </span>
                            ) : null}
                            {i.refundOf ? (
                              <button
                                type="button"
                                onClick={() =>
                                  setLinked((l) => (l === i.refundOf ? null : i.refundOf!))
                                }
                                className="font-medium text-info underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                              >
                                refund — show original
                              </button>
                            ) : null}
                          </p>
                        </div>
                        <span
                          className={cn(
                            "shrink-0 font-mono text-sm tabular-nums",
                            i.amount > 0 ? "font-semibold text-market-up" : "text-foreground"
                          )}
                        >
                          {i.amount > 0 ? "+" : "−"}
                          {currency}
                          {inr(i.amount)}
                        </span>
                      </div>
                    </li>
                  );
                })}
            </ul>
          </div>
        ))}
      </div>
    </div>
  );
}

registry/default/enterprise/reconciliati:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface ReconPair {
  id: string;
  ledger: { ref: string; desc: string; amount: number };
  statement: { ref: string; desc: string; amount: number };
  /** Match confidence 0–1. */
  confidence: number;
}

export interface ReconciliationProps
  extends React.HTMLAttributes<HTMLDivElement> {
  pairs?: ReconPair[];
  /** Confidence at or above which "Accept all" applies. Default 0.95. */
  bulkThreshold?: number;
  onResolve?: (id: string, action: "accept" | "reject") => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_RECON: ReconPair[] = [
  {
    id: "r1",
    ledger: { ref: "INV-2041", desc: "Acme Corp · services", amount: 118_000 },
    statement: { ref: "NEFT-88123", desc: "ACME CORP PVT LTD", amount: 118_000 },
    confidence: 0.99,
  },
  {
    id: "r2",
    ledger: { ref: "INV-2044", desc: "Globex · retainer", amount: 90_000 },
    statement: { ref: "IMPS-11407", desc: "GLOBEX INDIA", amount: 90_000 },
    confidence: 0.97,
  },
  {
    id: "r3",
    ledger: { ref: "INV-2038", desc: "Initech · milestone 2", amount: 2_40_000 },
    statement: { ref: "RTGS-55019", desc: "INITECH SOLUTIONS", amount: 2_38_820 },
    confidence: 0.74,
  },
  {
    id: "r4",
    ledger: { ref: "INV-2047", desc: "Umbrella · onboarding", amount: 56_500 },
    statement: { ref: "UPI-99231", desc: "UMBRELA SVCS", amount: 56_500 },
    confidence: 0.88,
  },
];

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);

/* ------------------------------------------------------------------ */
/* Workspace                                                            */
/* ------------------------------------------------------------------ */

/**
 * Two-sided reconciliation: suggested ledger↔statement matches with
 * confidence, amount differences called out to the rupee, accept/reject
 * per pair (accepted pairs collapse away), bulk-accept above a threshold
 * and a live matched meter.
 */
export function Reconciliation({
  pairs = DEMO_RECON,
  bulkThreshold = 0.95,
  onResolve,
  className,
  ref,
  ...rest
}: ReconciliationProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [resolved, setResolved] = React.useState<Record<string, "accept" | "reject">>({});
  const open = pairs.filter((p) => !resolved[p.id]);
  const accepted = Object.values(resolved).filter((v) => v === "accept").length;
  const matchedPct = Math.round((accepted / pairs.length) * 100);
  const bulkable = open.filter((p) => p.confidence >= bulkThreshold);

  const resolve = (id: string, action: "accept" | "reject") => {
    const el = rootRef.current?.querySelector<HTMLElement>(`[data-pair="${id}"]`);
    const commit = () => {
      setResolved((r) => ({ ...r, [id]: action }));
      onResolve?.(id, action);
    };
    if (reduced || !el) {
      commit();
      return;
    }
    gsap.to(el, {
      x: action === "accept" ? 32 : -32,
      opacity: 0,
      height: 0,
      marginBottom: 0,
      duration: 0.35,
      ease: "power2.in",
      onComplete: commit,
    });
  };

  const bulkAccept = () => {
    for (const p of bulkable) resolve(p.id, "accept");
  };

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-pair]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 14, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.4, ease: "power3.out", stagger: 0.08 }
      );
    },
    { scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="reconciliation"
      className={cn(
        "w-full max-w-2xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Header + meter */}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">
          Bank reconciliation · July
        </h3>
        <Button
          size="sm"
          variant="outline"
          disabled={bulkable.length === 0}
          onClick={bulkAccept}
        >
          Accept all ≥{Math.round(bulkThreshold * 100)}% ({bulkable.length})
        </Button>
      </div>
      <div
        className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted"
        role="meter"
        aria-label="Matched share"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={matchedPct}
      >
        <span
          className="block h-full rounded-full bg-success transition-all duration-500 ease-out"
          style={{ width: `${matchedPct}%` }}
        />
      </div>
      <p className="mt-1 text-[11px] tabular-nums text-muted-foreground">
        {accepted}/{pairs.length} matched · {open.length} awaiting review
      </p>

      {/* Pairs */}
      <div className="mt-3 flex flex-col">
        {open.length === 0 ? (
          <div className="rounded-xl border border-success/40 bg-success/5 px-3 py-6 text-center">
            <p className="text-sm font-medium text-success">All matched</p>
            <p className="mt-0.5 text-[11px] text-muted-foreground">
              Decisions are logged to the audit trail with your user and timestamp.
            </p>
          </div>
        ) : null}
        {open.map((p) => {
          const diff = p.statement.amount - p.ledger.amount;
          const high = p.confidence >= bulkThreshold;
          return (
            <div key={p.id} data-pair={p.id} className="mb-2 overflow-hidden">
              <div
                className={cn(
                  "rounded-xl border p-3",
                  diff !== 0 ? "border-warning/50" : "border-border"
                )}
              >
                <div className="grid gap-2 sm:grid-cols-[1fr_auto_1fr]">
                  {/* Ledger side */}
                  <div className="min-w-0 rounded-lg bg-muted/50 px-2.5 py-2">
                    <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
                      Ledger · {p.ledger.ref}
                    </p>
                    <p className="truncate text-xs font-medium text-foreground">{p.ledger.desc}</p>
                    <p className="font-mono text-sm tabular-nums text-foreground">₹{inr(p.ledger.amount)}</p>
                  </div>
                  {/* Confidence link */}
                  <div className="flex items-center justify-center">
                    <span
                      className={cn(
                        "rounded-full px-2 py-0.5 text-[10px] font-semibold tabular-nums",
                        high
                          ? "bg-success/15 text-success"
                          : p.confidence >= 0.8
                            ? "bg-warning/15 text-warning"
                            : "bg-risk-high/15 text-risk-high"
                      )}
                    >
                      {Math.round(p.confidence * 100)}%
                    </span>
                  </div>
                  {/* Statement side */}
                  <div className="min-w-0 rounded-lg bg-muted/50 px-2.5 py-2 sm:text-right">
                    <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
                      Statement · {p.statement.ref}
                    </p>
                    <p className="truncate text-xs font-medium text-foreground">{p.statement.desc}</p>
                    <p className="font-mono text-sm tabular-nums text-foreground">₹{inr(p.statement.amount)}</p>
                  </div>
                </div>
                <div className="mt-2 flex items-center justify-between gap-2">
                  <p className="text-[11px] tabular-nums">
                    {diff === 0 ? (
                      <span className="text-muted-foreground">Amounts agree exactly</span>
                    ) : (
                      <span className="font-medium text-warning">
                        Δ ₹{inr(Math.abs(diff))} {diff < 0 ? "short" : "over"} — likely bank charges; verify before accepting
                      </span>
                    )}
                  </p>
                  <div className="flex gap-1.5">
                    <Button size="sm" variant="outline" onClick={() => resolve(p.id, "reject")}>
                      Reject
                    </Button>
                    <Button size="sm" onClick={() => resolve(p.id, "accept")}>
                      Accept match
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

registry/default/enterprise/audit-log.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Badge } from "@/registry/default/ui/badge";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type AuditAction = "created" | "updated" | "deleted" | "accessed";

export interface AuditEvent {
  id: string;
  actor: string;
  action: AuditAction;
  resource: string;
  timestamp: string;
  ip?: string;
  device?: string;
  /** Field-level before/after for updated events. */
  changes?: { field: string; before: string; after: string }[];
  /** Hash-chain integrity of this entry. */
  integrity?: "verified" | "tampered";
}

export interface AuditLogProps extends React.HTMLAttributes<HTMLDivElement> {
  events?: AuditEvent[];
  onExport?: (visible: AuditEvent[]) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_AUDIT: AuditEvent[] = [
  {
    id: "e1",
    actor: "priya@acme.in",
    action: "updated",
    resource: "customer/8412 · credit limit",
    timestamp: "Today 14:32",
    ip: "10.4.1.22",
    device: "Chrome · macOS",
    changes: [
      { field: "credit_limit", before: "₹2,00,000", after: "₹3,50,000" },
      { field: "review_note", before: "—", after: "Raised after 12m clean history" },
    ],
    integrity: "verified",
  },
  {
    id: "e2",
    actor: "svc-billing",
    action: "created",
    resource: "invoice/INV-2051",
    timestamp: "Today 13:05",
    ip: "10.4.9.8",
    device: "API key · billing-svc",
    integrity: "verified",
  },
  {
    id: "e3",
    actor: "rahul@acme.in",
    action: "deleted",
    resource: "webhook/stripe-legacy",
    timestamp: "Today 11:47",
    ip: "10.4.1.9",
    device: "Firefox · Windows",
    changes: [{ field: "endpoint", before: "https://old.acme.in/hooks", after: "—" }],
    integrity: "tampered",
  },
  {
    id: "e4",
    actor: "priya@acme.in",
    action: "accessed",
    resource: "report/pnl-q2 (export)",
    timestamp: "Yesterday 18:20",
    ip: "10.4.1.22",
    device: "Chrome · macOS",
    integrity: "verified",
  },
];

const ACTION_META: Record<AuditAction, string> = {
  created: "bg-success/15 text-success",
  updated: "bg-info/15 text-info",
  deleted: "bg-destructive/15 text-destructive",
  accessed: "bg-muted text-muted-foreground",
};

/* ------------------------------------------------------------------ */
/* Explorer                                                             */
/* ------------------------------------------------------------------ */

/**
 * Tamper-evident audit trail: actor, action chip, resource and device per
 * event; updated events expand into a field-level before→after diff; a
 * broken hash chain is impossible to miss.
 */
export function AuditLog({
  events = DEMO_AUDIT,
  onExport,
  className,
  ref,
  ...rest
}: AuditLogProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [actionFilter, setActionFilter] = React.useState<AuditAction | "all">("all");
  const [openId, setOpenId] = React.useState<string | null>(null);

  const visible = events.filter((e) => actionFilter === "all" || e.action === actionFilter);
  const tampered = events.some((e) => e.integrity === "tampered");

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-event]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.3, ease: "power2.out", stagger: 0.05, overwrite: true }
      );
    },
    { dependencies: [actionFilter, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="audit-log"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">Audit log</h3>
        <div className="flex items-center gap-2">
          {tampered ? (
            <Badge variant="destructive" pulse>
              Chain integrity broken
            </Badge>
          ) : (
            <Badge variant="success">Chain verified</Badge>
          )}
          <button
            type="button"
            onClick={() => onExport?.(visible)}
            className="rounded-md border border-border px-2 py-1 text-[11px] font-medium text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            Export {visible.length}
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="mt-2 flex flex-wrap gap-1.5">
        {(["all", "created", "updated", "deleted", "accessed"] as const).map((a) => (
          <button
            key={a}
            type="button"
            aria-pressed={actionFilter === a}
            onClick={() => setActionFilter(a)}
            className={cn(
              "rounded-full px-2.5 py-1 text-[11px] font-medium capitalize transition-colors duration-200",
              actionFilter === a
                ? "bg-primary text-primary-foreground"
                : "bg-muted text-muted-foreground hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            {a}
          </button>
        ))}
      </div>

      {/* Events */}
      <ul className="mt-3 flex flex-col gap-1.5">
        {visible.map((e) => {
          const open = openId === e.id;
          const expandable = (e.changes?.length ?? 0) > 0 || e.ip;
          return (
            <li key={e.id} data-event>
              <div
                className={cn(
                  "rounded-xl border transition-colors duration-300",
                  e.integrity === "tampered" ? "border-destructive/60 bg-destructive/5" : "border-border bg-background"
                )}
              >
                <button
                  type="button"
                  aria-expanded={open}
                  disabled={!expandable}
                  onClick={() => setOpenId((o) => (o === e.id ? null : e.id))}
                  className="flex w-full items-center gap-2.5 px-2.5 py-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                >
                  <span
                    className={cn(
                      "shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase",
                      ACTION_META[e.action]
                    )}
                  >
                    {e.action}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-xs font-medium text-foreground">
                      {e.resource}
                    </span>
                    <span className="block truncate text-[10px] text-muted-foreground">
                      {e.actor} · {e.timestamp}
                      {e.integrity === "tampered" ? (
                        <span className="ml-1 font-semibold text-destructive">
                          · hash mismatch with previous entry
                        </span>
                      ) : null}
                    </span>
                  </span>
                  {expandable ? (
                    <span
                      aria-hidden="true"
                      className={cn(
                        "text-muted-foreground transition-transform duration-300",
                        open && "rotate-180"
                      )}
                    >
                      ▾
                    </span>
                  ) : null}
                </button>
                {open ? <EventDetail event={e} reduced={reduced} /> : null}
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function EventDetail({ event, reduced }: { event: AuditEvent; reduced: boolean }) {
  const ref = React.useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { height: "auto", opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { height: 0, opacity: 0 },
        { height: "auto", opacity: 1, duration: 0.3, ease: "power3.out", clearProps: "height" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="overflow-hidden">
      <div className="border-t border-border px-2.5 py-2">
        {event.changes?.length ? (
          <dl className="flex flex-col gap-1">
            {event.changes.map((c) => (
              <div key={c.field} className="grid grid-cols-[auto_1fr] items-baseline gap-x-2 text-[11px]">
                <dt className="font-mono text-muted-foreground">{c.field}</dt>
                <dd className="flex flex-wrap items-baseline gap-1 font-mono tabular-nums">
                  <span className="rounded bg-destructive/10 px-1 text-destructive line-through decoration-destructive/50">
                    {c.before}
                  </span>
                  <span aria-hidden="true" className="text-muted-foreground">→</span>
                  <span className="rounded bg-success/10 px-1 text-success">{c.after}</span>
                </dd>
              </div>
            ))}
          </dl>
        ) : null}
        {event.ip ? (
          <p className="mt-1.5 text-[10px] text-muted-foreground">
            {event.ip} · {event.device}
          </p>
        ) : null}
      </div>
    </div>
  );
}

registry/default/enterprise/investigatio:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type EvidenceSource = "transactions" | "emails" | "access-logs";

export interface InvestigationEvent {
  id: string;
  time: string;
  title: string;
  actor: string;
  source: EvidenceSource;
  /** Analyst confidence in this event's interpretation, 0–1. */
  confidence: number;
  evidence: string[];
  note?: string;
  /** Days of unexplained silence before this event. */
  gapDaysBefore?: number;
}

export interface InvestigationTimelineProps
  extends React.HTMLAttributes<HTMLDivElement> {
  title?: string;
  events?: InvestigationEvent[];
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_INVESTIGATION: InvestigationEvent[] = [
  {
    id: "i1",
    time: "3 Jun · 09:14",
    title: "Vendor 'Meridian Supplies' created",
    actor: "r.kapoor",
    source: "access-logs",
    confidence: 0.95,
    evidence: ["Admin console session 8f2c", "Vendor record v-2291 creation log"],
  },
  {
    id: "i2",
    time: "3 Jun · 09:31",
    title: "Bank details set to a personal account",
    actor: "r.kapoor",
    source: "access-logs",
    confidence: 0.9,
    evidence: ["Field change: payee IFSC → HDFC0004xx", "Account holder ≠ vendor name"],
    note: "Same session as vendor creation — 17 minutes apart.",
  },
  {
    id: "i3",
    time: "11 Jun · 18:02",
    title: "First invoice approved under dual-control threshold",
    actor: "r.kapoor",
    source: "transactions",
    confidence: 0.85,
    evidence: ["INV-0093 · ₹49,500 (threshold ₹50,000)", "Approval chain skipped second signer"],
    gapDaysBefore: 8,
  },
  {
    id: "i4",
    time: "12 Jun · 08:47",
    title: "Email to accounts requesting expedited payment",
    actor: "r.kapoor",
    source: "emails",
    confidence: 0.65,
    evidence: ["Mail thread 'Meridian — urgent clearance'"],
    note: "Language matches two prior expedite requests; motive unclear.",
  },
  {
    id: "i5",
    time: "27 Jun · 14:20",
    title: "Three further invoices, all just under threshold",
    actor: "system",
    source: "transactions",
    confidence: 0.92,
    evidence: ["INV-0107 ₹49,900", "INV-0112 ₹48,750", "INV-0118 ₹49,500"],
    gapDaysBefore: 15,
  },
];

const SOURCE_META: Record<EvidenceSource, { label: string; cls: string }> = {
  "transactions": { label: "Transactions", cls: "bg-info/15 text-info" },
  "emails": { label: "Emails", cls: "bg-warning/15 text-warning" },
  "access-logs": { label: "Access logs", cls: "bg-success/15 text-success" },
};

/* ------------------------------------------------------------------ */
/* Timeline                                                             */
/* ------------------------------------------------------------------ */

/**
 * A case timeline for investigators: events carry actor, source,
 * confidence and expandable evidence; unexplained gaps are first-class
 * (a dashed void with the day count), and source filters re-cascade the
 * thread.
 */
export function InvestigationTimeline({
  title = "Case 2214 · vendor fraud",
  events = DEMO_INVESTIGATION,
  className,
  ref,
  ...rest
}: InvestigationTimelineProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [filter, setFilter] = React.useState<EvidenceSource | "all">("all");
  const [openId, setOpenId] = React.useState<string | null>(null);

  const visible = events.filter((e) => filter === "all" || e.source === filter);
  const actors = [...new Set(events.map((e) => e.actor))];

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-event]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 14, opacity: 0, filter: "blur(5px)" },
        {
          y: 0,
          opacity: 1,
          filter: "blur(0px)",
          duration: 0.4,
          ease: "power3.out",
          stagger: 0.07,
          overwrite: true,
          clearProps: "filter",
        }
      );
    },
    { dependencies: [filter, reduced], scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="investigation-timeline"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">{title}</h3>
        <span className="text-[11px] text-muted-foreground">
          {actors.length} actors · {events.length} events
        </span>
      </div>

      {/* Source filter */}
      <div className="mt-2 flex flex-wrap gap-1.5">
        {(["all", "transactions", "emails", "access-logs"] as const).map((s) => (
          <button
            key={s}
            type="button"
            aria-pressed={filter === s}
            onClick={() => setFilter(s)}
            className={cn(
              "rounded-full px-2.5 py-1 text-[11px] font-medium transition-colors duration-200",
              filter === s
                ? "bg-primary text-primary-foreground"
                : "bg-muted text-muted-foreground hover:text-foreground",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            )}
          >
            {s === "all" ? "All sources" : SOURCE_META[s].label}
          </button>
        ))}
      </div>

      {/* Events */}
      <ol className="mt-4 flex flex-col">
        {visible.map((e, i) => {
          const open = openId === e.id;
          const src = SOURCE_META[e.source];
          return (
            <li key={e.id} data-event className="relative flex gap-3 pb-1">
              {/* rail */}
              <div className="flex w-4 flex-col items-center">
                <span
                  className={cn(
                    "mt-1.5 size-2.5 shrink-0 rounded-full border-2 border-card",
                    e.confidence >= 0.85 ? "bg-primary" : "bg-warning"
                  )}
                />
                {i < visible.length - 1 ? (
                  <span className="w-px flex-1 bg-border" aria-hidden="true" />
                ) : null}
              </div>

              <div className="min-w-0 flex-1 pb-3">
                {/* gap marker */}
                {e.gapDaysBefore && filter === "all" ? (
                  <p className="mb-2 rounded-md border border-dashed border-border px-2 py-1 text-[10px] uppercase tracking-wide text-muted-foreground">
                    {e.gapDaysBefore} days with no recorded activity
                  </p>
                ) : null}

                <button
                  type="button"
                  aria-expanded={open}
                  onClick={() => setOpenId((o) => (o === e.id ? null : e.id))}
                  className="w-full rounded-lg text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  <p className="text-[10px] tabular-nums text-muted-foreground">{e.time}</p>
                  <p className="text-sm font-medium leading-5 text-foreground">{e.title}</p>
                  <p className="mt-0.5 flex flex-wrap items-center gap-1.5 text-[10px]">
                    <span className="rounded bg-muted px-1.5 py-0.5 font-mono text-foreground">
                      {e.actor}
                    </span>
                    <span className={cn("rounded px-1.5 py-0.5 font-medium", src.cls)}>
                      {src.label}
                    </span>
                    <span className="text-muted-foreground">
                      confidence {(e.confidence * 100).toFixed(0)}%
                    </span>
                    <span className="h-1 w-12 overflow-hidden rounded-full bg-muted" aria-hidden="true">
                      <span
                        className={cn(
                          "block h-full rounded-full",
                          e.confidence >= 0.85 ? "bg-primary" : "bg-warning"
                        )}
                        style={{ width: `${e.confidence * 100}%` }}
                      />
                    </span>
                  </p>
                </button>

                {open ? (
                  <EvidencePanel event={e} reduced={reduced} />
                ) : (
                  <p className="mt-0.5 text-[11px] text-muted-foreground">
                    {e.evidence.length} evidence item{e.evidence.length > 1 ? "s" : ""} — click to review
                  </p>
                )}
              </div>
            </li>
          );
        })}
      </ol>

      {visible.length === 0 ? (
        <p className="rounded-lg bg-muted/50 px-3 py-6 text-center text-xs text-muted-foreground">
          No events from this source.
        </p>
      ) : null}

      <p className="mt-1 border-t border-border pt-2 text-[10px] text-muted-foreground">
        Amber dots and bars mark lower-confidence interpretations. Gaps are
        shown, not hidden — absence of evidence is part of the case.
      </p>
    </div>
  );
}

function EvidencePanel({
  event,
  reduced,
}: {
  event: InvestigationEvent;
  reduced: boolean;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { height: "auto", opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { height: 0, opacity: 0 },
        { height: "auto", opacity: 1, duration: 0.3, ease: "power3.out", clearProps: "height" }
      );
    },
    { scope: ref }
  );
  return (
    <div ref={ref} className="overflow-hidden">
      <ul className="mt-1.5 flex flex-col gap-1 rounded-lg border border-border bg-background p-2.5">
        {event.evidence.map((ev) => (
          <li key={ev} className="flex items-start gap-1.5 text-[11px] text-foreground">
            <span aria-hidden="true" className="mt-1 size-1 shrink-0 rounded-full bg-muted-foreground" />
            {ev}
          </li>
        ))}
        {event.note ? (
          <li className="mt-1 border-t border-border pt-1.5 text-[11px] italic text-muted-foreground">
            Analyst note: {event.note}
          </li>
        ) : null}
      </ul>
    </div>
  );
}

registry/default/enterprise/entity-graph:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type EntityType = "person" | "org" | "account" | "transaction";

export interface GraphNode {
  id: string;
  label: string;
  type: EntityType;
  /** Position in the 600×340 viewBox. */
  x: number;
  y: number;
  detail?: string;
  risk?: boolean;
}

export interface GraphEdge {
  from: string;
  to: string;
  label: string;
  /** Risk links render dashed destructive. */
  risk?: boolean;
}

export interface EntityGraphProps
  extends React.HTMLAttributes<HTMLDivElement> {
  nodes?: GraphNode[];
  edges?: GraphEdge[];
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_GRAPH: { nodes: GraphNode[]; edges: GraphEdge[] } = {
  nodes: [
    { id: "rk", label: "R. Kapoor", type: "person", x: 300, y: 60, detail: "AP clerk · vendor-master access since Jan", risk: true },
    { id: "meridian", label: "Meridian Supplies", type: "org", x: 130, y: 150, detail: "Vendor v-2291 · created 3 Jun", risk: true },
    { id: "acct1", label: "HDFC ••4471", type: "account", x: 130, y: 265, detail: "Payee account · holder name mismatch", risk: true },
    { id: "spouse", label: "P. Kapoor", type: "person", x: 300, y: 300, detail: "Account holder of HDFC ••4471" },
    { id: "inv", label: "4 invoices · ₹1.98L", type: "transaction", x: 460, y: 150, detail: "All within ₹1,500 of the dual-control threshold", risk: true },
    { id: "acme", label: "Acme Corp", type: "org", x: 470, y: 60, detail: "Employer · AP system owner" },
    { id: "acct2", label: "Acme escrow", type: "account", x: 470, y: 265, detail: "Source of the four payments" },
  ],
  edges: [
    { from: "rk", to: "meridian", label: "created" },
    { from: "rk", to: "inv", label: "approved" },
    { from: "meridian", to: "acct1", label: "payee" },
    { from: "acct1", to: "spouse", label: "held by" },
    { from: "rk", to: "spouse", label: "married to", risk: true },
    { from: "acme", to: "rk", label: "employs" },
    { from: "acct2", to: "inv", label: "paid" },
    { from: "inv", to: "acct1", label: "credited", risk: true },
  ],
};

const TYPE_META: Record<EntityType, { fill: string; label: string }> = {
  person: { fill: "fill-info", label: "Person" },
  org: { fill: "fill-primary", label: "Organisation" },
  account: { fill: "fill-warning", label: "Account" },
  transaction: { fill: "fill-success", label: "Transactions" },
};

const W = 600;
const H = 340;
const R = 17;

/* ------------------------------------------------------------------ */
/* Graph                                                                */
/* ------------------------------------------------------------------ */

/**
 * An entity-relationship graph for investigations: typed nodes, labelled
 * edges (risk links dashed in destructive), edges draw themselves in, and
 * selecting a node isolates its neighbourhood while a panel explains it.
 */
export function EntityGraph({
  nodes = DEMO_GRAPH.nodes,
  edges = DEMO_GRAPH.edges,
  className,
  ref,
  ...rest
}: EntityGraphProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [selected, setSelected] = React.useState<string | null>(null);
  const byId = React.useMemo(
    () => Object.fromEntries(nodes.map((n) => [n.id, n])),
    [nodes]
  );
  const neighbours = React.useMemo(() => {
    if (!selected) return null;
    const set = new Set([selected]);
    for (const e of edges) {
      if (e.from === selected) set.add(e.to);
      if (e.to === selected) set.add(e.from);
    }
    return set;
  }, [selected, edges]);

  const sel = selected ? byId[selected] : null;

  /* Entrance: edges draw, nodes pop. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const lines = gsap.utils.toArray<SVGLineElement>(root.querySelectorAll("[data-edge]"));
      const dots = gsap.utils.toArray<SVGGElement>(root.querySelectorAll("[data-node]"));
      if (reduced) {
        gsap.set(lines, { strokeDashoffset: 0, opacity: 1 });
        gsap.set(dots, { scale: 1, opacity: 1 });
        return;
      }
      gsap.set(dots, { transformOrigin: "center center" });
      gsap.fromTo(
        dots,
        { scale: 0, opacity: 0 },
        { scale: 1, opacity: 1, duration: 0.45, ease: "back.out(1.8)", stagger: 0.07 }
      );
      for (const line of lines) {
        const len = Math.hypot(
          Number(line.getAttribute("x2")) - Number(line.getAttribute("x1")),
          Number(line.getAttribute("y2")) - Number(line.getAttribute("y1"))
        );
        gsap.fromTo(
          line,
          { strokeDasharray: len, strokeDashoffset: len, opacity: 0 },
          {
            strokeDashoffset: 0,
            opacity: 1,
            duration: 0.6,
            ease: "power2.inOut",
            delay: 0.35,
            onComplete: () => {
              // restore the designed dash pattern for risk edges
              if (line.dataset.risk === "true") line.style.strokeDasharray = "5 4";
              else line.style.strokeDasharray = "none";
            },
          }
        );
      }
    },
    { scope: rootRef }
  );

  const dimmed = (id: string) => (neighbours ? !neighbours.has(id) : false);

  return (
    <div
      ref={rootRef}
      data-slot="entity-graph"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      <div className="flex flex-wrap items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">Entity graph</h3>
        <div className="flex flex-wrap gap-2 text-[10px] text-muted-foreground">
          {(Object.keys(TYPE_META) as EntityType[]).map((t) => (
            <span key={t} className="flex items-center gap-1">
              <svg viewBox="0 0 8 8" className="size-2" aria-hidden="true">
                <circle cx="4" cy="4" r="4" className={TYPE_META[t].fill} />
              </svg>
              {TYPE_META[t].label}
            </span>
          ))}
        </div>
      </div>

      <svg
        viewBox={`0 0 ${W} ${H}`}
        role="img"
        aria-label={`Entity graph: ${nodes.length} entities, ${edges.length} relationships. Select a node to isolate its connections.`}
        className="mt-2 w-full"
      >
        {/* edges */}
        {edges.map((e) => {
          const a = byId[e.from];
          const b = byId[e.to];
          if (!a || !b) return null;
          const dim = neighbours
            ? !(neighbours.has(e.from) && neighbours.has(e.to)) ||
              (selected !== e.from && selected !== e.to)
            : false;
          const mx = (a.x + b.x) / 2;
          const my = (a.y + b.y) / 2;
          return (
            <g
              key={`${e.from}-${e.to}`}
              className="transition-opacity duration-300"
              style={{ opacity: dim ? 0.12 : 1 }}
            >
              <line
                data-edge
                data-risk={e.risk ? "true" : "false"}
                x1={a.x}
                y1={a.y}
                x2={b.x}
                y2={b.y}
                strokeWidth={e.risk ? 1.8 : 1.2}
                className={e.risk ? "stroke-destructive" : "stroke-border"}
              />
              <text
                x={mx}
                y={my - 4}
                textAnchor="middle"
                className={cn(
                  "text-[8.5px]",
                  e.risk ? "fill-destructive font-semibold" : "fill-muted-foreground"
                )}
              >
                {e.label}
              </text>
            </g>
          );
        })}

        {/* nodes */}
        {nodes.map((n) => (
          <g
            key={n.id}
            data-node
            role="button"
            tabIndex={0}
            aria-label={`${TYPE_META[n.type].label}: ${n.label}${n.risk ? ", flagged" : ""}`}
            aria-pressed={selected === n.id}
            onClick={() => setSelected((s) => (s === n.id ? null : n.id))}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                setSelected((s) => (s === n.id ? null : n.id));
              }
            }}
            className="cursor-pointer transition-opacity duration-300 focus-visible:outline-none"
            style={{ opacity: dimmed(n.id) ? 0.18 : 1 }}
          >
            {n.risk ? (
              <circle
                cx={n.x}
                cy={n.y}
                r={R + 4}
                className="fill-none stroke-destructive/50"
                strokeDasharray="3 3"
              />
            ) : null}
            <circle
              cx={n.x}
              cy={n.y}
              r={R}
              className={cn(
                TYPE_META[n.type].fill,
                selected === n.id ? "stroke-foreground" : "stroke-card"
              )}
              strokeWidth={selected === n.id ? 2.5 : 2}
              fillOpacity={0.9}
            />
            <text
              x={n.x}
              y={n.y + R + 12}
              textAnchor="middle"
              className="fill-foreground text-[10px] font-medium"
            >
              {n.label}
            </text>
          </g>
        ))}
      </svg>

      {/* Detail panel */}
      <div
        className={cn(
          "mt-1 rounded-xl border p-3 text-sm transition-colors duration-300",
          sel?.risk ? "border-destructive/40 bg-destructive/5" : "border-border bg-background"
        )}
        aria-live="polite"
      >
        {sel ? (
          <>
            <div className="flex items-center justify-between gap-2">
              <p className="font-medium text-foreground">
                {sel.label}
                <span className="ml-2 text-[11px] font-normal text-muted-foreground">
                  {TYPE_META[sel.type].label}
                </span>
              </p>
              <button
                type="button"
                onClick={() => setSelected(null)}
                className="text-[11px] text-muted-foreground underline-offset-2 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                Show all
              </button>
            </div>
            {sel.detail ? (
              <p className="mt-0.5 text-[12px] leading-5 text-muted-foreground">{sel.detail}</p>
            ) : null}
            <p className="mt-1 text-[11px] text-muted-foreground">
              {edges
                .filter((e) => e.from === sel.id || e.to === sel.id)
                .map((e) =>
                  e.from === sel.id
                    ? `${e.label} → ${byId[e.to]?.label}`
                    : `${byId[e.from]?.label} → ${e.label}`
                )
                .join(" · ")}
            </p>
          </>
        ) : (
          <p className="text-[12px] text-muted-foreground">
            Select an entity to isolate its neighbourhood. Dashed red rings and
            edges mark risk links.
          </p>
        )}
      </div>
    </div>
  );
}

registry/default/fintech/fund-compare.ts:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface FundProfile {
  name: string;
  category: string;
  returns3y: number;
  returns5y: number;
  /** Share of 3y rolling windows beating the benchmark, %. */
  rollingBeat: number;
  expenseRatio: number;
  exitLoad: string;
  maxDrawdown: number;
  sharpe: number;
  managerTenureYears: number;
  /** Top-10 holdings share, %. */
  top10Weight: number;
}

export interface FundCompareProps
  extends React.HTMLAttributes<HTMLDivElement> {
  funds?: [FundProfile, FundProfile];
  /** Portfolio overlap between the two funds, %. */
  overlapPct?: number;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_FUNDS: [FundProfile, FundProfile] = [
  {
    name: "Nifty Alpha Flexicap",
    category: "Flexi cap · direct growth",
    returns3y: 18.4,
    returns5y: 15.2,
    rollingBeat: 74,
    expenseRatio: 0.62,
    exitLoad: "1% < 1y",
    maxDrawdown: -21.3,
    sharpe: 1.12,
    managerTenureYears: 6.5,
    top10Weight: 38,
  },
  {
    name: "Bluechip Advantage",
    category: "Large cap · direct growth",
    returns3y: 14.1,
    returns5y: 13.8,
    rollingBeat: 58,
    expenseRatio: 0.95,
    exitLoad: "Nil",
    maxDrawdown: -16.8,
    sharpe: 0.94,
    managerTenureYears: 2.1,
    top10Weight: 52,
  },
];

interface MetricRow {
  key: string;
  label: string;
  hint: string;
  value: (f: FundProfile) => number;
  format: (v: number) => string;
  /** true if higher is better. */
  higherBetter: boolean;
  /** Normalizer for the bar, returns 0–1. */
  norm: (v: number) => number;
}

const METRICS: MetricRow[] = [
  { key: "r3", label: "3y returns", hint: "annualised", value: (f) => f.returns3y, format: (v) => `${v.toFixed(1)}%`, higherBetter: true, norm: (v) => v / 25 },
  { key: "r5", label: "5y returns", hint: "annualised", value: (f) => f.returns5y, format: (v) => `${v.toFixed(1)}%`, higherBetter: true, norm: (v) => v / 25 },
  { key: "roll", label: "Rolling consistency", hint: "3y windows beating benchmark", value: (f) => f.rollingBeat, format: (v) => `${v.toFixed(0)}%`, higherBetter: true, norm: (v) => v / 100 },
  { key: "er", label: "Expense ratio", hint: "lower is better", value: (f) => f.expenseRatio, format: (v) => `${v.toFixed(2)}%`, higherBetter: false, norm: (v) => v / 1.5 },
  { key: "dd", label: "Max drawdown", hint: "worst peak-to-trough", value: (f) => Math.abs(f.maxDrawdown), format: (v) => `−${v.toFixed(1)}%`, higherBetter: false, norm: (v) => v / 30 },
  { key: "sharpe", label: "Sharpe", hint: "risk-adjusted return", value: (f) => f.sharpe, format: (v) => v.toFixed(2), higherBetter: true, norm: (v) => v / 1.5 },
  { key: "tenure", label: "Manager tenure", hint: "current manager", value: (f) => f.managerTenureYears, format: (v) => `${v.toFixed(1)}y`, higherBetter: true, norm: (v) => v / 10 },
  { key: "conc", label: "Top-10 weight", hint: "concentration, lower is better", value: (f) => f.top10Weight, format: (v) => `${v.toFixed(0)}%`, higherBetter: false, norm: (v) => v / 60 },
];

/* ------------------------------------------------------------------ */
/* Compare                                                              */
/* ------------------------------------------------------------------ */

/**
 * Two funds, honestly compared: mirrored metric bars grow from the
 * centre, the better side is marked per metric, and portfolio overlap
 * tells you whether holding both diversifies anything at all.
 */
export function FundCompare({
  funds = DEMO_FUNDS,
  overlapPct = 41,
  className,
  ref,
  ...rest
}: FundCompareProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);
  const [a, b] = funds;

  const winsA = METRICS.filter((m) => {
    const va = m.value(a);
    const vb = m.value(b);
    return m.higherBetter ? va > vb : va < vb;
  }).length;

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-bar]"));
      if (reduced) {
        for (const bar of bars) gsap.set(bar, { width: `${Number(bar.dataset.bar) * 100}%` });
        return;
      }
      for (const bar of bars) {
        gsap.fromTo(
          bar,
          { width: 0 },
          {
            width: `${Math.min(1, Number(bar.dataset.bar)) * 100}%`,
            duration: 0.6,
            ease: "power3.out",
            stagger: 0.05,
          }
        );
      }
    },
    { scope: rootRef }
  );

  const winDot = (mine: number, theirs: number, higherBetter: boolean) => {
    const win = higherBetter ? mine > theirs : mine < theirs;
    return win ? (
      <span aria-label="better" className="text-success">●</span>
    ) : null;
  };

  return (
    <div
      ref={rootRef}
      data-slot="fund-compare"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border/70 bg-card p-4 shadow-sm",
        className
      )}
      {...rest}
    >
      {/* Fund headers */}
      <div className="grid grid-cols-[1fr_auto_1fr] items-start gap-2">
        <div>
          <span className="mb-1 inline-flex items-center gap-1.5 rounded-full bg-primary/10 px-1.5 py-0.5 text-[9px] font-medium text-foreground">
            <span className="size-1.5 rounded-full bg-primary" />A
          </span>
          <p className="text-sm font-semibold leading-5 text-foreground">{a.name}</p>
          <p className="text-[10px] text-muted-foreground">{a.category}</p>
        </div>
        <span className="pt-1 text-[10px] font-medium uppercase text-muted-foreground">vs</span>
        <div className="text-right">
          <span className="mb-1 inline-flex items-center gap-1.5 rounded-full bg-info/10 px-1.5 py-0.5 text-[9px] font-medium text-foreground">
            B<span className="size-1.5 rounded-full bg-info" />
          </span>
          <p className="text-sm font-semibold leading-5 text-foreground">{b.name}</p>
          <p className="text-[10px] text-muted-foreground">{b.category}</p>
        </div>
      </div>

      {/* Metric rows: mirrored bars from the centre */}
      <div className="mt-4 flex flex-col gap-2.5">
        {METRICS.map((m) => {
          const va = m.value(a);
          const vb = m.value(b);
          return (
            <div key={m.key}>
              <div className="grid grid-cols-[1fr_auto_1fr] items-baseline gap-2 text-xs tabular-nums">
                <span className="flex items-center gap-1.5 font-medium text-foreground">
                  {winDot(va, vb, m.higherBetter)}
                  {m.format(m.key === "dd" ? va : va)}
                </span>
                <span className="text-center text-[10px] text-muted-foreground">
                  {m.label}
                  <span className="hidden sm:inline"> · {m.hint}</span>
                </span>
                <span className="flex items-center justify-end gap-1.5 font-medium text-foreground">
                  {m.format(vb)}
                  {winDot(vb, va, m.higherBetter)}
                </span>
              </div>
              <div className="mt-1 grid grid-cols-2 gap-1" aria-hidden="true">
                <div className="flex justify-end overflow-hidden rounded-l-full bg-muted/70 ring-1 ring-inset ring-border/40">
                  <span
                    data-bar={Math.min(1, m.norm(va))}
                    className="block h-1.5 rounded-l-full"
                    style={{
                      width: 0,
                      background: "linear-gradient(270deg, var(--primary), color-mix(in oklab, var(--primary) 45%, transparent))",
                    }}
                  />
                </div>
                <div className="flex overflow-hidden rounded-r-full bg-muted/70 ring-1 ring-inset ring-border/40">
                  <span
                    data-bar={Math.min(1, m.norm(vb))}
                    className="block h-1.5 rounded-r-full"
                    style={{
                      width: 0,
                      background: "linear-gradient(90deg, var(--info), color-mix(in oklab, var(--info) 45%, transparent))",
                    }}
                  />
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Exit load + overlap */}
      <div className="mt-4 grid gap-2 sm:grid-cols-2">
        <div className="rounded-xl border border-border/70 bg-background px-3 py-2 text-xs shadow-xs">
          <p className="text-[10px] uppercase tracking-wide text-muted-foreground">Exit load</p>
          <p className="mt-0.5 tabular-nums text-foreground">
            {a.exitLoad} <span className="text-muted-foreground">vs</span> {b.exitLoad}
          </p>
        </div>
        <div className="rounded-xl border border-border/70 bg-background px-3 py-2 text-xs shadow-xs">
          <p className="text-[10px] uppercase tracking-wide text-muted-foreground">
            Portfolio overlap
          </p>
          <div className="mt-1.5 flex items-center gap-2">
            <span
              className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted"
              role="meter"
              aria-label="Portfolio overlap"
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={overlapPct}
            >
              <span
                data-bar={overlapPct / 100}
                className="block h-full rounded-full"
                style={{
                  width: 0,
                  background:
                    overlapPct > 50
                      ? "linear-gradient(90deg, color-mix(in oklab, var(--warning) 50%, transparent), var(--warning))"
                      : "linear-gradient(90deg, color-mix(in oklab, var(--primary) 50%, transparent), var(--primary))",
                }}
              />
            </span>
            <span className="font-medium tabular-nums text-foreground">{overlapPct}%</span>
          </div>
          {overlapPct > 50 ? (
            <p className="mt-1 text-[10px] leading-4 text-warning">
              High overlap — holding both adds little diversification.
            </p>
          ) : null}
        </div>
      </div>

      <p className="mt-3 text-[11px] text-muted-foreground">
        <span className="font-medium text-foreground">{winsA >= METRICS.length / 2 ? a.name : b.name}</span>{" "}
        leads on {Math.max(winsA, METRICS.length - winsA)} of {METRICS.length} metrics ·
        past returns don&apos;t guarantee future ones · not advice
      </p>
    </div>
  );
}

registry/default/fintech/loan-eligibilit:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { NumberFlow } from "@/registry/default/fintech/number-flow";

/* ------------------------------------------------------------------ */
/* Model + math                                                         */
/* ------------------------------------------------------------------ */

export interface LoanEligibilityProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** Annual interest rate by credit band, %. */
  rates?: { excellent: number; good: number; fair: number };
  /** Processing fee, % of principal. */
  processingFeePct?: number;
  /** FOIR ceiling used for the approval read. Default 0.5. */
  foirLimit?: number;
  ref?: React.Ref<HTMLDivElement>;
}

export type CreditBand = "excellent" | "good" | "fair";

/** Standard amortised EMI. */
export function emi(principal: number, annualRatePct: number, months: number) {
  const r = annualRatePct / 12 / 100;
  if (r === 0) return principal / months;
  const f = Math.pow(1 + r, months);
  return (principal * r * f) / (f - 1);
}

const inr = (n: number) =>
  new Intl.NumberFormat("en-IN", { maximumFractionDigits: 0 }).format(n);
const lakh = (n: number) =>
  n >= 1e5 ? `₹${(n / 1e5).toFixed(1)}L` : `₹${inr(n)}`;

const BANDS: { key: CreditBand; label: string; range: string }[] = [
  { key: "excellent", label: "750+", range: "Excellent" },
  { key: "good", label: "700–749", range: "Good" },
  { key: "fair", label: "650–699", range: "Fair" },
];

const DOCUMENTS = [
  "PAN + Aadhaar",
  "3 months' salary slips",
  "6 months' bank statement",
  "Employment certificate",
];

/* ------------------------------------------------------------------ */
/* Composer                                                             */
/* ------------------------------------------------------------------ */

/**
 * Loan eligibility composer: amount/tenure/income/obligations sliders
 * drive the EMI, the FOIR meter shows exactly why the answer is what it
 * is, and the approval read moves between likely/borderline/unlikely
 * with the reason spelled out.
 */
export function LoanEligibility({
  rates = { excellent: 10.5, good: 12.25, fair: 14.5 },
  processingFeePct = 1.5,
  foirLimit = 0.5,
  className,
  ref,
  ...rest
}: LoanEligibilityProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [amount, setAmount] = React.useState(800_000);
  const [months, setMonths] = React.useState(48);
  const [income, setIncome] = React.useState(95_000);
  const [obligations, setObligations] = React.useState(12_000);
  const [band, setBand] = React.useState<CreditBand>("good");

  const rate = rates[band];
  const monthly = emi(amount, rate, months);
  const totalInterest = monthly * months - amount;
  const processingFee = (amount * processingFeePct) / 100;
  const foir = (monthly + obligations) / income;

  const verdict =
    foir <= foirLimit * 0.8
      ? { label: "Approval likely", cls: "text-success", bar: "bg-success" }
      : foir <= foirLimit
        ? { label: "Borderline", cls: "text-warning", bar: "bg-warning" }
        : { label: "Unlikely at this size", cls: "text-risk-high", bar: "bg-risk-high" };

  // Max amount that keeps FOIR at the limit, for the suggestion line.
  const headroom = Math.max(0, income * foirLimit - obligations);
  const perRupee = emi(100_000, rate, months) / 100_000;
  const maxEligible = Math.floor(headroom / perRupee / 10_000) * 10_000;

  /* FOIR meter tweens to each new position. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const fill = root.querySelector<HTMLElement>("[data-foir]");
      if (!fill) return;
      const pct = Math.min(100, foir * 100);
      if (reduced) gsap.set(fill, { width: `${pct}%` });
      else gsap.to(fill, { width: `${pct}%`, duration: 0.5, ease: "power3.out", overwrite: true });
    },
    { dependencies: [foir, reduced], scope: rootRef }
  );

  const slider = (
    label: string,
    value: number,
    set: (v: number) => void,
    min: number,
    max: number,
    step: number,
    fmt: (v: number) => string
  ) => (
    <label className="flex flex-col gap-1 text-xs">
      <span className="flex justify-between text-muted-foreground">
        {label}
        <span className="font-medium tabular-nums text-foreground">{fmt(value)}</span>
      </span>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        aria-label={label}
        onChange={(e) => set(parseInt(e.target.value, 10))}
        className="accent-primary"
      />
    </label>
  );

  return (
    <div
      ref={rootRef}
      data-slot="loan-eligibility"
      className={cn(
        "w-full max-w-md rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Headline EMI */}
      <div className="flex items-baseline justify-between gap-2">
        <div>
          <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
            Monthly EMI
          </p>
          <p className="text-2xl font-semibold tracking-tight text-foreground">
            <NumberFlow value={Math.round(monthly)} prefix="₹" locale="en-IN" trend />
          </p>
        </div>
        <p className={cn("text-sm font-semibold", verdict.cls)} aria-live="polite">
          {verdict.label}
        </p>
      </div>

      {/* FOIR meter */}
      <div className="mt-2">
        <div
          className="relative h-2 overflow-hidden rounded-full bg-muted"
          role="meter"
          aria-label="Fixed-obligation to income ratio"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(foir * 100)}
        >
          <span
            data-foir
            className={cn("block h-full rounded-full", verdict.bar)}
            style={{ width: 0 }}
          />
          <span
            aria-hidden="true"
            className="absolute inset-y-0 w-0.5 bg-foreground/60"
            style={{ left: `${foirLimit * 100}%` }}
          />
        </div>
        <p className="mt-1 text-[11px] tabular-nums text-muted-foreground">
          Obligations {(foir * 100).toFixed(0)}% of income · lenders cap near{" "}
          {(foirLimit * 100).toFixed(0)}%
          {foir > foirLimit && maxEligible > 0 ? (
            <span className="font-medium text-foreground">
              {" "}
              — {lakh(maxEligible)} would fit at this tenure
            </span>
          ) : null}
        </p>
      </div>

      {/* Controls */}
      <div className="mt-4 flex flex-col gap-3">
        {slider("Loan amount", amount, setAmount, 100_000, 3_000_000, 50_000, lakh)}
        {slider("Tenure", months, setMonths, 12, 84, 6, (v) => `${v} months`)}
        {slider("Monthly income", income, setIncome, 25_000, 400_000, 5_000, (v) => `₹${inr(v)}`)}
        {slider("Existing EMIs", obligations, setObligations, 0, 100_000, 1_000, (v) => `₹${inr(v)}`)}
        <div className="flex items-center justify-between gap-2 text-xs">
          <span className="text-muted-foreground">Credit score</span>
          <div className="flex gap-1" role="tablist" aria-label="Credit band">
            {BANDS.map((b) => (
              <button
                key={b.key}
                role="tab"
                aria-selected={band === b.key}
                onClick={() => setBand(b.key)}
                className={cn(
                  "rounded-md px-2 py-1 text-[11px] font-medium tabular-nums transition-colors duration-200",
                  band === b.key
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground hover:text-foreground",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
                title={b.range}
              >
                {b.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Cost breakdown */}
      <dl className="mt-4 flex flex-col gap-1 rounded-xl border border-border bg-background p-3 text-xs tabular-nums">
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Interest rate ({BANDS.find((b) => b.key === band)?.range})</dt>
          <dd className="text-foreground">{rate.toFixed(2)}% p.a.</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Total interest over {months}m</dt>
          <dd className="text-foreground">₹{inr(Math.round(totalInterest))}</dd>
        </div>
        <div className="flex justify-between">
          <dt className="text-muted-foreground">Processing fee ({processingFeePct}%)</dt>
          <dd className="text-foreground">₹{inr(Math.round(processingFee))}</dd>
        </div>
      </dl>

      {/* Documents */}
      <div className="mt-3">
        <p className="text-[11px] font-medium text-foreground">You&apos;ll need</p>
        <ul className="mt-1 flex flex-wrap gap-1.5">
          {DOCUMENTS.map((d) => (
            <li
              key={d}
              className="rounded-full bg-muted px-2 py-0.5 text-[10px] text-muted-foreground"
            >
              {d}
            </li>
          ))}
        </ul>
      </div>
      <p className="mt-2 text-[10px] text-muted-foreground">
        Indicative only — the lender&apos;s own bureau pull and policy decide.
      </p>
    </div>
  );
}

"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type ToolCallStatus = "ok" | "error" | "denied";

export interface InspectedToolCall {
  id: string;
  tool: string;
  /** Human summary of what the call did. */
  summary: string;
  args: Record<string, unknown>;
  result?: unknown;
  error?: string;
  durationMs: number;
  status: ToolCallStatus;
  permission: "allowed" | "asked" | "denied";
  retryOf?: string;
}

export interface ToolCallInspectorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  calls?: InspectedToolCall[];
  onRetry?: (id: string) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_TOOL_CALLS: InspectedToolCall[] = [
  {
    id: "c1",
    tool: "search_orders",
    summary: "Found order #8412 for asha@example.com",
    args: { email: "asha@example.com", status: "paid" },
    result: { id: 8412, total: 2499, currency: "INR" },
    durationMs: 312,
    status: "ok",
    permission: "allowed",
  },
  {
    id: "c2",
    tool: "payments.refund",
    summary: "First refund attempt hit a gateway timeout",
    args: { txn: "txn_9f2c", amount: 2499, reason: "customer_request" },
    error: "504 gateway timeout after 8000ms",
    durationMs: 8000,
    status: "error",
    permission: "asked",
  },
  {
    id: "c3",
    tool: "payments.refund",
    summary: "Retry succeeded — refund refund_51ab initiated",
    args: { txn: "txn_9f2c", amount: 2499, reason: "customer_request" },
    result: { refund: "refund_51ab", state: "initiated" },
    durationMs: 1240,
    status: "ok",
    permission: "asked",
    retryOf: "c2",
  },
  {
    id: "c4",
    tool: "db.delete_customer",
    summary: "Blocked: destructive call outside the approved scope",
    args: { id: 8412 },
    durationMs: 4,
    status: "denied",
    permission: "denied",
  },
];

const STATUS_META: Record<ToolCallStatus, { cls: string; label: string }> = {
  ok: { cls: "bg-success/15 text-success", label: "ok" },
  error: { cls: "bg-destructive/15 text-destructive", label: "error" },
  denied: { cls: "bg-warning/15 text-warning", label: "denied" },
};

/* ------------------------------------------------------------------ */
/* Inspector                                                            */
/* ------------------------------------------------------------------ */

/**
 * A transcript of what the agent actually did: every tool call with its
 * permission, duration bar, and a human ↔ raw toggle — the raw view is
 * the exact JSON, the human view is what you'd tell a teammate.
 */
export function ToolCallInspector({
  calls = DEMO_TOOL_CALLS,
  onRetry,
  className,
  ref,
  ...rest
}: ToolCallInspectorProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [raw, setRaw] = React.useState(false);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const maxMs = Math.max(...calls.map((c) => c.durationMs), 1);

  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-call]"));
      const bars = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-duration]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        for (const bar of bars) gsap.set(bar, { width: `${Number(bar.dataset.duration) * 100}%` });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.35, ease: "power2.out", stagger: 0.07 }
      );
      for (const bar of bars) {
        gsap.fromTo(
          bar,
          { width: 0 },
          { width: `${Number(bar.dataset.duration) * 100}%`, duration: 0.6, ease: "power3.out", delay: 0.3 }
        );
      }
    },
    { scope: rootRef }
  );

  return (
    <div
      ref={rootRef}
      data-slot="tool-call-inspector"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-sm font-semibold text-foreground">
          Tool calls <span className="text-muted-foreground">({calls.length})</span>
        </h3>
        <div className="flex rounded-lg bg-muted p-0.5" role="tablist" aria-label="View mode">
          {(["human", "raw"] as const).map((v) => (
            <button
              key={v}
              role="tab"
              aria-selected={(v === "raw") === raw}
              onClick={() => setRaw(v === "raw")}
              className={cn(
                "rounded-md px-2.5 py-1 text-[11px] font-medium capitalize transition-colors duration-200",
                (v === "raw") === raw
                  ? "bg-background text-foreground shadow-sm"
                  : "text-muted-foreground hover:text-foreground",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              )}
            >
              {v}
            </button>
          ))}
        </div>
      </div>

      {/* Calls */}
      <ul className="mt-3 flex flex-col gap-1.5">
        {calls.map((c) => {
          const meta = STATUS_META[c.status];
          const open = openId === c.id;
          return (
            <li key={c.id} data-call>
              <div
                className={cn(
                  "rounded-xl border bg-background",
                  c.status === "error"
                    ? "border-destructive/40"
                    : c.status === "denied"
                      ? "border-warning/40"
                      : "border-border"
                )}
              >
                <button
                  type="button"
                  aria-expanded={open}
                  onClick={() => setOpenId((o) => (o === c.id ? null : c.id))}
                  className="w-full px-3 py-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                >
                  <div className="flex items-center gap-2">
                    <code className="truncate font-mono text-xs font-semibold text-foreground">
                      {c.tool}
                    </code>
                    <span className={cn("rounded px-1.5 py-0.5 text-[9px] font-semibold uppercase", meta.cls)}>
                      {meta.label}
                    </span>
                    {c.permission === "asked" ? (
                      <span className="rounded bg-info/15 px-1.5 py-0.5 text-[9px] font-semibold uppercase text-info">
                        user approved
                      </span>
                    ) : null}
                    {c.retryOf ? (
                      <span className="rounded bg-muted px-1.5 py-0.5 text-[9px] font-semibold uppercase text-muted-foreground">
                        retry
                      </span>
                    ) : null}
                    <span className="ml-auto shrink-0 font-mono text-[10px] tabular-nums text-muted-foreground">
                      {c.durationMs >= 1000 ? `${(c.durationMs / 1000).toFixed(1)}s` : `${c.durationMs}ms`}
                    </span>
                  </div>
                  {/* duration bar */}
                  <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-muted" aria-hidden="true">
                    <span
                      data-duration={c.durationMs / maxMs}
                      className={cn(
                        "block h-full rounded-full",
                        c.status === "error" ? "bg-destructive" : c.status === "denied" ? "bg-warning" : "bg-primary"
                      )}
                      style={{ width: 0 }}
                    />
                  </div>
                  <p className="mt-1.5 text-[11px] leading-4 text-muted-foreground">
                    {raw ? (
                      <code className="font-mono">{JSON.stringify(c.args)}</code>
                    ) : (
                      c.summary
                    )}
                  </p>
                </button>

                {open ? <CallDetail call={c} raw={raw} reduced={reduced} onRetry={onRetry} /> : null}
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function CallDetail({
  call,
  raw,
  reduced,
  onRetry,
}: {
  call: InspectedToolCall;
  raw: boolean;
  reduced: boolean;
  onRetry?: (id: string) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  useGSAP(
    () => {
      if (!ref.current) return;
      if (reduced) {
        gsap.set(ref.current, { height: "auto", opacity: 1 });
        return;
      }
      gsap.fromTo(
        ref.current,
        { height: 0, opacity: 0 },
        { height: "auto", opacity: 1, duration: 0.3, ease: "power3.out", clearProps: "height" }
      );
    },
    { scope: ref }
  );

  return (
    <div ref={ref} className="overflow-hidden">
      <div className="border-t border-border px-3 py-2">
        {raw ? (
          <pre className="overflow-x-auto rounded-lg bg-muted/60 p-2 font-mono text-[10px] leading-4 text-foreground">
            {JSON.stringify(
              { tool: call.tool, args: call.args, ...(call.result ? { result: call.result } : {}), ...(call.error ? { error: call.error } : {}) },
              null,
              2
            )}
          </pre>
        ) : (
          <div className="flex flex-col gap-1 text-[11px] leading-4">
            {call.result != null ? (
              <p className="text-foreground">
                <span className="font-medium">Result:</span>{" "}
                {typeof call.result === "object" ? JSON.stringify(call.result) : String(call.result)}
              </p>
            ) : null}
            {call.error ? (
              <p className="text-destructive">
                <span className="font-medium">Error:</span> {call.error}
              </p>
            ) : null}
            {call.status === "denied" ? (
              <p className="text-warning">
                Denied by policy before execution — no side effects occurred.
              </p>
            ) : null}
          </div>
        )}
        {call.status === "error" ? (
          <div className="mt-2">
            <Button size="sm" variant="outline" onClick={() => onRetry?.(call.id)}>
              Retry call
            </Button>
          </div>
        ) : null}
      </div>
    </div>
  );
}

registry/default/ai/approval-gate.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export type ApprovalState =
  | "pending"
  | "approved"
  | "modified"
  | "rejected"
  | "expired";

export interface ApprovalGateProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** What the agent wants to do, imperative. */
  action: string;
  /** The risky payload the human is approving — editable via Modify. */
  payload: string;
  details?: [string, string][];
  /** Seconds until the request expires. Default 60. */
  expiresInSec?: number;
  onDecision?: (state: ApprovalState, payload: string) => void;
  ref?: React.Ref<HTMLDivElement>;
}

const STATE_META: Record<
  ApprovalState,
  { label: string; cls: string; border: string }
> = {
  pending: { label: "Awaiting approval", cls: "text-agent-waiting", border: "border-agent-waiting/50" },
  approved: { label: "Approved", cls: "text-success", border: "border-success/50" },
  modified: { label: "Approved with edits", cls: "text-success", border: "border-success/50" },
  rejected: { label: "Rejected", cls: "text-muted-foreground", border: "border-border" },
  expired: { label: "Expired — agent paused", cls: "text-destructive", border: "border-destructive/50" },
};

/* ------------------------------------------------------------------ */
/* Gate                                                                 */
/* ------------------------------------------------------------------ */

/**
 * The human approval gate: an agent's outward-facing action paused for a
 * person. The expiry bar drains in real time; Approve, Reject, or Modify
 * the payload and approve the edited version — every terminal state is
 * designed, including "nobody answered".
 */
export function ApprovalGate({
  action,
  payload,
  details = [],
  expiresInSec = 60,
  onDecision,
  className,
  ref,
  ...rest
}: ApprovalGateProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const barRef = React.useRef<HTMLSpanElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [state, setState] = React.useState<ApprovalState>("pending");
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(payload);
  const [remaining, setRemaining] = React.useState(expiresInSec);

  const decide = (next: ApprovalState) => {
    setState(next);
    setEditing(false);
    onDecision?.(next, draft);
  };

  /* Countdown: the bar drains linearly; hitting zero expires the gate. */
  React.useEffect(() => {
    if (state !== "pending") return;
    const id = setInterval(() => {
      setRemaining((r) => {
        if (r <= 1) {
          clearInterval(id);
          setState("expired");
          onDecision?.("expired", draft);
          return 0;
        }
        return r - 1;
      });
    }, 1000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state]);

  useGSAP(
    () => {
      if (!barRef.current) return;
      const pct = (remaining / expiresInSec) * 100;
      if (reduced) gsap.set(barRef.current, { width: `${pct}%` });
      else gsap.to(barRef.current, { width: `${pct}%`, duration: 1, ease: "none", overwrite: true });
    },
    { dependencies: [remaining, expiresInSec, reduced] }
  );

  const meta = STATE_META[state];
  const settled = state !== "pending";

  return (
    <div
      ref={rootRef}
      data-slot="approval-gate"
      className={cn(
        "w-full max-w-md rounded-2xl border bg-card p-4 transition-colors duration-300",
        meta.border,
        className
      )}
      {...rest}
    >
      {/* Header */}
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
            Agent requests approval
          </p>
          <p className="text-sm font-semibold leading-5 text-foreground">{action}</p>
        </div>
        <span className={cn("flex shrink-0 items-center gap-1.5 text-xs font-semibold", meta.cls)} aria-live="polite">
          {state === "pending" ? (
            <span className="relative flex size-2">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-agent-waiting opacity-60" />
              <span className="relative inline-flex size-2 rounded-full bg-agent-waiting" />
            </span>
          ) : null}
          {meta.label}
        </span>
      </div>

      {/* Payload */}
      <div className="mt-3">
        {editing ? (
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            rows={4}
            aria-label="Edit the payload before approving"
            className="w-full rounded-lg border border-input bg-background p-2.5 text-[12px] leading-5 text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          />
        ) : (
          <blockquote
            className={cn(
              "rounded-lg border-l-2 bg-muted/50 px-3 py-2 text-[12px] leading-5",
              draft !== payload ? "border-info text-foreground" : "border-border text-foreground",
              state === "rejected" && "opacity-50"
            )}
          >
            {draft}
            {draft !== payload ? (
              <span className="mt-1 block text-[10px] font-medium text-info">
                edited by reviewer
              </span>
            ) : null}
          </blockquote>
        )}
      </div>

      {/* Details */}
      {details.length > 0 ? (
        <dl className="mt-2 flex flex-col gap-0.5 text-[11px] tabular-nums">
          {details.map(([k, v]) => (
            <div key={k} className="flex justify-between gap-2">
              <dt className="text-muted-foreground">{k}</dt>
              <dd className="text-right text-foreground">{v}</dd>
            </div>
          ))}
        </dl>
      ) : null}

      {/* Expiry / outcome */}
      {state === "pending" ? (
        <>
          <div className="mt-3 h-1 overflow-hidden rounded-full bg-muted" aria-hidden="true">
            <span
              ref={barRef}
              className={cn(
                "block h-full rounded-full",
                remaining / expiresInSec > 0.33 ? "bg-agent-waiting" : "bg-destructive"
              )}
              style={{ width: "100%" }}
            />
          </div>
          <p className="mt-1 text-[10px] tabular-nums text-muted-foreground">
            Expires in {remaining}s — the agent stays paused, nothing is sent
            without a decision.
          </p>
          <div className="mt-3 flex gap-2">
            {editing ? (
              <>
                <Button size="sm" variant="outline" onClick={() => { setDraft(payload); setEditing(false); }}>
                  Discard edits
                </Button>
                <Button size="sm" className="flex-1" onClick={() => decide("modified")}>
                  Approve edited version
                </Button>
              </>
            ) : (
              <>
                <Button size="sm" variant="outline" onClick={() => decide("rejected")}>
                  Reject
                </Button>
                <Button size="sm" variant="outline" onClick={() => setEditing(true)}>
                  Modify
                </Button>
                <Button size="sm" className="flex-1" onClick={() => decide("approved")}>
                  Approve
                </Button>
              </>
            )}
          </div>
        </>
      ) : (
        <p className="mt-3 rounded-lg bg-muted/50 px-2.5 py-1.5 text-[11px] leading-4 text-muted-foreground">
          {state === "approved" && "The agent is executing the approved action."}
          {state === "modified" && "The agent is executing your edited version — the original was not sent."}
          {state === "rejected" && "Nothing was sent. The agent will report the rejection and stop this branch."}
          {state === "expired" && "No decision arrived in time. The action was not taken; the agent is waiting for a human to resume."}
        </p>
      )}
    </div>
  );
}

registry/default/ai/grounded-answer.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";

/* ------------------------------------------------------------------ */
/* Model                                                                */
/* ------------------------------------------------------------------ */

export interface AnswerSource {
  id: string;
  title: string;
  quote: string;
  meta: string;
}

export interface AnswerClaim {
  text: string;
  sourceIds: string[];
  /** Grounding confidence 0–1; low values render with a caution tint. */
  confidence: number;
  /** Set when sources disagree — surfaced, never averaged away. */
  contradiction?: string;
}

export interface GroundedAnswerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  question: string;
  claims?: AnswerClaim[];
  sources?: AnswerSource[];
  missingEvidence?: string[];
  onFeedback?: (helpful: boolean) => void;
  ref?: React.Ref<HTMLDivElement>;
}

export const DEMO_ANSWER: Pick<
  GroundedAnswerProps,
  "question" | "claims" | "sources" | "missingEvidence"
> = {
  question: "What is our refund SLA for UPI payments?",
  claims: [
    {
      text: "Refunds for UPI payments must be initiated within 24 hours of the customer request.",
      sourceIds: ["s1"],
      confidence: 0.95,
    },
    {
      text: "Once initiated, the credit reaches the customer in 5–7 working days.",
      sourceIds: ["s1", "s2"],
      confidence: 0.88,
      contradiction:
        "The 2023 help-centre page still says 3–5 days; the 2025 policy supersedes it.",
    },
    {
      text: "For failed (not refunded) UPI transactions, auto-reversal is required within T+1 day.",
      sourceIds: ["s3"],
      confidence: 0.72,
    },
  ],
  sources: [
    { id: "s1", title: "Refund policy v4 (2025)", quote: "UPI refunds: initiate ≤ 24h from request; settlement 5–7 working days.", meta: "policies/refunds.md · updated 12 Mar 2025" },
    { id: "s2", title: "Help centre — refunds", quote: "You'll usually see the money back in 3–5 business days.", meta: "help.acme.in/refunds · 2023, stale" },
    { id: "s3", title: "NPCI circular 129", quote: "Failed transactions shall be auto-reversed within T+1.", meta: "external · applies to failures, not refunds" },
  ],
  missingEvidence: ["No source covers refunds for international UPI (UPI One World)."],
};

/* ------------------------------------------------------------------ */
/* Answer                                                               */
/* ------------------------------------------------------------------ */

/**
 * An answer that shows its work: every claim carries citation chips that
 * light up the exact source and quote, contradictions are called out
 * inline instead of averaged away, and what the sources don't cover is
 * stated plainly.
 */
export function GroundedAnswer({
  question,
  claims = DEMO_ANSWER.claims!,
  sources = DEMO_ANSWER.sources!,
  missingEvidence = DEMO_ANSWER.missingEvidence!,
  onFeedback,
  className,
  ref,
  ...rest
}: GroundedAnswerProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => rootRef.current as HTMLDivElement);

  const [activeSource, setActiveSource] = React.useState<string | null>(null);
  const [feedback, setFeedback] = React.useState<null | boolean>(null);
  const srcIndex = Object.fromEntries(sources.map((s, i) => [s.id, i + 1]));

  /* Claims blur in sequentially, like a considered answer. */
  useGSAP(
    () => {
      const root = rootRef.current;
      if (!root) return;
      const rows = gsap.utils.toArray<HTMLElement>(root.querySelectorAll("[data-claim]"));
      if (reduced) {
        gsap.set(rows, { y: 0, opacity: 1 });
        return;
      }
      gsap.fromTo(
        rows,
        { y: 10, opacity: 0, filter: "blur(5px)" },
        { y: 0, opacity: 1, filter: "blur(0px)", duration: 0.4, ease: "power3.out", stagger: 0.12, clearProps: "filter" }
      );
    },
    { scope: rootRef }
  );

  /* Selecting a citation pulses the matching source card. */
  const focusSource = (id: string) => {
    setActiveSource((s) => (s === id ? null : id));
    if (reduced || !rootRef.current) return;
    const card = rootRef.current.querySelector<HTMLElement>(`[data-source="${id}"]`);
    if (card)
      gsap.fromTo(card, { scale: 1 }, { scale: 1.02, duration: 0.15, yoyo: true, repeat: 1, ease: "power2.out" });
  };

  return (
    <div
      ref={rootRef}
      data-slot="grounded-answer"
      className={cn(
        "w-full max-w-xl rounded-2xl border border-border bg-card p-4",
        className
      )}
      {...rest}
    >
      <p className="text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
        Question
      </p>
      <p className="text-sm font-medium text-foreground">{question}</p>

      {/* Claims */}
      <div className="mt-3 flex flex-col gap-2">
        {claims.map((c, i) => (
          <div
            key={i}
            data-claim
            className={cn(
              "rounded-lg px-3 py-2 text-[13px] leading-6",
              c.confidence < 0.8 ? "bg-warning/5" : "bg-muted/40"
            )}
          >
            <span className="text-foreground">{c.text}</span>{" "}
            {c.sourceIds.map((sid) => (
              <button
                key={sid}
                type="button"
                aria-pressed={activeSource === sid}
                aria-label={`Show source ${srcIndex[sid]}`}
                onClick={() => focusSource(sid)}
                className={cn(
                  "mx-0.5 inline-flex size-4 items-center justify-center rounded align-text-top text-[9px] font-semibold transition-colors duration-200",
                  activeSource === sid
                    ? "bg-primary text-primary-foreground"
                    : "bg-info/15 text-info hover:bg-info/25",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                )}
              >
                {srcIndex[sid]}
              </button>
            ))}
            <span
              className={cn(
                "ml-1 align-middle text-[10px] tabular-nums",
                c.confidence < 0.8 ? "font-medium text-warning" : "text-muted-foreground"
              )}
            >
              {(c.confidence * 100).toFixed(0)}%
            </span>
            {c.contradiction ? (
              <p className="mt-1 border-l-2 border-warning pl-2 text-[11px] leading-4 text-warning">
                Sources disagree: {c.contradiction}
              </p>
            ) : null}
          </div>
        ))}
      </div>

      {/* Missing evidence */}
      {missingEvidence.length > 0 ? (
        <p className="mt-2 rounded-lg border border-dashed border-border px-3 py-1.5 text-[11px] leading-4 text-muted-foreground">
          <span className="font-medium text-foreground">Not covered by any source:</span>{" "}
          {missingEvidence.join(" ")}
        </p>
      ) : null}

      {/* Sources */}
      <p className="mt-3 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
        Sources
      </p>
      <ol className="mt-1.5 flex flex-col gap-1.5">
        {sources.map((s) => (
          <li
            key={s.id}
            data-source={s.id}
            className={cn(
              "rounded-xl border px-3 py-2 transition-colors duration-300",
              activeSource === s.id ? "border-primary bg-primary/5" : "border-border bg-background"
            )}
          >
            <p className="flex items-baseline gap-1.5 text-xs font-medium text-foreground">
              <span className="flex size-4 shrink-0 items-center justify-center rounded bg-info/15 text-[9px] font-semibold text-info">
                {srcIndex[s.id]}
              </span>
              {s.title}
            </p>
            <p className="mt-0.5 text-[11px] italic leading-4 text-muted-foreground">
              “{s.quote}”
            </p>
            <p className="mt-0.5 text-[10px] text-muted-foreground">{s.meta}</p>
          </li>
        ))}
      </ol>

      {/* Feedback */}
      <div className="mt-3 flex items-center justify-between border-t border-border pt-2">
        <span className="text-[10px] text-muted-foreground">
          Confidence is per claim, not per answer — low-confidence claims are tinted.
        </span>
        <div className="flex gap-1" aria-live="polite">
          {feedback === null ? (
            (["yes", "no"] as const).map((v) => (
              <button
                key={v}
                type="button"
                aria-label={v === "yes" ? "Helpful" : "Not helpful"}
                onClick={() => {
                  setFeedback(v === "yes");
                  onFeedback?.(v === "yes");
                }}
                className="rounded-md border border-border px-2 py-1 text-[11px] text-muted-foreground transition-colors duration-200 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                {v === "yes" ? "Helpful" : "Not helpful"}
              </button>
            ))
          ) : (
            <span className="text-[11px] text-success">Thanks — recorded.</span>
          )}
        </div>
      </div>
    </div>
  );
}

registry/default/blocks/signup-card.tsx:
"use client";

import * as React from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { cn } from "@/lib/utils";
import { useReducedMotion } from "@/registry/default/lib/use-reduced-motion";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import { Field } from "@/registry/default/ui/field";
import { Checkbox } from "@/registry/default/ui/checkbox";
import { Alert } from "@/registry/default/ui/alert";

export interface SignupCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit" | "title"> {
  onSubmit: (data: {
    name: string;
    email: string;
    password: string;
  }) => Promise<void>;
  onOAuth?: (provider: "google" | "github") => void;
  title?: string;
  loginHref?: string;
  ref?: React.Ref<HTMLDivElement>;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type FieldName = "name" | "email" | "password" | "terms";

const MESSAGES: Record<FieldName, string> = {
  name: "Enter your name",
  email: "Enter a valid email address",
  password: "Password must be at least 8 characters",
  terms: "Accept the terms to continue",
};

function passwordLevel(pw: string): number {
  if (pw.length < 8) return pw.length > 0 ? 1 : 0;
  let level = 1;
  if (/[a-z]/.test(pw) && /[A-Z]/.test(pw)) level++;
  if (/\d/.test(pw)) level++;
  if (/[^a-zA-Z0-9]/.test(pw)) level++;
  return level;
}

const LEVEL_LABELS = ["", "Weak", "Fair", "Good", "Strong"];

function levelColor(level: number): string {
  if (level >= 3) return "bg-emerald-500";
  if (level === 2) return "bg-amber-500";
  if (level === 1) return "bg-destructive";
  return "bg-muted";
}

function GoogleMark() {
  return (
    <svg viewBox="0 0 24 24" className="size-4" aria-hidden="true">
      <path
        fill="currentColor"
        d="M21.6 12.2c0-.7-.1-1.4-.2-2H12v3.9h5.4a4.6 4.6 0 0 1-2 3v2.5h3.2c1.9-1.7 3-4.3 3-7.4Z"
        opacity="0.9"
      />
      <path
        fill="currentColor"
